state over = false;

fn start() {
  for i in 0..6 {
    ix[i] = 2 + (i % 3) * 4;
    iy[i] = 1 + i / 3;
    alive[i] = true;
  }
  shield = [2, 3, 11, 12];
  dir = 1;
  cx = 7;
  sy = -1;
  by = -1;
  ticks = 0;
  score = 0;
  lives = 3;
  won = false;
  over = false;
  speed = 100;
}

fn stop() {
  speed = 0;
  sy = -1;
  by = -1;
}

// The shield square at (x, y), or -1.
fn shieldAt(x: int, y: int) -> int {
  if y == 9 {
    for k in 0..4 {
      if shield[k] == x { return k; }
    }
  }
  return -1;
}

fn count() -> int {
  let n = 0;
  for i in 0..6 {
    if alive[i] { n += 1; }
  }
  return n;
}

// The shot on a shield or an invader.
fn hit() {
  if sy < 0 { return; }
  let k = shieldAt(sx, sy);
  if k >= 0 {
    shield[k] = -1;
    sy = -1;
    return;
  }
  for i in 0..6 {
    if sy >= 0 && alive[i] && ix[i] == sx && iy[i] == sy {
      alive[i] = false;
      sy = -1;
      score += 10;
      if count() == 0 {
        won = true;
        stop();
      }
    }
  }
}

// The bomb on a shield or the cannon, or past the bottom.
fn bombed() {
  if by < 0 { return; }
  let k = shieldAt(bx, by);
  if by > 11 {
    by = -1;
  } else if k >= 0 {
    shield[k] = -1;
    by = -1;
  } else if by == 11 && bx == cx {
    by = -1;
    lives -= 1;
    if lives == 0 {
      over = true;
      stop();
    }
  }
}

// One march, then a bomb from the lowest invader over the cannon.
fn march() {
  let edge = false;
  for i in 0..6 {
    if alive[i] && (ix[i] + dir < 0 || ix[i] + dir > 15) { edge = true; }
  }
  for i in 0..6 {
    if edge { iy[i] += 1; } else { ix[i] += dir; }
    if alive[i] && iy[i] >= 11 {
      over = true;
      stop();
    }
  }
  if edge { dir = -dir; }
  hit();
  let low = -1;
  for i in 0..6 {
    if alive[i] && ix[i] == cx { low = max(low, iy[i]); }
  }
  if speed > 0 && by < 0 && low >= 0 {
    bx = cx;
    by = low + 1;
    bombed();
  }
}

fn fire() {
  if speed > 0 && sy < 0 {
    sx = cx;
    sy = 10;
    hit();
  }
}

fn steer(d: int) {
  if speed > 0 {
    cx = min(15, max(0, cx + d));
    bombed();
  }
}

every speed {
  ticks += 1;
  if sy >= 0 {
    sy -= 1;
    hit();
  }
  if by >= 0 {
    by += 1;
    bombed();
  }
  if speed > 0 && ticks % 10 == 0 { march(); }
}

