// Whether a floor is at (x, y).
fn floor(x: int, y: int) -> bool {
  if y == 11 { return true; }
  if y == 8 || y == 2 { return x >= 1; }
  if y == 5 { return x <= 10; }
  return false;
}

// Whether (x, y) is on a ladder's way: from the row under it to the row above it.
fn ladder(x: int, y: int) -> bool {
  return (x == 2 && y >= 7 && y <= 10) || (x == 9 && y >= 4 && y <= 7) || (x == 4 && y >= 1 && y <= 4);
}

fn barrel() {
  push(bx, 11);
  push(by, 1);
  push(bd, -1);
  push(bf, false);
}

fn start() {
  clear(bx);
  clear(by);
  clear(bd);
  clear(bf);
  barrel();
  px = 5;
  py = 10;
  ticks = 0;
  lives = 3;
  won = false;
  over = false;
  speed = 200;
}

fn drop(i: int) {
  remove(bx, i);
  remove(by, i);
  remove(bd, i);
  remove(bf, i);
}

// A barrel on the player: that barrel gone, a life lost, the player back at the start.
fn hit() {
  for i in 0..len(bx) {
    if i < len(bx) && bx[i] == px && by[i] == py {
      drop(i);
      lives -= 1;
      px = 5;
      py = 10;
      if lives == 0 {
        over = true;
        speed = 0;
      }
    }
  }
}

fn walk(dx: int, dy: int) {
  let nx = px + dx;
  let ny = py + dy;
  if speed == 0 { return; }
  let ok = dy == 0 && py % 3 == 1 && nx >= 0 && nx <= 11 && floor(nx, py + 1);
  if ok || (dx == 0 && ladder(px, py) && ladder(nx, ny)) {
    px = nx;
    py = ny;
    hit();
    if px == 6 && py == 1 {
      won = true;
      speed = 0;
    }
  }
}

every speed {
  ticks += 1;
  for i in 0..len(bx) {
    if !floor(bx[i], by[i] + 1) {
      by[i] += 1;
      bf[i] = true;
    } else {
      if bf[i] { bd[i] = -bd[i]; }
      bf[i] = false;
      bx[i] += bd[i];
    }
  }
  if len(bx) > 0 && (bx[0] < 0 || bx[0] > 11) { drop(0); }
  if ticks % 12 == 0 { barrel(); }
  hit();
}

