// Calculator: tap digits, then + - x or /, then =; C clears. Whole numbers, worked left to right.
// icon: loop 5 2 19 2 19 22 5 22 fill 8 5 16 5 16 9 8 9 line 8 16 12 16 line 10 14 10 18 line 13 16 17 16
state acc = 0;            // the result so far
state cur = 0;            // the number being typed
state op = "";            // the operation waiting for its second number
state typing = false;     // whether a number is being typed
state err = false;        // a division by 0, or a result too big to show

fn display() -> string {
  if err { return "Error"; }
  if typing { return "" + cur; }
  return "" + acc;
}

// The waiting operation worked on what is kept and what was typed.
fn work() {
  let big = 999999999999;
  if op == "+" {
    acc += cur;
  } else if op == "-" {
    acc -= cur;
  } else if op == "x" {
    if cur != 0 && abs(acc) > big / abs(cur) { err = true; } else { acc = acc * cur; }
  } else if op == "/" {
    if cur == 0 { err = true; } else { acc = acc / cur; }
  }
  if abs(acc) > big { err = true; }
}

fn digit(d: int) {
  if err { return; }
  if !typing {
    cur = 0;
    typing = true;
  }
  if cur < 100000000 { cur = cur * 10 + d; }
}

fn operation(o: string) {
  if err { return; }
  if typing {
    if op == "" { acc = cur; } else { work(); }
    typing = false;
  }
  op = o;
}

fn equals() {
  if err { return; }
  if typing {
    if op == "" { acc = cur; } else { work(); }
  }
  typing = false;
  op = "";
}

fn reset() {
  acc = 0;
  cur = 0;
  op = "";
  typing = false;
  err = false;
}

