// decimal.
// icon: loop 2 9 7 9 7 15 2 15 fill 9 9 14 9 14 15 9 15 loop 16 9 21 9 21 15 16 15
state bits = [0; 8];      // 4 (blue) on, 0 off; 128 on the left
state worth = [128, 64, 32, 16, 8, 4, 2, 1];

fn value() -> int {
  let v = 0;
  for i in 0..8 {
    if bits[i] > 0 { v += worth[i]; }
  }
  return v;
}

fn binary() -> string {
  let s = "";
  for i in 0..8 {
    if bits[i] > 0 { s = s + "1"; } else { s = s + "0"; }
  }
  return s;
}

// The bits of v, 0 to 255.
fn set(v: int) {
  for i in 0..8 {
    if v / worth[i] % 2 == 1 { bits[i] = 4; } else { bits[i] = 0; }
  }
}

