    for i in 0..4 {
      let j = i + random(10 - i);
      let t = ds[i];
      ds[i] = ds[j];
      ds[j] = t;
      n = n * 10 + ds[i];
    }
    secret = n;
  }
  clear(said);
  clear(bulls);
  clear(cows);
  bad = false;
  over = 0;
}

fn scored(k: int) -> string {
  let i = len(said) - 1 - k;
  return said[i] + "   Bulls: " + bulls[i] + "  Cows: " + cows[i];
}

