fn left() -> int { return rows[0] + rows[1] + rows[2] + rows[3]; }

// A tap on square (c, r) takes the match there and those to its right.
fn take(c: int, r: int) {
  if winner > 0 || c >= rows[r] { return; }
  rows[r] = c;
  if left() == 0 { winner = player; } else { player = 3 - player; }
