  for i in 0..25 {
    let c = i % 5;
    let r = i / 5;
    if link(i) && r % 2 == 0 { line(c * 20, r * 20 + 10, c * 20 + 20, r * 20 + 10, 1, 10); }
    if link(i) && r % 2 == 1 { line(c * 20 + 10, r * 20, c * 20 + 10, r * 20 + 20, 1, 10); }
  }
  let b = [-1; 25];
  for i in 0..25 {
    if drawn[i] || (i % 5 % 2 == 0 && i / 5 % 2 == 0) {
      b[i] = 8;
    } else if owner[i] == 1 {
      b[i] = 1;
    } else if owner[i] == 2 {
      b[i] = 4;
    }
  }
  pixels(b, 0, 0, 5, 20);
}

