  for i in 0..21 {
    line(i * 8, 0, i * 8, 160, 1, 8);
    line(0, i * 8, 160, i * 8, 1, 8);
  }
  let b = [-1; 400];
  for i in 0..400 {
    if live[i] { b[i] = 2; }
  }
  pixels(b, 0, 0, 20, 8);
}

