// Life on a board whose edges wrap around: Step (or space) moves a generation; new squares are
// green, older ones blue. Tap to bring a square to life or kill it; Reset brings the glider back.
// icon: fill 9 3 15 3 15 9 9 9 fill 15 9 21 9 21 15 15 15 fill 3 15 9 15 9 21 3 21 fill 9 15 15 15 15 21 9 21 fill 15 15 21 15 21 21 15 21
state cells = [1, 14, 24, 25, 26];    // the live squares, row * 12 + column: a glider at first
state old = [false; 5];               // whether each has lived through a step
state generation = 0;
state stable = false;                 // the last step left the same squares alive

// Each live square adds one to each of its 8 neighbours, across the edges; then the rules.
fn step() {
  let near = [0; 144];
  let alive = [false; 144];
  for j in 0..len(cells) {
    let i = cells[j];
    alive[i] = true;
    for dr in 11..14 {
      for dc in 11..14 {
        let k = ((i / 12 + dr) % 12) * 12 + (i % 12 + dc) % 12;
        if k != i { near[k] += 1; }
      }
    }
  }
  clear(cells);
  clear(old);
  stable = true;
  for i in 0..144 {
    if alive[i] && (near[i] == 2 || near[i] == 3) {
      push(cells, i);
      push(old, true);
    } else if !alive[i] && near[i] == 3 {
      push(cells, i);
      push(old, false);
      stable = false;
    } else if alive[i] {
      stable = false;
    }
