];                        // the puzzle, row by row from the top: 0 a blank square
state mine = [0; 81];     // the digits I wrote
state sel = -1;           // the selected square; -1 none
state mistakes = 0;

fn digit(i: int) -> int { return given[i] + mine[i]; }

// Whether d is in another square of square i's row, column or 3 x 3 box.
fn clash(i: int, d: int) -> bool {
  let r = i / 9;
  let c = i % 9;
  for k in 0..9 {
    let b = (r / 3 * 3 + k / 3) * 9 + c / 3 * 3 + k % 3;
    if r * 9 + k != i && digit(r * 9 + k) == d { return true; }
    if k * 9 + c != i && digit(k * 9 + c) == d { return true; }
    if b != i && digit(b) == d { return true; }
  }
  return false;
}

fn left() -> int {
