// Whether ship k fits with its first square at (c, r), a step (dc, dr) at a time.
fn fits(c: int, r: int, dc: int, dr: int, k: int) -> bool {
  for j in 0..sizes[k - 1] {
    let a = c + dc * j;
    let b = r + dr * j;
    if a >= 10 || b >= 10 { return false; }
    if fleet[b * 10 + a] != 0 { return false; }
  }
  return true;
}

// Ship k somewhere at random where it fits.
fn hide(k: int) {
  let done = false;
  repeat 500 {
    if !done {
      let c = random(10);
      let r = random(10);
      let dc = random(2);
      if fits(c, r, dc, 1 - dc, k) {
        for j in 0..sizes[k - 1] { fleet[(r + (1 - dc) * j) * 10 + c + dc * j] = k; }
        done = true;
      }
    }
  }
}

