// Mancala (Kalah) for two: tap a pit of your row to sow its stones counter-clockwise. The last in
// your store plays again; in an empty pit of yours it takes the pit across. Most stones win.
// icon: loop 2 7 22 7 22 17 2 17 ring 7 12 3 ring 12 12 3 ring 17 12 3
state pits = [4, 4, 4, 4, 4, 4, 0, 4, 4, 4, 4, 4, 4, 0];
                          // 0-5 South's row left to right, 6 its store, 7-12 North's row right
                          // to left, 13 its store: the way the stones go round
state turn = 0;           // 0 South, 1 North
state over = false;

fn home(p: int) -> int { return 6 + p * 7; }

// The stones in p's row.
fn side(p: int) -> int {
  let n = 0;
  for k in 0..6 { n += pits[p * 7 + k]; }
  return n;
}

// The pit at column c of row r (0 the top, North's), as an index of pits.
fn spot(c: int, r: int) -> int {
  if r == 1 { return c; }
  return 12 - c;
}

// Pit i's stones, one into each pit on, skipping the other store; then a capture, or the turn
// passes unless the last stone fell in the mover's store.
fn sow(i: int) {
  let p = turn;
  let n = pits[i];
  pits[i] = 0;
  let j = i;
  for k in 0..n {
    j = (j + 1) % 14;
    if j == home(1 - p) { j = (j + 1) % 14; }
    pits[j] += 1;
  }
  if j == home(p) { return; }
  if j / 7 == p && pits[j] == 1 && pits[12 - j] > 0 {
    pits[home(p)] += pits[12 - j] + 1;
    pits[12 - j] = 0;
    pits[j] = 0;
  }
  turn = 1 - p;
}

// A row empty ends the game: each row's stones go to its owner's store.
fn finish() {
  if side(0) > 0 && side(1) > 0 { return; }
  for k in 0..6 {
    pits[6] += pits[k];
    pits[k] = 0;
    pits[13] += pits[7 + k];
    pits[7 + k] = 0;
  }
  over = true;
}

fn tap(i: int) {
  if over || pits[i] == 0 || i / 7 != turn { return; }
  sow(i);
  finish();
}

fn fresh() {
  for k in 0..14 { pits[k] = 4; }
  pits[6] = 0;
  pits[13] = 0;
  turn = 0;
  over = false;
}

// The mover's row lit: its pits silver, the other's gray.
fn shade(r: int) -> int {
  if !over && turn == 1 - r { return 7; }
  return 8;
}

// Pits 20 units apart in two rows, North's store at the left end and South's at the right.
fn scene() {
  rect(0, 0, 160, 60, 3);
  rect(2, 4, 16, 52, 8);
  rect(142, 4, 16, 52, 8);
  text(pits[13], 10, 30, 10, 9);
  text(pits[6], 150, 30, 10, 9);
  for c in 0..6 {
    for r in 0..2 {
      circle(30 + c * 20, 15 + r * 30, 8, shade(r));
      text(pits[spot(c, r)], 30 + c * 20, 15 + r * 30, 8, 9);
    }
  }
}

fn status() -> string {
  if over {
    if pits[6] > pits[13] { return "South wins"; }
    if pits[13] > pits[6] { return "North wins"; }
    return "Draw";
  }
  if turn == 0 { return "South to play"; }
  return "North to play";
}

