// Gomoku against the computer: tap an empty square for a blue stone; red answers at once. Five or
// more in a row, across, down or diagonally, wins.
// icon: line 2 12 22 12 line 12 2 12 22 dot 7 7 4 ring 17 17 4
state board = [0; 169];   // 13 a row, row 0 at the top: 0 empty, 1 mine (blue), 2 its (red)
state result = 0;         // 0 playing, 1 I won, 2 it won, 3 a draw

fn at(c: int, r: int) -> int {
  if c < 0 || c >= 13 || r < 0 || r >= 13 { return -1; }
  return board[r * 13 + c];
}

// How many of p's stones run on from (c, r), a step (dc, dr) at a time, up to 4.
fn run(c: int, r: int, dc: int, dr: int, p: int) -> int {
  let n = 0;
  for k in 1..5 {
    if n == k - 1 && at(c + dc * k, r + dr * k) == p { n = k; }
  }
  return n;
}

// Whether a stone of p at (c, r) makes five or more in a line.
fn fives(c: int, r: int, p: int) -> bool {
  if run(c, r, 1, 0, p) + run(c, r, -1, 0, p) >= 4 { return true; }
  if run(c, r, 0, 1, p) + run(c, r, 0, -1, p) >= 4 { return true; }
  if run(c, r, 1, 1, p) + run(c, r, -1, -1, p) >= 4 { return true; }
  return run(c, r, 1, -1, p) + run(c, r, -1, 1, p) >= 4;
}

// The first empty square, in reading order, where a stone of p makes five; -1 if none.
fn making(p: int) -> int {
  for i in 0..169 {
    if board[i] == 0 {
      if fives(i % 13, i / 13, p) { return i; }
    }
  }
  return -1;
}

// The first empty square next to square i: right, below right, below, below left, left, above
// left, above, above right; else the first empty square of all; -1 when the board is full.
fn near(i: int) -> int {
  let dc = [1, 1, 0, -1, -1, -1, 0, 1];
  let dr = [0, 1, 1, 1, 0, -1, -1, -1];
  for k in 0..8 {
    if at(i % 13 + dc[k], i / 13 + dr[k]) == 0 { return (i / 13 + dr[k]) * 13 + i % 13 + dc[k]; }
  }
  for j in 0..169 {
    if board[j] == 0 { return j; }
  }
  return -1;
}

// Its square: a win, else a block, else next to my last stone.
fn choice(last: int) -> int {
  let i = making(2);
  if i < 0 { i = making(1); }
  if i < 0 { i = near(last); }
  return i;
}

fn tap(i: int) {
  if result != 0 || board[i] != 0 { return; }
  board[i] = 1;
  if fives(i % 13, i / 13, 1) {
    result = 1;
    return;
  }
  let j = choice(i);
  if j < 0 {
    result = 3;
    return;
  }
  board[j] = 2;
  if fives(j % 13, j / 13, 2) {
    result = 2;
  } else if near(j) < 0 {
    result = 3;
  }
}

fn tint(v: int) -> int {
  if v == 1 { return 4; }
  return 1;
}

// Gray squares 10 units apart, each stone a circle in its color.
fn scene() {
  for i in 0..169 {
    let px = (i % 13) * 10;
    let py = (i / 13) * 10;
    rect(px, py, 9, 9, 8);
    if board[i] != 0 { circle(px + 4, py + 4, 4, tint(board[i])); }
  }
}

fn status() -> string {
  if result == 1 { return "You win"; }
  if result == 2 { return "Computer wins"; }
  if result == 3 { return "Draw"; }
  return "Your turn";
}

