  meet(0);
  meet(1);
  if lives == l {
    let i = py * 9 + px;
    if food[i] == 1 { score += 10; }
    if food[i] == 2 {
      score += 50;
      scared = 20;
    }
    food[i] = 0;
    if left() == 0 {
      won = true;
      speed = 0;
    }
    for k in 0..2 {
      if speed > 0 && steps % 2 == 0 && lives == l && alive[k] { chase(k); }
    }
    if scared > 0 { scared -= 1; }
  }
}

