// Billiards for two: left and right turn the aim, up and down set the power, space or Shoot
// shoots. Pot a red to score and shoot again; a miss passes the turn; most points wins.
// icon: ring 12 12 9 dot 9 10 3 dot 15 14 3 line 3 21 9 15
state bx = [2, 8, 7, 9, 3];     // the balls, the cue ball first: square, and whether on the table
state by = [3, 1, 4, 2, 2];
state on = [true, true, true, true, true];
state ways = [0, 1, 1, 1, 0, -1, -1, -1];   // the 8 aims from up, turning right: across
state wayd = [-1, -1, 0, 1, 1, 1, 0, -1];   // and down
state aim = 2;
state power = 4;
state mover = -1;               // the ball rolling (-1: none), its way and the squares left
state dx = 0;
state dy = 0;
state left = 0;
state potted = false;           // what this shot did
state scratched = false;
state pts = [0, 0];
state turn = 0;                 // 0: P1, 1: P2
state speed = 0;                // 100 while a game runs, else 0
state result = "";

fn pocket(c: int, r: int) -> bool { return (c == 0 || c == 5 || c == 10) && (r == 0 || r == 6); }

fn at(c: int, r: int) -> int {
  for i in 0..5 {
    if on[i] && bx[i] == c && by[i] == r { return i; }
  }
  return -1;
}

fn reds() -> int {
  let n = 0;
  for i in 1..5 {
    if on[i] { n += 1; }
  }
  return n;
}

fn start() {
  bx = [2, 8, 7, 9, 3];
  by = [3, 1, 4, 2, 2];
  on = [true, true, true, true, true];
  aim = 2;
  power = 4;
  mover = -1;
  pts = [0, 0];
  turn = 0;
  result = "";
  speed = 100;
}

fn shoot() {
  if speed > 0 && mover < 0 {
    dx = ways[aim];
    dy = wayd[aim];
    left = power;
    potted = false;
    scratched = false;
    mover = 0;
  }
}

// The roll is over: a pot scores and keeps the turn; a scratch gives the other a point.
fn done() {
  mover = -1;
  if potted {
    pts[turn] += 1;
  } else {
    turn = 1 - turn;
    if scratched { pts[turn] += 1; }
  }
  if reds() == 0 {
    speed = 0;
    if pts[0] > pts[1] {
      result = "P1 wins";
    } else if pts[1] > pts[0] {
      result = "P2 wins";
    } else {
      result = "Draw";
    }
  }
}

every speed {
  if mover >= 0 {
    let i = mover;
    if bx[i] + dx < 0 || bx[i] + dx > 10 { dx = -dx; }
    if by[i] + dy < 0 || by[i] + dy > 6 { dy = -dy; }
    let j = at(bx[i] + dx, by[i] + dy);
    if j >= 0 {
      mover = j;
    } else {
      bx[i] += dx;
      by[i] += dy;
      left -= 1;
      if pocket(bx[i], by[i]) {
        if i == 0 {
          bx[0] = 2;
          by[0] = 3;
          scratched = true;
        } else {
          on[i] = false;
          potted = true;
        }
        done();
      } else if left == 0 {
        done();
      }
    }
  }
}

fn turnaim(d: int) {
  if speed > 0 { aim = (aim + d + 8) % 8; }
}

fn setpower(d: int) {
  if speed > 0 { power = min(9, max(1, power + d)); }
}

on key "left" { turnaim(-1); }
