// Sand box: pick Sand, Water, Stone or Erase and tap or drag to paint. Sand piles up and sinks
// through water; water runs into the low places. Pause stops time; Clear empties the box.
// icon: fill 12 4 21 20 3 20 line 3 8 9 8 line 15 10 21 10
state box = [0; 192];       // 16 x 12 squares, row by row: 0 empty, 3 sand, 4 water, 8 stone
state tool = 3;
state speed = 100;          // ms a step; 0 while paused
state names = ["Sand", "Water", "Stone", "Erase"];
state kinds = [3, 4, 8, 0];

// Whether (c, r) is on the board and empty.
fn open(c: int, r: int) -> bool {
  return c >= 0 && c < 16 && r >= 0 && r < 12 && box[r * 16 + c] == 0;
}

// Where the grain or drop on (c, r) moves this step: its square's index, or -1 if it stays.
fn target(c: int, r: int) -> int {
  let i = r * 16 + c;
  if box[i] == 3 {
    if r < 11 && (box[i + 16] == 0 || box[i + 16] == 4) { return i + 16; }
  } else if open(c, r + 1) {
    return i + 16;
  }
  if open(c - 1, r + 1) { return i + 15; }
  if open(c + 1, r + 1) { return i + 17; }
  if box[i] == 4 && open(c - 1, r) { return i - 1; }
  if box[i] == 4 && open(c + 1, r) { return i + 1; }
  return -1;
}

fn count(k: int) -> int {
  let n = 0;
  for i in 0..192 {
    if box[i] == k { n += 1; }
  }
  return n;
}

fn name(k: int) -> string {
  for t in 0..4 {
    if kinds[t] == k { return names[t]; }
  }
  return "";
}

// A step: the rows from the bottom up, each left to right; nothing moves twice.
every speed {
  let moved = [false; 192];
  for j in 0..12 {
    for c in 0..16 {
      let i = (11 - j) * 16 + c;
      if !moved[i] && (box[i] == 3 || box[i] == 4) {
        let t = target(c, 11 - j);
        if t >= 0 {
          let k = box[t];
          box[t] = box[i];
          box[i] = k;
          moved[t] = true;
          moved[i] = true;
        }
      }
    }
  }
}

fn scene() {
  let cells = [-1; 192];
  for i in 0..192 {
    if box[i] > 0 { cells[i] = box[i]; }
  }
  pixels(cells, 0, 0, 16, 10);
}

label "Sand box";
label "Sand " + count(3) + "   Water " + count(4) + "   Painting: " + name(tool);
