// Rush hour: tap a car to pick it, then the arrow keys slide it along its length. Clear the way
// and drive the red car out on the right; Reset starts over.
// icon: fill 3 15 5 9 9 6 15 6 19 9 21 15 dot 8 16 3 dot 16 16 3
// The cars, the red one first: the left or top square of each, whether it lies across, its length.
state cx = [1, 0, 5, 0, 3, 0, 4, 2];
state cy = [2, 0, 0, 1, 1, 4, 4, 5];
state across = [true, true, false, false, false, false, true, true];
state size = [2, 2, 3, 3, 3, 2, 2, 3];
state picked = -1;
state moves = 0;
state won = false;

fn covers(k: int, c: int, r: int) -> bool {
  if across[k] { return r == cy[k] && c >= cx[k] && c < cx[k] + size[k]; }
  return c == cx[k] && r >= cy[k] && r < cy[k] + size[k];
}

// The car on square (c, r), else -1.
fn owner(c: int, r: int) -> int {
  for k in 0..len(cx) {
    if covers(k, c, r) { return k; }
  }
  return -1;
}

fn free(c: int, r: int) -> bool {
  return c >= 0 && c < 6 && r >= 0 && r < 6 && owner(c, r) < 0;
}

// The picked car one square along its length, if the square it moves into is free.
fn slide(dc: int, dr: int) {
  if picked < 0 || won { return; }
  let k = picked;
  if across[k] != (dr == 0) { return; }
  let c = cx[k] + dc;
  let r = cy[k] + dr;
  if dc > 0 { c = cx[k] + size[k]; }
  if dr > 0 { r = cy[k] + size[k]; }
  if !free(c, r) { return; }
  cx[k] += dc;
  cy[k] += dr;
  moves += 1;
  if cx[0] == 4 { won = true; }
}

fn tint(k: int) -> int {
  if k == 0 { return 1; }
  if size[k] == 3 { return 5; }
  return 4;
}

fn reset() {
  cx = [1, 0, 5, 0, 3, 0, 4, 2];
  cy = [2, 0, 0, 1, 1, 4, 4, 5];
  picked = -1;
  moves = 0;
  won = false;
}

// Squares of 20 units: the cars in their colors, the picked one outlined, the exit marked.
fn scene() {
  let b = [-1; 36];
  for k in 0..len(cx) {
    for i in 0..size[k] {
      if across[k] { b[cy[k] * 6 + cx[k] + i] = tint(k); } else { b[(cy[k] + i) * 6 + cx[k]] = tint(k); }
    }
  }
  pixels(b, 0, 0, 6, 20);
  rect(118, 40, 2, 20, 11);
  if picked >= 0 {
    let w = 20;
    let h = 20;
    if across[picked] { w = size[picked] * 20; } else { h = size[picked] * 20; }
    let x = cx[picked] * 20;
    let y = cy[picked] * 20;
    line(x + 1, y + 1, x + w - 1, y + 1, 2, 9);
    line(x + 1, y + h - 1, x + w - 1, y + h - 1, 2, 9);
    line(x + 1, y + 1, x + 1, y + h - 1, 2, 9);
    line(x + w - 1, y + 1, x + w - 1, y + h - 1, 2, 9);
  }
  if won { text("You win", 60, 60, 16, 9); }
}

