fn fits(t: int) -> bool {
  return left < 0 || t / 10 == left || t % 10 == left || t / 10 == right || t % 10 == right;
}

// Whether who (0 me, 1 the computer) holds a tile that fits.
fn can(who: int) -> bool {
  for k in 0..7 {
    if who == 0 && k < len(mine) && fits(mine[k]) { return true; }
    if who == 1 && k < len(its) && fits(its[k]) { return true; }
  }
  return false;
}

fn pips(who: int) -> int {
  let n = 0;
  for k in 0..7 {
    if who == 0 && k < len(mine) { n += mine[k] / 10 + mine[k] % 10; }
    if who == 1 && k < len(its) { n += its[k] / 10 + its[k] % 10; }
  }
  return n;
}

// Tile t on the line: the first as it is, then on the left end if it matches it, else the right;
// the end it lands on becomes its other number.
fn lay(t: int) {
  let a = t / 10;
  let b = t % 10;
  if left < 0 {
    left = a;
    right = b;
    push(chain, t);
  } else if a == left || b == left {
    if a == left { left = b; } else { left = a; }
    insert(chain, 0, left * 10 + a + b - left);
  } else {
    if a == right { right = b; } else { right = a; }
    push(chain, (a + b - right) * 10 + right);
  }
}

// The end of the hand: who won (0 me, 1 the computer, -1 blocked) and the points.
fn end(who: int) {
  let w = who;
  if w < 0 && pips(0) < pips(1) { w = 0; }
  if w < 0 && pips(1) < pips(0) { w = 1; }
  over = true;
  result = "Draw";
  if w == 0 {
    result = "You win";
    points = pips(1);
  }
  if w == 1 {
    result = "Computer wins";
    points = pips(0);
  }
}

// The computer plays its first tile that fits, if any.
fn reply() {
  for k in 0..7 {
    if k < len(its) && fits(its[k]) {
      lay(its[k]);
      remove(its, k);
      return;
    }
  }
}

// My tile k, then the computer's turn, again while I cannot play, until one can or neither can.
fn play(k: int) {
  if over || k >= len(mine) || !fits(mine[k]) { return; }
  lay(mine[k]);
  remove(mine, k);
  if len(mine) == 0 {
    end(0);
    return;
  }
  let done = false;
  repeat 14 {
    if !over && !done {
      reply();
      if len(its) == 0 {
        end(1);
      } else if can(0) {
        done = true;
      } else if !can(1) {
        end(-1);
      }
    }
  }
}

fn fresh() {
  clear(mine);
  clear(its);
  clear(chain);
  for k in 0..7 {
    push(mine, deal[k]);
    push(its, deal[k + 7]);
  }
  left = -1;
  right = -1;
  over = false;
  result = "";
  points = 0;
}

