// Dominoes, all fives, against the computer: the keys 1 to 9 play your tiles from the left, Draw
// takes one from the boneyard. Ends adding up to 5, 10, 15 or 20 score them. The deal is fixed.
// icon: loop 3 7 21 7 21 17 3 17 line 12 7 12 17 dot 7 12 2 dot 16 10 2 dot 18 14 2
state deal = [10, 24, 53, 14, 40, 31, 5, 46, 63, 45, 62, 23, 15, 44, 20, 61, 33, 11, 0, 22, 34, 65,
  25, 66, 3, 12, 60, 55];  // each tile as tens and ones (65 is 6|5, 5 is 0|5): mine the first 7,
                           // its the next 7, then the boneyard
state mine = [0; 0];
state its = [0; 0];
state yard = [0; 0];
state chain = [0; 0];     // the line of play, left to right, each tile turned as it lies
state left = -1;          // the open ends; -1 before the first tile
state right = -1;
state over = false;
state result = "";
state score = [0, 0];     // mine, its

fn fits(t: int) -> bool {
  return left < 0 || t / 10 == left || t % 10 == left || t / 10 == right || t % 10 == right;
}

// Whether who (0 me, 1 the computer) holds a tile that fits.
fn can(who: int) -> bool {
  for k in 0..28 {
    if who == 0 && k < len(mine) && fits(mine[k]) { return true; }
    if who == 1 && k < len(its) && fits(its[k]) { return true; }
  }
  return false;
}

fn pips(who: int) -> int {
  let n = 0;
  for k in 0..28 {
    if who == 0 && k < len(mine) { n += mine[k] / 10 + mine[k] % 10; }
    if who == 1 && k < len(its) { n += its[k] / 10 + its[k] % 10; }
  }
  return n;
}

// Tile t on the line, laid by who: the first as it is, then on the left end if it matches it, else
// the right; the end it lands on becomes its other number. Ends adding up to a multiple of 5 score.
fn lay(t: int, who: int) {
  let a = t / 10;
  let b = t % 10;
  if left < 0 {
    left = a;
    right = b;
    push(chain, t);
  } else if a == left || b == left {
    if a == left { left = b; } else { left = a; }
    insert(chain, 0, left * 10 + a + b - left);
  } else {
    if a == right { right = b; } else { right = a; }
    push(chain, (a + b - right) * 10 + right);
  }
  if (left + right) % 5 == 0 { score[who] += left + right; }
}

// The end of the hand: who won (0 me, 1 the computer, -1 blocked) and the points.
fn end(who: int) {
  let w = who;
  if w < 0 && pips(0) < pips(1) { w = 0; }
  if w < 0 && pips(1) < pips(0) { w = 1; }
  over = true;
  result = "Draw";
  if w == 0 {
    result = "You win";
    score[0] += pips(1);
  }
  if w == 1 {
    result = "Computer wins";
    score[1] += pips(0);
  }
}

// The computer draws from the boneyard until a tile fits, then plays its first tile that fits.
fn reply() {
  repeat 14 {
    if !can(1) && len(yard) > 0 {
      push(its, yard[0]);
      remove(yard, 0);
    }
  }
  for k in 0..28 {
    if k < len(its) && fits(its[k]) {
      lay(its[k], 1);
      remove(its, k);
      return;
    }
  }
}

// The computer's turn, again while I can neither play nor draw, until I can or neither can play.
fn turns() {
  let done = false;
  repeat 30 {
    if !over && !done {
      reply();
      if len(its) == 0 {
        end(1);
      } else if can(0) || len(yard) > 0 {
        done = true;
      } else if !can(1) {
        end(-1);
      }
    }
  }
}

// My tile k, then the computer's turn.
fn play(k: int) {
  if over || k >= len(mine) || !fits(mine[k]) { return; }
  lay(mine[k], 0);
  remove(mine, k);
  if len(mine) == 0 { end(0); } else { turns(); }
}

// A tile from the boneyard when none of mine fits; if still none fits and it is empty, I pass.
fn draw() {
  if over || can(0) || len(yard) == 0 { return; }
  push(mine, yard[0]);
  remove(yard, 0);
  if !can(0) && len(yard) == 0 { turns(); }
}

fn fresh() {
  clear(mine);
  clear(its);
  clear(chain);
  clear(yard);
  for k in 0..7 {
    push(mine, deal[k]);
    push(its, deal[k + 7]);
  }
  for k in 14..28 { push(yard, deal[k]); }
  left = -1;
  right = -1;
  over = false;
  result = "";
  score[0] = 0;
  score[1] = 0;
}

// A tile at x, y: two squares with its numbers.
fn tile(t: int, x: int, y: int, c: int) {
  rect(x, y, 18, 10, c);
  line(x + 9, y, x + 9, y + 10, 1, 9);
  text(t / 10, x + 4, y + 5, 7, 9);
  text(t % 10, x + 14, y + 5, 7, 9);
}

// The line of play in rows of 8, my hand along the bottom in rows of 7.
fn scene() {
  for k in 0..len(chain) { tile(chain[k], 2 + (k % 8) * 20, 2 + (k / 8) * 12, 7); }
  for k in 0..len(mine) { tile(mine[k], 2 + (k % 7) * 22, 52 + (k / 7) * 12, 3); }
}

