// Go on 9 x 9 for two: tap a point to play, Black first; Pass passes, and two passes end the game.
// Stones and the empty points only they surround score; White adds 7.
// icon: line 3 8 21 8 line 3 16 21 16 line 8 3 8 21 line 16 3 16 21 dot 8 8 4 ring 16 16 4
state board = [0; 81];    // row by row from the top: 0 empty, 1 black, 2 white
state before = [0; 81];   // the board as this move began
state last = [0; 81];     // the board as the other player's last move began (ko)
state turn = 1;
state passes = 0;
state over = false;

// The neighbor of point i a step d (0 left, 1 right, 2 up, 3 down) away, or -1 off the board.
fn step(i: int, d: int) -> int {
  let c = i % 9;
  let r = i / 9;
  if d == 0 && c > 0 { return i - 1; }
  if d == 1 && c < 8 { return i + 1; }
  if d == 2 && r > 0 { return i - 9; }
  if d == 3 && r < 8 { return i + 9; }
  return -1;
}

// Whether the group of stones at i has a liberty: a search over its stones.
fn free(i: int) -> bool {
  let p = board[i];
  let seen = [false; 81];
  let todo = [i];
  seen[i] = true;
  let at = 0;
  repeat 81 {
    if at < len(todo) {
      let j = todo[at];
      at += 1;
      for d in 0..4 {
        let k = step(j, d);
        if k >= 0 && board[k] == 0 { return true; }
        if k >= 0 && board[k] == p && !seen[k] {
          seen[k] = true;
          push(todo, k);
        }
      }
    }
  }
  return false;
}

// Takes the group of stones at i off the board.
fn take(i: int) {
  let p = board[i];
  let todo = [i];
  board[i] = 0;
  let at = 0;
  repeat 81 {
    if at < len(todo) {
      let j = todo[at];
      at += 1;
      for d in 0..4 {
        let k = step(j, d);
        if k >= 0 && board[k] == p {
          board[k] = 0;
          push(todo, k);
        }
      }
    }
  }
}

fn same() -> bool {
  for i in 0..81 {
    if board[i] != last[i] { return false; }
  }
  return true;
}

// A stone at i; the other's groups it leaves without a liberty are taken. A move that leaves its
// own group none, or brings back the board of before the other's last move, is taken back.
fn play(i: int) {
  if over || board[i] != 0 { return; }
  for k in 0..81 { before[k] = board[k]; }
  board[i] = turn;
  for d in 0..4 {
    let k = step(i, d);
    if k >= 0 && board[k] == 3 - turn && !free(k) { take(k); }
  }
  if !free(i) || same() {
    for k in 0..81 { board[k] = before[k]; }
    return;
  }
  for k in 0..81 { last[k] = before[k]; }
  turn = 3 - turn;
  passes = 0;
}

fn pass() {
  if over { return; }
  for k in 0..81 { last[k] = board[k]; }
  turn = 3 - turn;
  passes += 1;
  over = passes >= 2;
}

// p's area: its stones, and each empty region whose border holds only p's stones.
fn area(p: int) -> int {
  let n = 0;
  let seen = [false; 81];
  for i in 0..81 {
    if board[i] == p { n += 1; }
    if board[i] == 0 && !seen[i] {
      let todo = [i];
      seen[i] = true;
      let at = 0;
      let mine = false;
      let theirs = false;
      repeat 81 {
        if at < len(todo) {
          let j = todo[at];
          at += 1;
          for d in 0..4 {
            let k = step(j, d);
            if k >= 0 && board[k] == 0 && !seen[k] {
              seen[k] = true;
              push(todo, k);
            }
            if k >= 0 && board[k] == p { mine = true; }
            if k >= 0 && board[k] == 3 - p { theirs = true; }
          }
        }
      }
      if mine && !theirs { n += len(todo); }
    }
  }
  return n;
}

fn fresh() {
  for k in 0..81 {
    board[k] = 0;
    last[k] = 0;
  }
  turn = 1;
  passes = 0;
  over = false;
}

// Lines through the middles of 9 x 9 squares of 20 units; black stones ink, white silver.
fn scene() {
  rect(0, 0, 180, 180, 3);
  for k in 0..9 {
    line(10, 10 + k * 20, 170, 10 + k * 20, 1, 10);
    line(10 + k * 20, 10, 10 + k * 20, 170, 1, 10);
