// Nine men's morris for two: tap points to place your 9 pieces, then tap a piece and a point next to
// it to move. Three in a line removes a piece of the other's; with 3 left, fly; down to 2 loses.
// icon: loop 3 3 21 3 21 21 3 21 loop 8 8 16 8 16 16 8 16 line 12 3 12 8 dot 3 12 2 dot 21 12 2
state mills = [0, 3, 6, 8, 10, 12, 16, 17, 18, 21, 22, 23, 25, 26, 27, 30, 31, 32, 36, 38, 40, 42,
  45, 48, 0, 21, 42, 8, 22, 36, 16, 23, 30, 3, 10, 17, 31, 38, 45, 18, 25, 32, 12, 26, 40, 6, 27,
  48];                    // the 16 lines of three, as squares of the 7 x 7 board (row * 7 + column)
state board = [0; 49];    // 0 empty, 1 red, 2 blue
state hand = [0, 9, 9];   // pieces left to place: red, blue
state turn = 1;
state taking = false;     // whether the player to play removes a piece
state picked = -1;        // the piece picked to move
state winner = 0;

fn point(i: int) -> bool {
  for k in 0..48 {
    if mills[k] == i { return true; }
  }
  return false;
}

// Whether the piece at i is in a line of three of its color.
fn inmill(i: int) -> bool {
  let p = board[i];
  for m in 0..16 {
    let a = mills[m * 3];
    let b = mills[m * 3 + 1];
    let c = mills[m * 3 + 2];
    if p != 0 && board[a] == p && board[b] == p && board[c] == p && (a == i || b == i || c == i) {
      return true;
    }
  }
  return false;
}

// Whether points a and b are next to each other on a line.
fn near(a: int, b: int) -> bool {
  for m in 0..16 {
    for k in 0..2 {
      let x = mills[m * 3 + k];
      let y = mills[m * 3 + k + 1];
      if (x == a && y == b) || (x == b && y == a) { return true; }
    }
  }
  return false;
}

fn count(p: int) -> int {
  let n = 0;
  for i in 0..49 {
    if board[i] == p { n += 1; }
  }
  return n;
}

// Whether every piece of p is in a line of three.
fn allmill(p: int) -> bool {
  for i in 0..49 {
    if board[i] == p && !inmill(i) { return false; }
  }
  return true;
}

// Whether p has a move: with 3 pieces any empty point will do, else one next to a piece.
fn canmove(p: int) -> bool {
  for a in 0..49 {
    if board[a] == p {
      for b in 0..49 {
        if board[b] == 0 && point(b) && (count(p) == 3 || near(a, b)) { return true; }
      }
    }
  }
  return false;
}

// The other's turn; it loses if down to 2 pieces, or if it has none to place and cannot move.
fn pass() {
  turn = 3 - turn;
  picked = -1;
  if count(turn) + hand[turn] < 3 || (hand[turn] == 0 && !canmove(turn)) { winner = 3 - turn; }
}

// After a piece lands on i: a new line of three removes a piece of the other's, else the turn passes.
fn landed(i: int) {
  if inmill(i) && count(3 - turn) > 0 { taking = true; } else { pass(); }
}

fn tap(i: int) {
  if winner != 0 || !point(i) { return; }
  if taking {
    if board[i] == 3 - turn && (!inmill(i) || allmill(3 - turn)) {
      board[i] = 0;
      taking = false;
      pass();
    }
  } else if hand[turn] > 0 {
    if board[i] == 0 {
      board[i] = turn;
      hand[turn] -= 1;
      landed(i);
    }
  } else if board[i] == turn {
    picked = i;
  } else if board[i] == 0 && picked >= 0 && (near(picked, i) || count(turn) == 3) {
    board[picked] = 0;
    board[i] = turn;
    picked = -1;
    landed(i);
  }
}

fn fresh() {
  for i in 0..49 { board[i] = 0; }
  hand[1] = 9;
  hand[2] = 9;
  turn = 1;
  taking = false;
  picked = -1;
  winner = 0;
}

fn tint(p: int) -> int {
  if p == 1 { return 1; }
  return 4;
}

// The lines, a dot on each point, the pieces as discs; the picked one ringed.
fn scene() {
  for m in 0..16 {
    let a = mills[m * 3];
    let c = mills[m * 3 + 2];
    line(10 + (a % 7) * 20, 10 + (a / 7) * 20, 10 + (c % 7) * 20, 10 + (c / 7) * 20, 1, 10);
  }
  for i in 0..49 {
    let x = 10 + (i % 7) * 20;
    let y = 10 + (i / 7) * 20;
    if point(i) && board[i] == 0 { circle(x, y, 2, 10); }
    if board[i] != 0 { circle(x, y, 7, tint(board[i])); }
    if i == picked { ring(x, y, 9, 2, 11); }
  }
}

fn who(p: int) -> string {
  if p == 1 { return "Red"; }
  return "Blue";
}

fn status() -> string {
  if winner != 0 { return who(winner) + " wins"; }
  if taking { return who(turn) + " to remove a piece"; }
  if hand[turn] > 0 { return who(turn) + " to place"; }
  return who(turn) + " to move";
}

