// Air Hockey: the arrows (or a tap) move your blue mallet in your half; the puck bounces off the
// rails and mallets. Get it into the computer's goal at the top; the first to 3 goals wins.
// icon: ring 12 12 9 dot 12 12 3 line 8 3 16 3 line 8 21 16 21
state mx = 4;                   // my mallet, in rows 7 to 11
state my = 10;
state cx = 4;                   // the computer's, on row 2
state px = 4;                   // the puck: its square and its way across and up or down
state py = 6;
state dx = 1;
state dy = 1;
state me = 0;
state cpu = 0;
state steps = 0;
state speed = 0;                // ms a step; 0 while no game runs
state result = "";

fn serve(d: int) {
  px = 4;
  py = 6;
  dx = 1;
  dy = d;
}

fn start() {
  mx = 4;
  my = 10;
  cx = 4;
  me = 0;
  cpu = 0;
  steps = 0;
  result = "";
  serve(1);
  speed = 100;
}

fn mallet(c: int, r: int) -> bool { return c == mx && r == my || c == cx && r == 2; }

fn mouth(c: int) -> bool { return c >= 3 && c <= 5; }

fn goal(top: bool) {
  if top { me += 1; } else { cpu += 1; }
  if me == 3 || cpu == 3 {
    result = "You win";
    if cpu == 3 { result = "You lose"; }
    speed = 0;
  } else if top {
    serve(-1);
  } else {
    serve(1);
  }
}

every speed {
  steps += 1;
  if px + dx < 0 || px + dx > 8 { dx = -dx; }
  if py + dy < 0 || py + dy > 12 { dy = -dy; }
  if mallet(px + dx, py + dy) {
    dy = -dy;
  } else {
    px += dx;
    py += dy;
    if mouth(px) && py == 0 { goal(true); }
    if mouth(px) && py == 12 { goal(false); }
  }
  if speed > 0 && steps % 2 == 0 && cx != px && !(cx + (px - cx) / abs(px - cx) == px && py == 2) {
    cx += (px - cx) / abs(px - cx);
  }
}

// My mallet a square that way: in my half, never onto the puck.
fn slide(x: int, y: int) {
  let c = mx + x;
  let r = my + y;
  if speed > 0 && c >= 0 && c <= 8 && r >= 7 && r <= 11 && !(c == px && r == py) {
    mx = c;
    my = r;
  }
}

