// icon: fill 5 9 19 9 19 21 5 21 ring 12 6 4 line 9 15 15 15
state dirt = [false; 90];       // dirt on each square, or dug
state rx = [3, 6, 1];           // the rocks
state ry = [2, 5, 2];
state mx = [1, 8];              // the monsters, and whether each is still about
state my = [4, 7];
