state py = 0;
state score = 0;
state lives = 3;
state steps = 0;
state speed = 0;                // ms a step; 0 while no game runs
state result = "";

fn at(c: int, r: int) -> int { return r * 9 + c; }

// The tunnels a game begins with: row 4 at columns 1 to 4, row 7 at columns 4 to 8.
fn tunnel(c: int, r: int) -> bool { return r == 4 && c >= 1 && c <= 4 || r == 7 && c >= 4; }

fn rock(c: int, r: int) -> bool {
  for i in 0..3 {
    if rx[i] == c && ry[i] == r { return true; }
  }
  return false;
}

fn monster(c: int, r: int) -> int {
  for i in 0..2 {
    if alive[i] && mx[i] == c && my[i] == r { return i; }
  }
  return -1;
}

// The digger and the monsters back where they began.
fn home() {
  px = 4;
  py = 0;
  mx = [1, 8];
  my = [4, 7];
}

fn start() {
  for i in 9..90 { dirt[i] = !tunnel(i % 9, i / 9); }
  rx = [3, 6, 1];
  ry = [2, 5, 2];
  for i in 0..3 { dirt[at(rx[i], ry[i])] = false; }
  alive = [true, true];
  home();
  score = 0;
  lives = 3;
  steps = 0;
  result = "";
  speed = 100;
}

fn caught() {
  lives -= 1;
  home();
  if lives == 0 {
    result = "Game over";
    speed = 0;
  }
}

// Whether a monster may move onto (c, r): dug, on the board, no rock or other monster on it.
fn free(c: int, r: int) -> bool {
  return c >= 0 && c < 9 && r >= 0 && r < 10 && !dirt[at(c, r)] && !rock(c, r) && monster(c, r) < 0;
}

fn sign(n: int) -> int { return max(-1, min(1, n)); }

// Monster i a square toward the digger: across first; whether it caught the digger.
fn hunt(i: int) -> bool {
  let dx = sign(px - mx[i]);
  let dy = sign(py - my[i]);
  if dx != 0 && (mx[i] + dx == px && my[i] == py || free(mx[i] + dx, my[i])) {
    mx[i] += dx;
  } else if dy != 0 && (mx[i] == px && my[i] + dy == py || free(mx[i], my[i] + dy)) {
    my[i] += dy;
  }
  return mx[i] == px && my[i] == py;
}

every speed {
