  for i in 0..3 {
    let b = ry[i] + 1;
    if b < 10 && !dirt[at(rx[i], b)] && !rock(rx[i], b) && !(rx[i] == px && b == py) {
      ry[i] = b;
      let m = monster(rx[i], b);
