// The knight across, then up while it has rise, else down unless it stands on a ledge.
fn fly() {
  let c = (kx + way + 12) % 12;
  if !ledge(c, ky) { kx = c; }
  if rise > 0 {
    if ky == 0 || ledge(kx, ky - 1) {
      rise = 0;
    } else {
      ky -= 1;
      rise -= 1;
    }
  } else if !ledge(kx, ky + 1) {
    ky += 1;
  }
}

// Riders next to the knight meet it: the higher wins; on one row both turn.
fn meet() {
  let i = 0;
  for n in 0..len(rx) {
    if i < len(rx) && abs(rx[i] - kx) <= 1 && abs(ry[i] - ky) <= 1 {
      if ky < ry[i] {
        remove(rx, i);
        remove(ry, i);
        remove(rw, i);
        score += 50;
      } else if ky > ry[i] {
        lives -= 1;
        home();
        if lives == 0 {
          result = "Game over";
          speed = 0;
        }
        return;
      } else {
        rw[i] = -rw[i];
        way = -way;
        i += 1;
      }
    } else {
      i += 1;
    }
  }
}

every speed {
