// Zoo Keeper: Start the clock, then tap an animal and one beside it to swap them; lines of 3 or
// more are caught and those above fall. Catch 6 of each kind before the time runs out.
// icon: dot 5 10 3 dot 12 10 3 dot 19 10 3 line 3 17 21 17 line 12 17 12 21
state first = [5, 2, 4, 4, 5, 3,  2, 3, 4, 4, 2, 2,  4, 3, 2, 3, 5, 3,
               4, 2, 2, 3, 4, 4,  5, 3, 5, 4, 5, 3,  3, 2, 5, 2, 5, 5];
state board = [5, 2, 4, 4, 5, 3,  2, 3, 4, 4, 2, 2,  4, 3, 2, 3, 5, 3,
               4, 2, 2, 3, 4, 4,  5, 3, 5, 4, 5, 3,  3, 2, 5, 2, 5, 5];
// 6 x 6 squares, row by row: their colors, 3 lion, 2 frog, 4 penguin, 5 hippo; 0 empty
state hit = [false; 36];    // the squares in a line
state caught = [0, 0, 0, 0, 0, 0];    // by color
state sel = -1;
state time = 60;
state speed = 0;            // ms a tick of the clock: 1000 while it runs
state over = "";            // You win or Time up, once it ends

// Marks a line of three from square i by step d, if one is there.
fn three(i: int, d: int) {
  let a = board[i];
  if a != 0 && board[i + d] == a && board[i + 2 * d] == a {
    hit[i] = true;
    hit[i + d] = true;
    hit[i + 2 * d] = true;
  }
}

// Marks every square in a line; how many.
fn lines() -> int {
  for i in 0..36 { hit[i] = false; }
  for r in 0..6 {
    for c in 0..6 {
      if c < 4 { three(r * 6 + c, 1); }
      if r < 4 { three(r * 6 + c, 6); }
    }
  }
  let n = 0;
  for i in 0..36 {
    if hit[i] { n += 1; }
  }
  return n;
}

// Those in a line are caught; those above fall into the gaps.
fn take() {
  for i in 0..36 {
    if hit[i] {
      caught[board[i]] += 1;
      board[i] = 0;
    }
  }
  for c in 0..6 {
    let w = 5;
    for k in 0..6 {
      let v = board[(5 - k) * 6 + c];
      if v != 0 {
        board[(5 - k) * 6 + c] = 0;
        board[w * 6 + c] = v;
        w -= 1;
      }
    }
  }
}

fn exchange(a: int, b: int) {
  let t = board[a];
  board[a] = board[b];
  board[b] = t;
}

fn won() -> bool {
  for k in 2..6 {
    if caught[k] < 6 { return false; }
  }
  return true;
}

// A swap that makes a line stays, and the lines are caught until none is left.
fn trade(a: int, b: int) {
  exchange(a, b);
  if lines() == 0 {
    exchange(a, b);
    return;
  }
  for k in 0..12 {
    if lines() > 0 { take(); }
  }
  if won() {
    over = "You win";
    speed = 0;
  }
}

fn tap(i: int) {
  if speed == 0 || board[i] == 0 { return; }
  if sel == i {
    sel = -1;
  } else if sel >= 0 && abs(sel % 6 - i % 6) + abs(sel / 6 - i / 6) == 1 {
    trade(sel, i);
    sel = -1;
  } else {
    sel = i;
  }
}

fn reset() {
  for i in 0..36 { board[i] = first[i]; }
  for k in 0..6 { caught[k] = 0; }
  sel = -1;
  time = 60;
  speed = 0;
  over = "";
}

every speed {
  time -= 1;
  if time <= 0 {
    over = "Time up";
    speed = 0;
  }
}

// The board, 6 x 6 squares of 16 units; a ring round the one selected.
fn scene() {
  let cells = [-1; 36];
  for i in 0..36 {
    if board[i] != 0 { cells[i] = board[i]; }
  }
  pixels(cells, 0, 0, 6, 16);
  if sel >= 0 { ring((sel % 6) * 16 + 8, (sel / 6) * 16 + 8, 7, 2, 9); }
  if over != "" { text(over, 48, 48, 14, 11); }
}

label "Zoo Keeper";
label "Time " + time;
label "Lions " + caught[3] + "   Frogs " + caught[2] + "   Penguins " + caught[4] + "   Hippos " + caught[5];
canvas 96, 96, scene() {
