// Crystal run: Start the clock; Buy crystals where they are cheap, Jump (5 credits, 2 ticks) and
// Sell where they are dear. Prices cycle every tick; reach 200 credits by tick 40.
// icon: fill 12 3 18 10 12 21 6 10 line 6 10 18 10
state alpha = [4, 6, 8, 10, 8, 6];
state beta = [12, 10, 8, 6, 8, 10];
state tick = 0;
state credits = 50;
state crystals = 0;
state at = 0;                // 0 docked at Alpha, 1 docked at Beta, 2 in flight
state to = 0;                // where a flight goes
state left = 0;              // ticks of flight to go
state speed = 0;             // ms a tick: 1000 while the clock runs
state over = "";             // You win or Game over, once it ends

fn price(s: int, t: int) -> int {
  if s == 0 { return alpha[t % 6]; }
  return beta[t % 6];
}

fn docked() -> bool { return speed > 0 && at < 2; }

fn buy() {
  if docked() && crystals < 10 && credits >= price(at, tick) {
    credits -= price(at, tick);
    crystals += 1;
  }
}

fn sell() {
  if docked() && crystals > 0 {
    crystals -= 1;
    credits += price(at, tick);
    if credits >= 200 {
      over = "You win";
      speed = 0;
    }
  }
}

fn jump() {
  if docked() && credits >= 5 {
    credits -= 5;
    to = 1 - at;
    at = 2;
    left = 2;
  }
}

fn reset() {
  tick = 0;
  credits = 50;
  crystals = 0;
  at = 0;
  speed = 0;
  over = "";
}

fn where() -> string {
  if at == 0 { return "Docked at Alpha"; }
  if at == 1 { return "Docked at Beta"; }
  return "In flight";
}

every speed {
  tick += 1;
  if at == 2 {
    left -= 1;
    if left == 0 { at = to; }
  }
  if tick >= 40 {
    over = "Game over";
    speed = 0;
  }
}

// The last 13 ticks of both prices: Alpha blue, Beta red, 4 units a credit.
fn scene() {
  for k in 0..5 { line(0, 100 - k * 20, 160, 100 - k * 20, 1, 10); }
  let a = max(0, tick - 12);
  for t in a..tick {
    let x = (t - a) * 12 + 8;
    line(x, 100 - price(0, t) * 4, x + 12, 100 - price(0, t + 1) * 4, 2, 4);
    line(x, 100 - price(1, t) * 4, x + 12, 100 - price(1, t + 1) * 4, 2, 1);
  }
  if over != "" { text(over, 80, 50, 14, 11); }
}

label "Crystal run";
