}

// Island rescue: Start the clock; Chop wood, Fish and Eat, Sleep at night, Light a signal fire
// so it burns when the ship passes at noon. Hunger 20 ends it.
// icon: line 4 20 20 20 line 12 20 12 6 fill 12 6 19 9 12 12 fill 6 18 12 13 18 18
state day = 1;
state hour = 6;
state hunger = 0;
state energy = 10;
state wood = 0;
state fish = 0;
state fire = 0;              // the hours the fire has left
state speed = 0;             // ms an hour: 1000 while the clock runs
state begun = false;
state over = "";             // Rescued or Game over, once it ends

fn night() -> bool { return hour >= 20 || hour <= 5; }

fn awake() -> bool { return speed > 0; }

fn starve() {
  if hunger >= 20 {
    over = "Game over";
    speed = 0;
  }
}

fn work(n: int) -> bool {
  if !awake() || energy < n { return false; }
  energy -= n;
  return true;
}

fn eat() {
  if awake() && fish > 0 {
    fish -= 1;
    hunger = max(0, hunger - 6);
  }
}

fn light() {
  if awake() && wood >= 5 {
    wood -= 5;
    fire = 4;
  }
}

// Asleep until hour 6: rested, hungrier, the fire lower by the hours slept.
fn sleep() {
  if !awake() || !night() { return; }
  let n = (30 - hour) % 24;
  if hour >= 20 { day += 1; }
  hour = 6;
  energy = 10;
  hunger += n;
  fire = max(0, fire - n);
  starve();
}

fn reset() {
  day = 1;
  hour = 6;
  hunger = 0;
  energy = 10;
  wood = 0;
  fish = 0;
  fire = 0;
  speed = 0;
  begun = false;
  over = "";
}

every speed {
  hour += 1;
  if hour == 24 {
    hour = 0;
    day += 1;
  }
  hunger += 1;
  fire = max(0, fire - 1);
  if hour == 12 && fire > 0 {
    over = "Rescued";
    speed = 0;
  } else {
    starve();
  }
}

// The island under a day or night sky, a palm, and the fire while it burns.
