// Pegboard: tap pegs to make the corners of a shape (6 at most), joined in order; Clear empties it.
// icon: loop 5 6 19 4 16 19 6 15 dot 5 6 2 dot 19 4 2 dot 16 19 2 dot 6 15 2
state corners = [0; 0];   // the corners in order, each a peg: row * 5 + column

// The middle of column or row k, in units: pegs are 30 apart.
fn mid(k: int) -> int { return k * 30 + 15; }

fn corner(p: int) -> bool {
  for i in 0..len(corners) {
    if corners[i] == p { return true; }
  }
  return false;
}

// A peg: a small gray dot, or a red one if it is a corner.
fn peg(p: int) {
  if corner(p) {
    circle(mid(p % 5), mid(p / 5), 5, 1);
  } else {
    circle(mid(p % 5), mid(p / 5), 2, 8);
  }
}

fn edge(p: int, q: int) { line(mid(p % 5), mid(p / 5), mid(q % 5), mid(q / 5), 3, 4); }

// The sides first, each corner to the next and the last back to the first; the pegs over them.
fn scene() {
  let n = len(corners);
  for i in 0..n { edge(corners[i], corners[(i + 1) % n]); }
  for p in 0..25 { peg(p); }
}

// The shape's name by its corners, from 3 to 6.
fn named() -> string {
  let n = len(corners);
  if n == 3 { return "Triangle"; }
  if n == 4 { return "Quadrilateral"; }
  if n == 5 { return "Pentagon"; }
  return "Hexagon";
}

fn add(p: int) {
  if len(corners) < 6 && !corner(p) { push(corners, p); }
}

label "Pegboard";
canvas 150, 150, scene() { add(y / 30 * 5 + x / 30); }
label "Corners: " + len(corners);
if len(corners) >= 3 { label named(); }
button "Clear" { clear(corners); }

// Moon month: Next day and Back walk the moon through its 28 days; the label names its phase.
// icon: ring 12 12 9 fill 12 3 17 5 19 9 19 15 17 19 12 21 15 17 16 12 15 7
state day = 0;            // 0 to 27: 0 new moon, 7 first quarter, 14 full, 21 last quarter

fn phase() -> string {
  if day == 0 { return "New moon"; }
  if day < 7 { return "Waxing crescent"; }
  if day == 7 { return "First quarter"; }
  if day < 14 { return "Waxing gibbous"; }
  if day == 14 { return "Full moon"; }
  if day < 21 { return "Waning gibbous"; }
  if day == 21 { return "Last quarter"; }
  return "Waning crescent";
}

// Whether the moon is lit dx half-squares right of its middle and dy below. Its shadow's edge
// runs across each height at the cosine of the month's turn (a full turn in 28 days) times the
// half-width there: from the right limb at new moon, through the middle, to the left limb at
// full moon; waning, mirrored. Compared squared, in thousandths.
fn bright(dx: int, dy: int) -> bool {
  let s = dx;
  if day > 14 { s = -dx; }
  let k = cos(day * 360 / 28);
  let w = 400 - dy * dy;
  if k >= 0 { return s > 0 && s * s * 1000000 > k * k * w; }
  return s >= 0 || s * s * 1000000 < k * k * w;
}

// The moon on 20 x 20 squares of 6 units: outside it nothing, on it yellow where lit, else gray.
fn scene() {
  let sky = [-1; 400];
  for i in 0..400 {
    let dx = i % 20 * 2 - 19;
    let dy = i / 20 * 2 - 19;
    if dx * dx + dy * dy <= 400 {
      sky[i] = 8;
      if bright(dx, dy) { sky[i] = 3; }
    }
  }
  pixels(sky, 0, 0, 20, 6);
}

label "Moon month";
canvas 120, 120, scene();
label "Day: " + day;
label phase();
row {
  button "Back" { day = (day + 27) % 28; }
  button "Next day" { day = (day + 1) % 28; }
}

// Moon phases: Next steps through the moon's eight phases; Hemisphere shows it from the south.
// icon: ring 12 12 9 fill 12 3 16 4 19 7 21 12 19 17 16 20 12 21
state phase = 0;          // 0 new, 2 first quarter, 4 full, 6 last quarter
state south = false;      // seen from the south: mirrored
state names = ["New moon", "Waxing crescent", "First quarter", "Waxing gibbous", "Full moon",
  "Waning gibbous", "Last quarter", "Waning crescent"];

// Whether the moon is lit dx half-squares right of its middle and dy below: from the north it
// waxes on the right, a crescent beyond half the half-width, a gibbous up to half of it past
// the middle.
fn bright(dx: int, dy: int) -> bool {
  let side = dx;          // toward the lit side
  let k = phase;          // 0 new, 1 crescent, 2 quarter, 3 gibbous, 4 full
  if phase > 4 {
    side = -dx;
    k = 8 - phase;
  }
  if south { side = -side; }
  let w = 400 - dy * dy;  // the half-width across at this height, squared
  if k == 0 { return false; }
  if k == 4 { return true; }
  if k == 2 { return side > 0; }
  if k == 1 { return side > 0 && 4 * side * side > w; }
  return side > 0 || 4 * side * side < w;
}

// The moon on 20 x 20 squares of 6 units: outside it nothing, on it yellow where lit, else gray.
fn scene() {
  let sky = [-1; 400];
  for i in 0..400 {
    let dx = i % 20 * 2 - 19;
    let dy = i / 20 * 2 - 19;
    if dx * dx + dy * dy <= 400 {
      sky[i] = 8;
      if bright(dx, dy) { sky[i] = 3; }
    }
  }
  pixels(sky, 0, 0, 20, 6);
}

fn seen() -> string {
  if south { return "Seen from the South"; }
  return "Seen from the North";
}

label "Moon phases";
canvas 120, 120, scene();
label names[phase];
label seen();
row {
  button "Next" { phase = (phase + 1) % 8; }
  button "Hemisphere" { south = !south; }
}

