// Etch-a-sketch: Left, Right, Up and Down move the pen and leave a line behind; Shake wipes it.
// icon: loop 2 3 22 3 22 21 2 21 line 6 14 6 8 12 8 12 12 18 12 dot 5 18 2 dot 19 18 2
state drawn = [false; 192];   // 16 x 12 squares: where the pen has been
state px = 8;                 // the pen's column
state py = 6;                 // and row

fn at(c: int, r: int) -> int { return r * 16 + c; }

// The screen in silver, the line blue, the pen red, squares of 10 units.
fn scene() {
  let b = [7; 192];
  for i in 0..192 {
    if drawn[i] { b[i] = 4; }
  }
  b[at(px, py)] = 1;
  pixels(b, 0, 0, 16, 10);
}

// A step, kept on the screen; the square it leaves is drawn.
fn go(dc: int, dr: int) {
  let c = min(15, max(0, px + dc));
  let r = min(11, max(0, py + dr));
  if c != px || r != py {
    drawn[at(px, py)] = true;
    px = c;
    py = r;
  }
}

