// Sketch: Left, Right, Up and Down move the pen; Pen lifts or lowers it (up, it draws nothing);
// Shake wipes the drawing.
// icon: loop 2 3 22 3 22 21 2 21 line 6 15 6 8 11 8 line 14 13 19 13 dot 19 13 2
state ink = [false; 300];     // 20 x 15 squares: drawn or not
state px = 0;                 // the pen's column
state py = 0;                 // and row
state down = true;            // the pen draws while down

fn at(c: int, r: int) -> int { return r * 20 + c; }

// The screen in silver, the drawing blue, the pen red, squares of 10 units.
fn scene() {
  let b = [7; 300];
  for i in 0..300 {
    if ink[i] { b[i] = 4; }
  }
  b[at(px, py)] = 1;
  pixels(b, 0, 0, 20, 10);
}

// A step, kept on the screen; with the pen down it draws where it was and where it goes.
fn go(dc: int, dr: int) {
  let c = min(19, max(0, px + dc));
  let r = min(14, max(0, py + dr));
  if c == px && r == py { return; }
  if down {
    ink[at(px, py)] = true;
    ink[at(c, r)] = true;
  }
  px = c;
  py = r;
}

fn pen() -> string {
  if down { return "Pen down"; }
  return "Pen up";
}

