// Sleep log: type the hour you went to bed and the hour you woke (0 to 23) and press Add; it
// keeps your nights: the last, the average and the short ones. Clear empties it.
// icon: fill 13 3 7 5 4 11 7 17 13 20 19 18 12 16 10 9 line 15 4 20 4 15 9 20 9
state bed = "";
state woke = "";
state nights = [0; 0];    // each night's hours, in order

// An hour typed: 0 to 23, else -1.
fn hour(s: string) -> int {
  let h = parse(s, -1);
  if h < 0 || h > 23 { return -1; }
  return h;
}

fn total() -> int {
  let t = 0;
  for i in 0..len(nights) { t += nights[i]; }
  return t;
}

fn last() -> int {
  if len(nights) == 0 { return 0; }
  return nights[len(nights) - 1];
}

fn average() -> int {
  if len(nights) == 0 { return 0; }
  return total() / len(nights);
}

fn short() -> int {
  let n = 0;
  for i in 0..len(nights) {
    if nights[i] < 7 { n += 1; }
  }
  return n;
}

// Logs the hours from bed to waking, through midnight when waking is not later.
fn add() {
  let b = hour(bed);
  let w = hour(woke);
  if b < 0 || w < 0 { return; }
  let h = w - b;
  if h <= 0 { h += 24; }
  push(nights, h);
  bed = "";
  woke = "";
}

