// Unit price: type each pack's price in cents and its size in grams; it shows the price per
// 100 g and which pack is cheaper by the gram.
// icon: loop 3 9 10 9 10 21 3 21 loop 14 5 21 5 21 21 14 21 line 4 4 8 4
state price_a = "";
state size_a = "";
state price_b = "";
state size_b = "";

// Cents per 100 g, rounded down; 0 without a size.
fn per(p: string, s: string) -> int {
  let g = parse(s, 0);
  if g <= 0 { return 0; }
  return parse(p, 0) * 100 / g;
}

// Which costs less by the gram: A's price over its size against B's, crossed out of fractions.
fn verdict() -> string {
  let a = parse(price_a, 0);
  let x = parse(size_a, 0);
  let b = parse(price_b, 0);
  let y = parse(size_b, 0);
  if a <= 0 || x <= 0 || b <= 0 || y <= 0 { return "Fill in both packs"; }
  if a * y < b * x { return "A is cheaper"; }
  if a * y > b * x { return "B is cheaper"; }
  return "Same";
}

label "Unit price";
