// Race predictor: type your pace per km in minutes and seconds and pick a race; it shows the
// time you would finish in.
// icon: line 5 21 5 3 line 5 4 19 4 19 12 5 12 fill 5 4 12 4 12 8 5 8 fill 12 8 19 8 19 12 12 12
state mins = "";
state secs = "";
