state names = ["5K", "10K", "Half", "Marathon"];
state metres = [5000, 10000, 21097, 42195];

// Two digits: 5 is 05.
fn two(n: int) -> string {
  if n < 10 { return "0" + n; }
  return "" + n;
}

// The finish in seconds: the pace times the metres over 1,000, rounded down.
fn finish() -> int { return (parse(mins, 0) * 60 + parse(secs, 0)) * metres[race] / 1000; }

// Seconds as hours, minutes and seconds: 6329 is 1:45:29.
fn clock(s: int) -> string { return s / 3600 + ":" + two(s / 60 % 60) + ":" + two(s % 60); }

