// Box breathing: press Start and follow it: breathe in, hold, breathe out and hold, 4 seconds
// each. Stop stops it.
// icon: loop 4 4 20 4 20 20 4 20 dot 20 12 2
state part = 0;           // 0 in, 1 hold, 2 out, 3 hold
state left = 4;           // seconds left of the part
state boxes = 0;
state speed = 0;          // ms a step; 0 while it is stopped
state parts = ["Breathe in", "Hold", "Breathe out", "Hold"];

every speed {
  left -= 1;
  if left == 0 {
    left = 4;
    part = (part + 1) % 4;
    if part == 0 { boxes += 1; }
  }
}

label "Box breathing";
if speed == 0 {
  label "Ready";
  button "Start" {
    part = 0;
    left = 4;
    boxes = 0;
    speed = 1000;
  }
} else {
  label parts[part];
  label "" + left;
  button "Stop" {
    speed = 0;
    boxes = 0;
  }
}
label "Boxes: " + boxes;

// 4-7-8 breathing: set how many breaths with + and -, press Start and follow it: inhale for 4
// seconds, hold for 7, exhale for 8. Stop stops it.
// icon: ring 12 12 9 ring 12 12 4
state breaths = 4;        // how many to do
state now = 0;            // the breath on, from 1
state part = 0;           // 0 inhale, 1 hold, 2 exhale
state left = 0;           // seconds left of the part
state done = false;       // the last breath is over
state speed = 0;          // ms a step; 0 while it is stopped
state parts = ["Inhale", "Hold", "Exhale"];
state lengths = [4, 7, 8];

every speed {
  left -= 1;
  if left == 0 {
    if part < 2 {
      part += 1;
      left = lengths[part];
    } else if now < breaths {
      now += 1;
      part = 0;
      left = lengths[0];
    } else {
      done = true;
      speed = 0;
    }
  }
}

label "4-7-8 breathing";
if speed == 0 {
  row {
    button "-" { breaths = max(1, breaths - 1); }
    label "Breaths: " + breaths;
    button "+" { breaths = min(8, breaths + 1); }
  }
  if done { label "Well done"; } else { label "Ready"; }
  button "Start" {
    now = 1;
    part = 0;
    left = lengths[0];
    done = false;
    speed = 1000;
  }
} else {
  label parts[part] + " " + left;
  label "Breath " + now + " of " + breaths;
  button "Stop" { speed = 0; }
}

// Reading log: type the book's pages, then the pages read in each sitting and press Log; it
// shows your page, how much is done and when you finish. New book starts again.
// icon: loop 2 6 12 8 22 6 22 19 12 21 2 19 line 12 8 12 21
state book = "";
state sitting = "";
state pages = 0;          // read in all
state sittings = 0;

// The book's pages: 300 unless a number above 0 is typed.
fn total() -> int {
  let t = parse(book, 0);
  if t <= 0 { return 300; }
  return t;
}

fn page() -> int { return min(pages, total()); }

label "Reading log";
row { label "Book pages"; input book; }
row {
  label "Pages read";
  input sitting;
  button "Log" {
    let n = parse(sitting, 0);
    if n > 0 {
      pages += n;
      sittings += 1;
      sitting = "";
    }
  }
}
label "Page: " + page() + " of " + total();
label "Done: " + page() * 100 / total() + "%";
label "Sittings: " + sittings;
if page() == total() { label "Finished"; }
button "New book" {
  pages = 0;
  sittings = 0;
}

// Books read: type a title and press how many stars it gets, 1 to 5, to log it; it shows your
// average and your favorite. Undo takes off the last.
// icon: fill 12 2 15 9 22 9 16 14 18 21 12 17 6 21 8 14 2 9 9 9
state titles = [""; 0];
state stars = [0; 0];
state title = "";

// Logs the title typed with n stars.
fn add(n: int) {
  if title == "" { return; }
  push(titles, title);
  push(stars, n);
  title = "";
}

fn average() -> int {
  if len(stars) == 0 { return 0; }
  let t = 0;
  for i in 0..len(stars) { t += stars[i]; }
  return t / len(stars);
}

// The book with the most stars, the first of a tie.
fn favorite() -> string {
  if len(stars) == 0 { return "None"; }
  let f = 0;
  for i in 1..len(stars) {
    if stars[i] > stars[f] { f = i; }
  }
  return titles[f];
}

label "Books read";
row {
  input title;
  for n in 1..6 { button "" + n { add(n); } }
}
for i in 0..len(titles) { label titles[i] + ": " + stars[i]; }
label "Books: " + len(titles);
label "Average: " + average();
label "Favorite: " + favorite();
button "Undo" {
  if len(titles) > 0 {
    remove(titles, len(titles) - 1);
    remove(stars, len(stars) - 1);
  }
}

