// Bus timetable: type the time now (hour and minute) to see the next bus and how long to wait.
// icon: loop 4 3 20 3 20 18 4 18 line 4 11 20 11 dot 8 19 2 dot 16 19 2
state buses = [400, 435, 485, 570, 720, 945, 1100, 1330];   // minutes after midnight
state hour = "";
state minute = "";

fn two(n: int) -> string {
  if n < 10 { return "0" + n; }
  return "" + n;
}

fn clock(m: int) -> string { return two(m / 60) + ":" + two(m % 60); }

// The time now in minutes after midnight, from what is typed (an empty box is 0).
fn now() -> int { return min(max(parse(hour, 0), 0), 23) * 60 + min(max(parse(minute, 0), 0), 59); }

// The first bus at the time now or later; len(buses) once the last has left.
fn next() -> int {
  for i in 0..len(buses) {
    if buses[i] >= now() { return i; }
  }
  return len(buses);
}

fn timetable() -> string {
  let s = "";
  for i in 0..len(buses) { s = s + " " + clock(buses[i]); }
  return s;
}

label "Bus timetable";
