// The numeral, largest parts first; no part comes more than three times.
fn roman(n: int) -> string {
  let left = n;
  let s = "";
  for i in 0..len(values) {
    repeat 3 {
      if left >= values[i] {
        s = s + marks[i];
        left -= values[i];
      }
