fn leap(y: int) -> bool { return (y % 4 == 0 && y % 100 != 0) || y % 400 == 0; }

fn days(m: int, y: int) -> int {
  if m == 1 {
    if leap(y) { return 29; }
    return 28;
  }
  if m == 3 || m == 5 || m == 8 || m == 10 { return 30; }
  return 31;
}

