// League table: type each match's goals, home then away, and Save; Undo takes the last back.
// The table ranks by points, then goal difference, then goals scored.
// icon: line 4 6 20 6 line 4 12 20 12 line 4 18 20 18 dot 7 3 2
state teams = ["Lions", "Tigers", "Bears", "Wolves"];
state home = [0, 2, 0, 1, 0, 1];      // the six matches in order: home and away teams
state away = [1, 3, 2, 3, 3, 2];
state hg = [0; 0];                    // the goals of each match played
state ag = [0; 0];
state hs = "";
state as = "";

// What team t took from match m: points (3, 1 or 0), or goals for or against.
fn won(t: int, m: int) -> int {
  let us = hg[m];
  let them = ag[m];
  if away[m] == t {
    us = ag[m];
    them = hg[m];
  }
  if us > them { return 3; }
  if us == them { return 1; }
  return 0;
}

fn plays(t: int, m: int) -> bool { return home[m] == t || away[m] == t; }

fn pts(t: int) -> int {
  let n = 0;
  for m in 0..len(hg) {
    if plays(t, m) { n += won(t, m); }
  }
  return n;
}

fn goals(t: int) -> int {
  let n = 0;
  for m in 0..len(hg) {
    if home[m] == t { n += hg[m]; }
    if away[m] == t { n += ag[m]; }
  }
  return n;
}

fn against(t: int) -> int {
  let n = 0;
  for m in 0..len(hg) {
    if home[m] == t { n += ag[m]; }
    if away[m] == t { n += hg[m]; }
  }
  return n;
}

fn gd(t: int) -> int { return goals(t) - against(t); }

// Whether team i ranks above team j.
fn above(i: int, j: int) -> bool {
  if pts(i) != pts(j) { return pts(i) > pts(j); }
  if gd(i) != gd(j) { return gd(i) > gd(j); }
  if goals(i) != goals(j) { return goals(i) > goals(j); }
  return i < j;
}

fn place(t: int) -> int {
  let p = 1;
  for j in 0..4 {
    if above(j, t) { p += 1; }
  }
  return p;
}

fn signed(n: int) -> string {
  if n > 0 { return "+" + n; }
  return "" + n;
}

fn line(t: int) -> string {
  return place(t) + ". " + teams[t] + " " + pts(t) + " pts   GD " + signed(gd(t));
}

fn save() {
  let h = parse(hs, -1);
  let a = parse(as, -1);
  if len(hg) < 6 && h >= 0 && a >= 0 {
    push(hg, h);
    push(ag, a);
    hs = "";
    as = "";
  }
}

