// Tap a peg to pick up its top disc, then the peg to put it on.
// icon: line 12 4 12 20 line 3 21 21 21 fill 8 10 16 10 16 13 8 13 fill 6 15 18 15 18 18 6 18
state at = [0, 0, 0];         // the peg of each disc, the smallest first
