  for d in 0..3 {
    let r = 4 - level(d);
    if d == top(held) { r = 0; }
    for k in 0..2 * d + 1 { b[r * 15 + at[d] * 5 + 2 - d + k] = d + 4; }
  }
  pixels(b, 0, 0, 15, 10);
}

