}

// Fishing: Left and Right (or the arrows) move the boat; Cast (or space) drops the line and
// catches the highest fish under the boat, a point a row deep. 30 seconds a round.
// icon: fill 3 12 8 7 14 7 18 12 14 17 8 17 fill 17 12 22 7 22 17
state fx = [2, 7, 4];      // the fish: column, row and the way each swims
state fy = [2, 3, 5];
state fd = [1, -1, 1];
state boat = 4;
state caught = 0;
state points = 0;
state misses = 0;
state ticks = 0;           // half seconds gone in the round
state speed = 0;           // ms a step; 0 between rounds
state over = false;

fn start() {
  fx = [2, 7, 4];
  boat = 4;
  caught = 0;
  points = 0;
  misses = 0;
  ticks = 0;
  over = false;
  speed = 500;
}

every speed {
  for i in 0..3 { fx[i] = (fx[i] + fd[i] + 10) % 10; }
  ticks += 1;
  if ticks == 60 {
    speed = 0;
    over = true;
  }
}

// The highest fish in the boat's column is caught and swims in again from its edge.
fn cast() {
  if speed == 0 { return; }
  let best = -1;
  for i in 0..3 {
    if fx[i] == boat {
      if best < 0 {
        best = i;
      } else if fy[i] < fy[best] {
        best = i;
      }
    }
  }
  if best < 0 {
    misses += 1;
    return;
  }
  caught += 1;
  points += fy[best];
  if fd[best] > 0 { fx[best] = 0; } else { fx[best] = 9; }
}

fn steer(d: int) { if speed > 0 { boat = min(9, max(0, boat + d)); } }

fn scene() {
  let b = [4; 60];
  for c in 0..10 { b[c] = 6; }
  b[boat] = 3;
  for i in 0..3 { b[fy[i] * 10 + fx[i]] = 1; }
  pixels(b, 0, 0, 10, 16);
  if over { text("Time up", 80, 48, 16, 9); }
}

on key "left" { steer(-1); }
on key "right" { steer(1); }
on key "space" { cast(); }

label "Fishing";
label "Fish: " + caught + "   Points: " + points + "   Misses: " + misses;
label "Time: " + (30 - ticks / 2);
canvas 160, 96, scene();
row {
  button "Left" { steer(-1); }
  button "Cast" { cast(); }
  button "Right" { steer(1); }
}
if speed == 0 { button "Start" { start(); } }

// Fishing: press Cast; a fish bites 3 seconds later; Reel in within 2 seconds to catch it.
// icon: fill 3 12 8 7 14 7 18 12 14 17 8 17 fill 17 12 22 7 22 17
state t = 0;              // seconds since the cast
state caught = 0;
state lost = 0;
state speed = 0;          // 1000 while the line is out

every speed {
  t += 1;
  if t == 5 {
    lost += 1;
