state tiles = [3, 3, 3, 3, 3, 3, 3, 3, 3];          // 3 open, 4 picked, 0 shut
state next = 0;           // the next pair of dice
state roll = 0;           // the roll waiting to be used, 0 if none
state over = false;

fn sum(k: int) -> int {
  let s = 0;
  for i in 0..9 {
    if tiles[i] == k { s += i + 1; }
  }
  return s;
}

fn score() -> int { return sum(3) + sum(4); }

// Whether some set of the tiles not shut adds up to n.
fn can(n: int) -> bool {
  let reach = [false; 46];
  reach[0] = true;
  for i in 0..9 {
    if tiles[i] != 0 {
      for k in 0..46 {
        let s = 45 - k;
        if s > i && reach[s - i - 1] { reach[s] = true; }
      }
    }
  }
  return reach[n];
}

fn throw() {
  roll = dice[next] + dice[next + 1];
  next = (next + 2) % len(dice);
  if !can(roll) { over = true; }
}

fn tap(i: int) {
  if roll == 0 || over || tiles[i] == 0 { return; }
  if tiles[i] == 3 { tiles[i] = 4; } else { tiles[i] = 3; }
  if sum(4) == roll {
    for k in 0..9 {
      if tiles[k] == 4 { tiles[k] = 0; }
    }
    roll = 0;
    if score() == 0 { over = true; }
  }
}

