// Ball sort: tap a tube, then another, to move its top ball onto an empty tube or its own color
// (4 at most). Undo takes a move back; sort every color into its own tube to win.
// icon: loop 4 5 4 21 10 21 10 5 loop 14 5 14 21 20 21 20 5 dot 7 17 2 dot 7 12 2 dot 17 17 2
state balls = [2, 1, 4, 1, 4, 2, 1, 2, 1, 4, 2, 4, 0, 0, 0, 0, 0, 0, 0, 0];
state level = [2, 1, 4, 1, 4, 2, 1, 2, 1, 4, 2, 4, 0, 0, 0, 0, 0, 0, 0, 0];
state sel = -1;           // the selected tube, -1 none
state froms = [0; 0];     // the moves made: from which tube to which
state tos = [0; 0];

// Tube t's balls are at t * 4 to t * 4 + 3, from the bottom; 0 is none.
fn high(t: int) -> int {
  let n = 0;
  for k in 0..4 {
    if balls[t * 4 + k] != 0 { n += 1; }
  }
  return n;
}

fn top(t: int) -> int {
  if high(t) == 0 { return 0; }
  return balls[t * 4 + high(t) - 1];
}

fn solved() -> bool {
  for t in 0..5 {
    let n = high(t);
    if n != 0 && n != 4 { return false; }
    for k in 0..n {
      if balls[t * 4 + k] != balls[t * 4] { return false; }
    }
  }
  return true;
}

fn shift(a: int, b: int) {
  balls[b * 4 + high(b)] = top(a);
  balls[a * 4 + high(a) - 1] = 0;
}

fn restart() {
  for i in 0..20 { balls[i] = level[i]; }
  clear(froms);
  clear(tos);
  sel = -1;
}

fn tap(t: int) {
  if solved() || t < 0 || t > 4 { return; }
  if sel == -1 {
    if high(t) > 0 { sel = t; }
    return;
  }
  if t != sel && high(t) < 4 && (high(t) == 0 || top(t) == top(sel)) {
    shift(sel, t);
    push(froms, sel);
    push(tos, t);
  }
  sel = -1;
}

fn undo() {
  if solved() || len(froms) == 0 { return; }
  let n = len(froms) - 1;
  shift(tos[n], froms[n]);
  remove(froms, n);
  remove(tos, n);
  sel = -1;
}

// Each tube's sides, in the accent while it is selected, and its balls from the bottom row up.
fn scene() {
  for t in 0..5 {
    let ink = 8;
    if t == sel { ink = 11; }
    line(t * 20 + 1, 2, t * 20 + 1, 79, 1, ink);
    line(t * 20 + 19, 2, t * 20 + 19, 79, 1, ink);
    line(t * 20 + 1, 79, t * 20 + 19, 79, 1, ink);
    for k in 0..4 {
      if balls[t * 4 + k] != 0 { circle(t * 20 + 10, 70 - k * 20, 8, balls[t * 4 + k]); }
    }
  }
}

