// Pipes: tap a piece to turn it a quarter turn clockwise; water runs from the top left piece
// through pipes that meet. Get it to every pipe.
// icon: line 3 12 12 12 12 21 line 12 3 12 12 21 12 dot 12 12 3
state pipe = [2, 3, 9, 2, 1, 5, 13, 12, 7, 6, 4, 10, 3, 5, 5, 6];   // 1 up, 2 right, 4 down, 8 left
state wet = [true, false, false, false, false, false, false, false, false, false, false, false,
  false, false, false, false];

fn opens(i: int, side: int) -> bool { return (pipe[i] / side) % 2 == 1; }

// Water from the top left piece into each neighbour whose pipe meets its own.
fn flood() {
  for i in 0..16 { wet[i] = false; }
  wet[0] = true;
  let todo = [0];
  let k = 0;
  let side = [1, 2, 4, 8];
  let back = [4, 8, 1, 2];
  repeat 16 {
    if k < len(todo) {
      let i = todo[k];
      k += 1;
      let near = [i - 4, i + 1, i + 4, i - 1];
      let ok = [i >= 4, i % 4 < 3, i < 12, i % 4 > 0];
      for d in 0..4 {
        if ok[d] && opens(i, side[d]) && opens(near[d], back[d]) && !wet[near[d]] {
          wet[near[d]] = true;
          push(todo, near[d]);
        }
      }
    }
  }
}

fn solved() -> bool {
  for i in 0..16 {
    if !wet[i] { return false; }
  }
  return true;
}

fn arm(on: bool, ink: string) -> string {
  if on { return ink; }
  return ".";
}

