// Set: tap three cards whose number, color and shape are each all the same or all different.
// A set is replaced from the deck; the game ends when no set is left on the table.
// icon: loop 2 6 8 6 8 18 2 18 loop 9 6 15 6 15 18 9 18 loop 16 6 22 6 22 18 16 18 dot 5 12 1
state deck = [7, 9, 8, 13, 25, 3, 20, 18, 10, 12, 17, 4, 2, 26, 21, 5, 1, 0, 24, 11, 23, 15, 22, 16,
  14, 6, 19];             // a card is (number - 1) * 9 + color * 3 + shape
state colors = [1, 2, 5];
state table = [-1; 9];    // -1 an empty place
state next = 9;           // the deck's next card
state picked = [0; 0];
state sets = 0;
state miss = false;
state dealt = false;

// Whether the three values are all the same or all different.
fn fit(a: int, b: int, c: int) -> bool {
  if a == b && b == c { return true; }
  return a != b && b != c && a != c;
}

fn isset(a: int, b: int, c: int) -> bool {
  if a < 0 || b < 0 || c < 0 { return false; }
  return fit(a / 9, b / 9, c / 9) && fit(a / 3 % 3, b / 3 % 3, c / 3 % 3) && fit(a % 3, b % 3, c % 3);
}

fn anyset() -> bool {
  for i in 0..9 {
    for j in i + 1..9 {
      for k in j + 1..9 {
        if isset(table[i], table[j], table[k]) { return true; }
      }
    }
  }
  return false;
}

fn deal() {
  for i in 0..9 { table[i] = deck[i]; }
  next = 9;
  clear(picked);
  sets = 0;
  miss = false;
  dealt = true;
}

fn chosen(i: int) -> bool {
  for k in 0..len(picked) {
    if picked[k] == i { return true; }
  }
  return false;
}

fn tap(i: int) {
  if !dealt || !anyset() || table[i] < 0 { return; }
  miss = false;
  if chosen(i) {
    for k in 0..len(picked) {
      if picked[k] == i { remove(picked, k); return; }
    }
  }
  push(picked, i);
  if len(picked) < 3 { return; }
  if isset(table[picked[0]], table[picked[1]], table[picked[2]]) {
    for i2 in 0..9 {
      if chosen(i2) {
        table[i2] = -1;
        if next < 27 {
          table[i2] = deck[next];
          next += 1;
        }
      }
    }
    sets += 1;
  } else {
    miss = true;
  }
  clear(picked);
}

// One shape of card c centered at x0, y0: a circle, a square or a triangle.
fn shape(c: int, x0: int, y0: int) {
  let ink = colors[c / 3 % 3];
  if c % 3 == 0 { circle(x0, y0, 4, ink); }
  if c % 3 == 1 { rect(x0 - 4, y0 - 4, 8, 8, ink); }
  if c % 3 == 2 {
    let s = "" + ink;
    sprite(["..." + s + "...", ".." + s + s + s + "..", "." + s + s + s + s + s + ".", s + s + s + s + s + s + s], x0 - 4, y0 - 3, 1);
  }
}

// Each card in its 40-unit cell, its 1 to 3 shapes side by side; a selected card yellow.
fn scene() {
  for i in 0..9 {
    let c = table[i];
    let x0 = i % 3 * 40;
    let y0 = i / 3 * 40;
    if c >= 0 {
      let face = 7;
      if chosen(i) { face = 3; }
      rect(x0 + 2, y0 + 2, 36, 36, face);
      let n = c / 9 + 1;
      for k in 0..n { shape(c, x0 + 20 + (2 * k - n + 1) * 6, y0 + 20); }
    }
  }
}

fn status() -> string {
  if dealt && !anyset() { return "Game over"; }
  if miss { return "Not a set"; }
  return "";
}

label "Set";
