// Woodoku, one piece at a time: tap the board where the next piece's top left block goes. Full
// rows, columns and 3 x 3 boxes clear; it is over when the next piece fits nowhere.
// icon: fill 3 3 11 3 11 11 3 11 fill 13 13 21 13 21 21 13 21 loop 13 3 21 3 21 11 13 11
state board = [0; 81];    // 0 empty, 4 a block
state px = [0, 1, 2, 0, 1, 2, 0, 1, 2, 0, 1, 0, 1, 0, 1, 2, 0, 0, 0, 0];
state py = [0, 0, 0, 1, 1, 1, 2, 2, 2, 0, 0, 1, 1, 0, 0, 0, 0, 1, 2, 0];
state from = [0, 9, 13, 16, 19, 20];   // piece p's blocks are from[p] to from[p + 1] - 1
state turn = 0;           // pieces placed: the next is turn % 5

fn fits(x0: int, y0: int) -> bool {
  let p = turn % 5;
  for k in from[p]..from[p + 1] {
    if x0 + px[k] > 8 || y0 + py[k] > 8 { return false; }
    if board[(y0 + py[k]) * 9 + x0 + px[k]] != 0 { return false; }
  }
  return true;
}

fn over() -> bool {
  for i in 0..81 {
    if fits(i % 9, i / 9) { return false; }
  }
  return true;
}

// Square k of row r (kind 0), column r (kind 1) or box r (kind 2).
fn square(kind: int, r: int, k: int) -> int {
  if kind == 0 { return r * 9 + k; }
  if kind == 1 { return k * 9 + r; }
  return (r / 3 * 3 + k / 3) * 9 + r % 3 * 3 + k % 3;
}

fn full(kind: int, r: int) -> bool {
  for k in 0..9 {
    if board[square(kind, r, k)] == 0 { return false; }
  }
  return true;
}

fn place(x0: int, y0: int) {
  if over() || !fits(x0, y0) { return; }
  let p = turn % 5;
  for k in from[p]..from[p + 1] { board[(y0 + py[k]) * 9 + x0 + px[k]] = 4; }
  let gone = [false; 81];
  for kind in 0..3 {
    for r in 0..9 {
      if full(kind, r) {
        for k in 0..9 { gone[square(kind, r, k)] = true; }
      }
    }
  }
  for i in 0..81 {
    if gone[i] { board[i] = 0; }
  }
  turn += 1;
}

fn scene() {
  pixels(board, 0, 0, 9, 20);
  for k in 0..4 {
    line(k * 60, 0, k * 60, 180, 1, 8);
    line(0, k * 60, 180, k * 60, 1, 8);
  }
}

fn preview() {
  let p = turn % 5;
  for k in from[p]..from[p + 1] { rect(px[k] * 12 + 2, py[k] * 12 + 2, 11, 11, 4); }
}

