// Word search: tap a word's first letter, then its last, to find it. Six sea animals hide in the
// grid, across, down or diagonally, forwards or backwards.
// icon: loop 3 3 21 3 21 21 3 21 line 7 8 17 8 line 7 13 17 13 line 7 18 13 18
state letters = ["P", "H", "W", "H", "A", "L", "E", "T", "D", "E", "G", "R", "D", "K", "D", "S",
  "E", "U", "D", "U", "E", "M", "E", "H", "L", "U", "D", "I", "G", "M", "D", "A",
  "A", "T", "D", "B", "U", "M", "D", "R", "R", "H", "A", "O", "U", "Q", "H", "K",
  "O", "R", "G", "O", "I", "G", "S", "K", "C", "R", "G", "L", "A", "E", "S", "E"];
state words = ["WHALE", "SHARK", "CRAB", "SEAL", "CORAL", "SQUID"];
state found = [false; 6];
state lit = [false; 64];   // the squares of the words found
state sel = -1;            // the square tapped first; -1 none

fn sign(v: int) -> int {
  if v > 0 { return 1; }
  if v < 0 { return -1; }
  return 0;
}

// The step from square a toward square b on one straight line; 0 when they are on none.
fn step(a: int, b: int) -> int {
  let dc = b % 8 - a % 8;
  let dr = b / 8 - a / 8;
  if dc != 0 && dr != 0 && abs(dc) != abs(dr) { return 0; }
  return sign(dr) * 8 + sign(dc);
}

// The letters from square a to square b, both ends counted.
fn spell(a: int, b: int) -> string {
  let s = step(a, b);
  let n = max(abs(b % 8 - a % 8), abs(b / 8 - a / 8));
  let w = "";
  for k in 0..n + 1 { w = w + letters[a + k * s]; }
  return w;
}

fn count() -> int {
  let n = 0;
  for k in 0..6 {
    if found[k] { n += 1; }
  }
  return n;
}

// A try from square a to square b: a hidden word not found yet, read either way, is found.
fn attempt(a: int, b: int) {
  if a == b || step(a, b) == 0 { return; }
  let fwd = spell(a, b);
  let back = spell(b, a);
  for k in 0..6 {
    if !found[k] && (words[k] == fwd || words[k] == back) {
      found[k] = true;
      let s = step(a, b);
      for j in 0..len(fwd) { lit[a + j * s] = true; }
      return;
    }
  }
}

fn tap(i: int) {
  if count() == 6 { return; }
  if sel < 0 {
    sel = i;
  } else {
    attempt(sel, i);
    sel = -1;
  }
}

fn tint(i: int) -> int {
  if i == sel { return 3; }
  if lit[i] { return 2; }
  return 7;
}

fn scene() {
  for i in 0..64 {
    rect((i % 8) * 16 + 1, (i / 8) * 16 + 1, 14, 14, tint(i));
    text(letters[i], (i % 8) * 16 + 8, (i / 8) * 16 + 8, 10, 9);
  }
}

fn status() -> string {
  if count() == 6 { return "You found them all"; }
  return "Found " + count() + " of 6";
}

