}

// The letters from a to b, if a word not found yet: found, and its squares lit.
fn attempt(a: int, b: int) {
  let s = step(a, b);
  if a == b || s == 0 { return; }
  let n = max(abs(b % 6 - a % 6), abs(b / 6 - a / 6));
