// Flow: tap a dot, then the squares next to each other (or drag), to lay a pipe to the dot of its
// color. Join every pair and fill the board. A tap on a dot starts afresh, on the pipe cuts back.
// icon: dot 5 5 3 line 5 5 19 5 19 19 dot 19 19 3 dot 5 19 3 line 5 19 12 19
state dots = [0, 0, 0, 0, 1, 0, 0, 0, 3, 4, 1, 0, 5, 4, 0, 2, 3, 0, 5, 0, 0, 2, 0, 0, 0];
state pipe = [0; 25];     // the color of the pipe on each square without a dot
state done = [false; 6];  // which colors are joined
state cur = [0; 0];       // the squares of the pipe being drawn, from its dot
state ink = 0;            // its color; 0 none

fn near(a: int, b: int) -> bool {
  return abs(a % 5 - b % 5) + abs(a / 5 - b / 5) == 1;
}

fn hue(i: int) -> int {
  if dots[i] > 0 { return dots[i]; }
  return pipe[i];
}

fn joined() -> int {
  let n = 0;
  for k in 1..6 {
    if done[k] { n += 1; }
  }
  return n;
}

fn solved() -> bool {
  for i in 0..25 {
    if hue(i) == 0 { return false; }
  }
  return joined() == 5;
}

fn erase(k: int) {
  for i in 0..25 {
    if pipe[i] == k { pipe[i] = 0; }
  }
  done[k] = false;
}

// The pipe cut back to square i, its squares past it emptied.
fn cut(i: int) {
  repeat 25 {
    let n = len(cur);
    if cur[n - 1] != i {
      pipe[cur[n - 1]] = 0;
      remove(cur, n - 1);
    }
  }
}

fn tap(i: int) {
  if solved() { return; }
  if ink > 0 {
    let end = cur[len(cur) - 1];
    if near(end, i) && dots[i] == ink && i != cur[0] {
      done[ink] = true;
      ink = 0;
      clear(cur);
      return;
    }
    if near(end, i) && hue(i) == 0 {
      pipe[i] = ink;
      push(cur, i);
      return;
    }
    if dots[i] == 0 && pipe[i] == ink {
      cut(i);
      return;
    }
  }
  if dots[i] > 0 {
    erase(dots[i]);
    ink = dots[i];
    clear(cur);
    push(cur, i);
  }
}

// Each square a cell; a dot a large circle, a pipe a band of its color.
fn scene() {
  for i in 0..25 {
    let x = (i % 5) * 20;
    let y = (i / 5) * 20;
    rect(x + 1, y + 1, 18, 18, 0);
    if dots[i] > 0 { circle(x + 10, y + 10, 8, dots[i]); }
    if pipe[i] > 0 { rect(x + 4, y + 4, 12, 12, pipe[i]); }
  }
}

fn status() -> string {
  if solved() { return "Solved"; }
  return "Flows: " + joined() + " of 5";
}

label "Flow";
canvas 100, 100, scene() { tap((y / 20) * 5 + x / 20); }
label status();
button "Clear" {
  for k in 1..6 { erase(k); }
  ink = 0;
