// Flow: drag from a dot (or tap square by square) to lay a pipe to the dot of its color. Join every
// pair and fill the board to solve it.
// icon: dot 5 5 3 line 5 5 19 5 19 19 dot 19 19 3 dot 5 19 3 line 5 19 12 19
state dots = [4, 5, 0, 1, 0, 2, 0, 0, 1, 2, 0, 3, 0, 0, 0, 0, 0, 0, 0, 5, 0, 6, 0, 0, 0, 6, 0, 0,
  0, 0, 0, 0, 4, 3, 0, 0];
state pipe = [0; 36];     // the color of the pipe on each square without a dot
state done = [false; 7];  // which colors are joined
state cur = [0; 0];       // the pipe being drawn, from its dot
state ink = 0;            // its color; 0 none

fn near(a: int, b: int) -> bool {
  return abs(a % 6 - b % 6) + abs(a / 6 - b / 6) == 1;
}

fn hue(i: int) -> int {
  if dots[i] > 0 { return dots[i]; }
  return pipe[i];
}

fn solved() -> bool {
  for i in 0..36 {
    if hue(i) == 0 { return false; }
  }
  for k in 1..7 {
    if !done[k] { return false; }
  }
  return true;
}

// A dot starts its color afresh; the pipe grows into an empty square next to its end, cuts back
// to a square of its own, and ends on its other dot.
fn tap(i: int) {
  if ink > 0 {
    let end = cur[len(cur) - 1];
    if near(end, i) && dots[i] == ink && i != cur[0] {
      done[ink] = true;
      ink = 0;
      return;
    }
    if near(end, i) && hue(i) == 0 {
      pipe[i] = ink;
      push(cur, i);
      return;
    }
    if dots[i] == 0 && pipe[i] == ink {
      repeat 36 {
        if cur[len(cur) - 1] != i {
          pipe[cur[len(cur) - 1]] = 0;
          remove(cur, len(cur) - 1);
        }
      }
      return;
    }
  }
  if dots[i] > 0 {
    ink = dots[i];
    for j in 0..36 {
      if pipe[j] == ink { pipe[j] = 0; }
    }
    done[ink] = false;
    clear(cur);
    push(cur, i);
  }
}

fn scene() {
  for i in 0..36 {
    let x = (i % 6) * 20;
    let y = (i / 6) * 20;
    if dots[i] > 0 { circle(x + 10, y + 10, 8, dots[i]); }
    if pipe[i] > 0 { rect(x + 4, y + 4, 12, 12, pipe[i]); }
  }
  if solved() { text("Solved!", 60, 60, 20, 9); }
}

