state down = [0; 8];      // 8 (gray) once knocked down
state answer = "";
state secret = 5;         // Max, for now

fn yes(v: bool) -> string {
  if v { return " Yes"; }
  return " No";
}

// The secret's answer, and everyone whose own answer differs knocked down.
fn glasses_q() {
  for i in 0..8 {
    if glasses[i] != glasses[secret] { down[i] = 8; }
  }
  answer = "Glasses?" + yes(glasses[secret]);
}

fn hat_q() {
  for i in 0..8 {
    if hat[i] != hat[secret] { down[i] = 8; }
  }
  answer = "Hat?" + yes(hat[secret]);
}

fn beard_q() {
  for i in 0..8 {
    if beard[i] != beard[secret] { down[i] = 8; }
  }
  answer = "Beard?" + yes(beard[secret]);
}

fn hair_q(h: string) {
  for i in 0..8 {
    if (hair[i] == h) != (hair[secret] == h) { down[i] = 8; }
  }
  answer = h + " hair?" + yes(hair[secret] == h);
}

fn left() -> int {
  let n = 0;
  for i in 0..8 {
    if down[i] == 0 { n += 1; }
  }
  return n;
}

