}

// Lode Runner: the arrows (or a tap) run and climb, z and x dig down-left or down-right. Take
// all the gold; the guard chases you, and a hole you dig traps it until it fills.
// icon: line 12 3 12 21 line 18 3 18 21 line 12 8 18 8 line 12 14 18 14 dot 6 12 3
state map = [0; 96];            // 12 x 8, square c + 12 * r: 0 empty, 8 brick, 6 ladder, 3 gold
state holes = [0; 0];           // dug squares, and the step each fills again
state fill = [0; 0];
state rx = 0;                   // the runner
state ry = 5;
state gx = 11;                  // the guard
state gy = 5;
state steps = 0;
state score = 0;
state lives = 3;
state speed = 0;                // 200 while a game runs, else 0
state won = false;
state over = false;

fn at(c: int, r: int) -> int { return r * 12 + c; }

fn sign(n: int) -> int {
  if n > 0 { return 1; }
  if n < 0 { return -1; }
  return 0;
}

// Whether something at (c, r) stands: on a ladder, or on brick or a ladder.
fn stands(c: int, r: int) -> bool {
  return map[at(c, r)] == 6 || map[at(c, r + 1)] == 8 || map[at(c, r + 1)] == 6;
}

fn start() {
  for i in 0..96 {
    map[i] = 0;
    if i >= 72 || (i >= 24 && i < 36) { map[i] = 8; }
  }
  for r in 1..6 { map[at(8, r)] = 6; }
  map[at(1, 1)] = 3;
  map[at(11, 1)] = 3;
  map[at(3, 5)] = 3;
  clear(holes);
  clear(fill);
  rx = 0;
  ry = 5;
  gx = 11;
  gy = 5;
  steps = 0;
  score = 0;
  lives = 3;
  won = false;
  over = false;
  speed = 200;
}

fn lose() {
  lives -= 1;
  rx = 0;
  ry = 5;
  gx = 11;
  gy = 5;
  if lives == 0 {
    over = true;
    speed = 0;
  }
}

// The runner on its square: gold is taken, the guard catches it.
fn arrive() {
  if map[at(rx, ry)] == 3 {
    map[at(rx, ry)] = 0;
    score += 100;
    let left = 0;
    for i in 0..96 {
      if map[i] == 3 { left += 1; }
    }
    if left == 0 {
      won = true;
      speed = 0;
    }
  }
  if rx == gx && ry == gy { lose(); }
}

fn run(x: int, y: int) {
  let c = rx + x;
  let r = ry + y;
  if speed == 0 || !stands(rx, ry) || c < 0 || c > 11 || r < 0 || map[at(c, r)] == 8 { return; }
  if y < 0 && map[at(rx, ry)] != 6 { return; }
  rx = c;
  ry = r;
  arrive();
}

// Digs the brick below the square beside the runner, that way, if that square is empty.
fn dig(x: int) {
  let c = rx + x;
  if speed > 0 && stands(rx, ry) && c >= 0 && c <= 11 && ry < 6 && map[at(c, ry)] == 0 && map[at(c, ry + 1)] == 8 {
    map[at(c, ry + 1)] = 0;
    push(holes, at(c, ry + 1));
    push(fill, steps + 15);
  }
}

// Holes due fill again: the runner in one loses a life, the guard goes back to its start.
fn refill() {
  let n = len(holes);
  for j in 0..n {
    let k = n - 1 - j;
    if fill[k] == steps {
      let i = holes[k];
      map[i] = 8;
      remove(holes, k);
      remove(fill, k);
      if at(rx, ry) == i {
        lose();
      } else if at(gx, gy) == i {
        gx = 11;
        gy = 5;
      }
    }
  }
}

// The guard, every 2nd step: falls if nothing holds it, else a column toward the runner.
fn chase() {
  if !stands(gx, gy) {
    gy += 1;
  } else if gx != rx && map[at(gx + (rx - gx) / abs(rx - gx), gy)] != 8 {
    gx += (rx - gx) / abs(rx - gx);
  }
  if rx == gx && ry == gy { lose(); }
}

every speed {
  steps += 1;
  refill();
  if speed > 0 && !stands(rx, ry) {
    ry += 1;
    arrive();
  }
  if speed > 0 && steps % 2 == 0 { chase(); }
}

