// Lode Runner: the arrows (or a tap) run, climb and go hand over hand along the rope; down lets
// go. Take all the gold, then climb the escape ladder; keep clear of the guard. 3 lives.
// icon: line 12 3 12 21 line 18 3 18 21 line 12 8 18 8 line 12 14 18 14 dot 6 12 3
state map = [0; 80];            // 10 x 8, square c + 10 * r: 0 empty, 8 brick, 6 ladder, 5 rope, 3 gold
state rx = 0;                   // the runner
state ry = 6;
state gx = 7;                   // the guard, and its way along row 3
state way = -1;
state score = 0;
state lives = 3;
state speed = 0;                // 100 while a game runs, else 0
state ticks = 0;
state won = false;
state over = false;

fn at(c: int, r: int) -> int { return r * 10 + c; }

fn sign(n: int) -> int {
  if n > 0 { return 1; }
  if n < 0 { return -1; }
  return 0;
}

// Whether the runner holds on: on a ladder or the rope, or on brick or a ladder.
fn stands() -> bool {
  let here = map[at(rx, ry)];
  let under = map[at(rx, ry + 1)];
  return here == 6 || here == 5 || under == 8 || under == 6;
}

fn start() {
  for i in 0..80 {
    map[i] = 0;
    if i >= 70 || (i >= 40 && i < 50 && i != 48) { map[i] = 8; }
  }
  for r in 2..7 { map[at(8, r)] = 6; }
  for c in 1..8 { map[at(c, 1)] = 5; }
  map[at(3, 6)] = 3;
