// Rolling Marble: an arrow (or a tap) tilts the board, space levels it; the marble speeds up
// downhill and slows on the level. Roll it into the green goal; the red pits cost a life.
// icon: loop 3 3 21 3 21 21 3 21 line 3 12 14 12 dot 17 17 3 line 6 7 12 7
state map = [8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 0, 0, 0, 0, 0, 0, 0, 0, 8, 8, 0, 8, 8, 8, 8, 0, 8, 0, 8, 8, 0, 0, 0, 0, 0, 0, 8, 0, 8, 8, 0, 8, 1, 8, 8, 0, 0, 0, 8, 8, 0, 8, 0, 0, 0, 0, 0, 1, 8, 8, 0, 0, 0, 8, 0, 0, 2, 0, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8];
