fn sign(n: int) -> int {
  if n > 0 { return 1; }
  if n < 0 { return -1; }
  return 0;
}

fn home() {
  mx = 1;
  my = 1;
  vx = 0;
  vy = 0;
  tx = 0;
  ty = 0;
}

fn start() {
  home();
  lives = 3;
  won = false;
  over = false;
  speed = 100;
}

fn tilt(x: int, y: int) {
  if speed > 0 {
    tx = x;
    ty = y;
  }
}

// One square of the roll, by (x, y): a wall stops it (false); a pit or the goal ends the roll.
fn roll(x: int, y: int) -> bool {
  let i = (my + y) * 10 + mx + x;
  if map[i] == 8 { return false; }
  mx += x;
  my += y;
  if map[i] == 1 {
    lives -= 1;
    home();
    if lives == 0 {
      over = true;
      speed = 0;
    }
    return false;
  }
  if map[i] == 2 {
    won = true;
    speed = 0;
    return false;
  }
  return true;
}

// Downhill the speed grows by 1 (3 at most); across the slope it falls by 1 toward 0. Then the
// marble rolls across, square by square, then up or down.
every speed {
  if tx != 0 { vx = min(3, max(-3, vx + tx)); } else { vx -= sign(vx); }
  if ty != 0 { vy = min(3, max(-3, vy + ty)); } else { vy -= sign(vy); }
  for k in 0..abs(vx) {
    if speed > 0 && vx != 0 && !roll(sign(vx), 0) { vx = 0; }
  }
  for k in 0..abs(vy) {
    if speed > 0 && vy != 0 && !roll(0, sign(vy)) { vy = 0; }
  }
}

