// Fruit Slice: fruit is thrown up and falls back; tap or drag across it to slice it. Let 3 fall and
// the game is over, and so is it at once if you slice a bomb.
// icon: dot 12 13 8 line 4 21 21 4
state cols = [1, 4, 6, 2, 5, 3, 0, 7];   // the columns things are thrown in, in turn
state tx = [0; 0];              // what is in the air: column, row, up-speed, a bomb
state ty = [0; 0];
state tv = [0; 0];
