// Sheepdog: the arrows (or a tap beside the dog) move the dog; sheep next to it run straight
// away. Herd all three into the green pen in the corner before the minute is up.
// icon: fill 3 10 13 10 13 16 3 16 dot 8 8 3 dot 18 15 3 line 18 18 18 21
state sx = [2, 5, 4];           // the sheep, and whether penned
state sy = [5, 5, 2];
state penned = [false, false, false];
state dx = 0;                   // the dog
state dy = 7;
state steps = 0;                // 250 ms steps since Start
state left = 60;                // seconds left
state count = 0;
state speed = 0;                // 250 while a game runs, else 0
state won = false;
state over = false;

fn pen(c: int, r: int) -> bool { return c >= 7 && r <= 2; }

fn on(c: int, r: int) -> bool { return c >= 0 && c < 10 && r >= 0 && r < 8; }

fn sign(n: int) -> int {
  if n > 0 { return 1; }
  if n < 0 { return -1; }
  return 0;
}

// The sheep on square (c, r), or -1.
fn sheep(c: int, r: int) -> int {
  for k in 0..3 {
    if !penned[k] && sx[k] == c && sy[k] == r { return k; }
  }
  return -1;
}

fn free(c: int, r: int) -> bool {
  return on(c, r) && sheep(c, r) < 0 && !(c == dx && r == dy);
}

fn start() {
  sx = [2, 5, 4];
  sy = [5, 5, 2];
  penned = [false, false, false];
  dx = 0;
  dy = 7;
  steps = 0;
  left = 60;
  count = 0;
  won = false;
  over = false;
  speed = 250;
}

fn walk(x: int, y: int) {
  if speed > 0 && on(dx + x, dy + y) && sheep(dx + x, dy + y) < 0 {
    dx += x;
    dy += y;
  }
}

// Sheep k to (c, r), into the pen if it is there.
fn go(k: int, c: int, r: int) {
  sx[k] = c;
  sy[k] = r;
  if pen(c, r) {
    penned[k] = true;
    count += 1;
  }
}

// Sheep k beside the dog runs a square straight away: both ways if it can, else across, else
// up or down.
fn flee(k: int) {
  let mx = sign(sx[k] - dx);
  let my = sign(sy[k] - dy);
  if penned[k] || abs(sx[k] - dx) > 1 || abs(sy[k] - dy) > 1 { return; }
  if free(sx[k] + mx, sy[k] + my) {
    go(k, sx[k] + mx, sy[k] + my);
  } else if mx != 0 && free(sx[k] + mx, sy[k]) {
    go(k, sx[k] + mx, sy[k]);
  } else if my != 0 && free(sx[k], sy[k] + my) {
    go(k, sx[k], sy[k] + my);
  }
}

every speed {
  for k in 0..3 { flee(k); }
  steps += 1;
  if steps % 4 == 0 { left -= 1; }
  if count == 3 {
    won = true;
    speed = 0;
  } else if left == 0 {
    over = true;
    speed = 0;
  }
}

on key "left" { walk(-1, 0); }
on key "right" { walk(1, 0); }
on key "up" { walk(0, -1); }
on key "down" { walk(0, 1); }

