label "Level: " + level + "   Barks: " + barks;
canvas 90, 90, scene() {
  let ax = x / 10 - dx;
  let ay = y / 10 - dy;
  if abs(ax) > abs(ay) {
    walk(sign(ax), 0);
  } else if ay != 0 {
    walk(0, sign(ay));
  }
}
