// Property trader: Red and Blue roll round a 12-square track, buy what they land on and pay
// rent on the other's; GO pays 50, Tax costs 50. Whoever cannot pay loses.
// icon: loop 3 3 21 3 21 21 3 21 loop 9 9 15 9 15 15 9 15 dot 6 6 2
state price = [0, 60, 60, 80, 100, 100, 0, 120, 120, 140, 160, 180];
state owner = [0; 12];       // 0 nobody, 1 Red, 2 Blue
state cx = [0, 1, 2, 3, 3, 3, 3, 2, 1, 0, 0, 0];   // each square's column and row
state cy = [0, 0, 0, 0, 1, 2, 3, 3, 3, 3, 2, 1];
state dice = [4, 4, 5, 5, 3, 6, 1, 1, 6, 5, 2, 2, 4, 5, 3, 3, 2, 2];
state rolls = 0;
state pos = [0, 0];
state cash = [300, 300];
state turn = 0;              // 0 Red, 1 Blue
state rolled = false;
state winner = "";

fn name(p: int) -> string {
  if p == 0 { return "Red"; }
  return "Blue";
}

// Player p pays n to `to` (2 the bank); if it cannot, it pays all it has and loses.
fn pay(p: int, n: int, to: int) {
  let paid = min(n, cash[p]);
  cash[p] -= paid;
  if to < 2 { cash[to] += paid; }
  if paid < n { winner = name(1 - p); }
}

fn roll() {
  let n = dice[rolls % 18];
  rolls += 1;
  let p = turn;
  if pos[p] + n >= 12 { cash[p] += 50; }
  pos[p] = (pos[p] + n) % 12;
  let s = pos[p];
  if s == 6 { pay(p, 50, 2); }
  if owner[s] == 2 - p { pay(p, price[s] / 2, 1 - p); }
  rolled = true;
}

fn buyable() -> bool {
  let s = pos[turn];
  return winner == "" && rolled && price[s] > 0 && owner[s] == 0 && cash[turn] >= price[s];
}

fn reset() {
  for s in 0..12 { owner[s] = 0; }
  rolls = 0;
  pos[0] = 0;
  pos[1] = 0;
  cash[0] = 300;
  cash[1] = 300;
  turn = 0;
  rolled = false;
  winner = "";
}

// The track, squares of 30 units: GO and Tax green, properties gray or their owner's color;
// the tokens in the corners, Red's top left, Blue's bottom right.
fn scene() {
  let b = [0; 16];
  let tint = [8, 1, 4];
  for s in 0..12 {
    let k = 2;
    if price[s] > 0 { k = tint[owner[s]]; }
    b[cy[s] * 4 + cx[s]] = k;
  }
  pixels(b, 0, 0, 4, 30);
  circle(cx[pos[0]] * 30 + 6, cy[pos[0]] * 30 + 6, 4, 1);
  circle(cx[pos[1]] * 30 + 24, cy[pos[1]] * 30 + 24, 4, 4);
}

label "Property trader";
label "Red " + cash[0] + "   Blue " + cash[1];
if winner != "" {
  label winner + " wins";
} else {
  label name(turn) + "'s turn";
}
canvas 120, 120, scene();
row {
  if winner == "" && !rolled { button "Roll" { roll(); } }
  if buyable() {
    button "Buy" {
      let s = pos[turn];
      cash[turn] -= price[s];
      owner[s] = turn + 1;
    }
  }
  if winner == "" && rolled {
    button "End turn" {
      turn = 1 - turn;
      rolled = false;
    }
  }
  button "New game" { reset(); }
}

// Town tycoon: tap an empty lot to build a house ($100) or a park ($50); Next day collects the
// rent: $10 a house, $20 beside a park.
// icon: fill 4 12 12 4 20 12 fill 6 12 18 12 18 20 6 20
state lots = [0; 25];       // 5 x 5: 0 empty, 1 a house, 2 a park
state money = 500;
state making = 1;           // what a tap builds

fn park(c: int, r: int) -> bool {
  return c >= 0 && c < 5 && r >= 0 && r < 5 && lots[r * 5 + c] == 2;
}

fn rent(i: int) -> int {
  if lots[i] != 1 { return 0; }
  let c = i % 5;
  let r = i / 5;
  if park(c - 1, r) || park(c + 1, r) || park(c, r - 1) || park(c, r + 1) { return 20; }
  return 10;
}

fn kind() -> string {
  if making == 1 { return "a house"; }
  return "a park";
}

label "Town tycoon";
