label "Building " + kind();
grid 5, lots {
  let cost = 100;
  if making == 2 { cost = 50; }
  if lots[cell] == 0 && money >= cost {
    lots[cell] = making;
    money -= cost;
  }
}
row {
  button "House" { making = 1; }
  button "Park" { making = 2; }
  button "Next day" {
    for i in 0..25 { money += rent(i); }
  }
}

// Ecosystem: tap to place grass, rabbits and foxes; Step (or Play) runs the world: rabbits breed
// on grass and starve without it, foxes eat rabbits and starve without them, grass spreads.
// icon: fill 3 20 21 20 21 15 3 15 dot 9 10 3 dot 16 8 3
state world = [0; 100];     // 10 x 10: 0 empty, 2 grass, 3 rabbit, 1 fox (their colors)
state put = 2;              // what a tap puts
state steps = 0;
state speed = 0;            // 500 while it plays
state stable = false;

// How many of square i's up to 8 neighbors hold k.
fn around(i: int, k: int) -> int {
  let n = 0;
  let c = i % 10;
  let r = i / 10;
  for dy in 0..3 {
    for dx in 0..3 {
      let x2 = c + dx - 1;
      let y2 = r + dy - 1;
      if (dx != 1 || dy != 1) && x2 >= 0 && x2 < 10 && y2 >= 0 && y2 < 10 {
        if world[y2 * 10 + x2] == k { n += 1; }
      }
    }
  }
  return n;
}

// What square i becomes this step.
fn next(i: int) -> int {
  let v = world[i];
  if v == 2 && around(i, 3) >= 2 { return 3; }
  if v == 3 && (around(i, 1) > 0 || around(i, 2) == 0) { return 0; }
  if v == 1 && around(i, 3) == 0 { return 0; }
  if v == 0 && around(i, 1) >= 2 && around(i, 3) > 0 { return 1; }
  if v == 0 && around(i, 2) >= 2 { return 2; }
  return v;
}

fn step() {
  let b = [0; 100];
  let changed = false;
  for i in 0..100 {
    b[i] = next(i);
    if b[i] != world[i] { changed = true; }
  }
  for i in 0..100 { world[i] = b[i]; }
  steps += 1;
  stable = !changed;
  if stable { speed = 0; }
}

fn count(k: int) -> int {
  let n = 0;
  for i in 0..100 {
    if world[i] == k { n += 1; }
  }
  return n;
}

every speed { step(); }

label "Ecosystem";
label "Grass " + count(2) + "   Rabbits " + count(3) + "   Foxes " + count(1) + "   Step " + steps;
if stable { label "Stable"; }
grid 10, world {
  world[cell] = put;
  stable = false;
}
row {
  button "Grass" { put = 2; }
  button "Rabbit" { put = 3; }
  button "Fox" { put = 1; }
  button "Empty" { put = 0; }
}
