// Flipbook: paint each 16 x 12 page; Add, Copy and Delete pages, Prev and Next to flip, the
// last page faintly under the one you paint; Play runs them as an animation.
// icon: loop 5 4 17 4 17 20 5 20 line 8 4 8 20 dot 12 12 2
state art = [0; 192];       // the pages, one after another, 192 squares each
state pages = 1;
state at = 0;               // the page shown, from 0
state paint = 1;            // the color a tap paints; 0 erases
state speed = 0;            // 250 while it plays

fn base(p: int) -> int { return p * 192; }

// A new page after the one shown: blank, or a copy of it.
fn put(copy: bool) {
  if pages >= 20 { return; }
  let from = base(at);
  let to = base(at + 1);
  for i in 0..192 {
    let v = 0;
    if copy { v = art[from + i]; }
    insert(art, to + i, v);
  }
  pages += 1;
  at += 1;
}

fn drop() {
  if pages <= 1 { return; }
  for i in 0..192 { remove(art, base(at)); }
  pages -= 1;
  at = max(0, at - 1);
}

fn flip(d: int) {
  if speed == 0 { at = min(pages - 1, max(0, at + d)); }
}

fn tap(i: int) {
  if speed == 0 { art[base(at) + i] = paint; }
}

every speed { at = (at + 1) % pages; }

on key "left" { flip(-1); }
on key "right" { flip(1); }

// The page shown, 16 x 12 squares of 10 units; while editing, the page before shows gray
// wherever this one is blank.
fn scene() {
  let b = [0; 192];
  for i in 0..192 {
    b[i] = art[base(at) + i];
    if b[i] == 0 && speed == 0 && at > 0 && art[base(at - 1) + i] != 0 { b[i] = 8; }
  }
  pixels(b, 0, 0, 16, 10);
}

fn swatch() -> string {
  let names = ["Erase", "Red", "Green", "", "Blue"];
  return names[paint];
}

label "Flipbook";
label "Page " + (at + 1) + " of " + pages + "   Painting: " + swatch();
canvas 160, 120, scene() { tap((y / 10) * 16 + x / 10); }
row {
  button "Red" { paint = 1; }
  button "Green" { paint = 2; }
  button "Blue" { paint = 4; }
  button "Erase" { paint = 0; }
}
row {
  button "Prev" { flip(-1); }
  button "Next" { flip(1); }
  if speed == 0 {
    button "Add page" { put(false); }
    button "Copy page" { put(true); }
    button "Delete page" { drop(); }
    button "Play" {
      at = 0;
      speed = 250;
    }
  } else {
    button "Stop" { speed = 0; }
  }
}

// Flipbook: draw on the page with a finger or the mouse; New page starts the next one; the left
// and right arrows flip back and forth through the pages.
// icon: loop 6 3 18 3 18 21 6 21 line 9 3 9 21 dot 14 12 2
state art = [0; 192];       // the pages, one after another, 16 x 12 squares each
state pages = 1;
state at = 0;               // the page shown, from 0

fn page() {
  let b = [0; 192];
  for i in 0..192 { b[i] = art[at * 192 + i]; }
  pixels(b, 0, 0, 16, 10);
}

on key "left" { at = max(0, at - 1); }
on key "right" { at = min(pages - 1, at + 1); }

label "Flipbook";
label "Page " + (at + 1) + " of " + pages;
canvas 160, 120, page() { art[at * 192 + (y / 10) * 16 + x / 10] = 9; }
button "New page" {
  if pages < 20 {
    for i in 0..192 { push(art, 0); }
    pages += 1;
    at = pages - 1;
  }
}

// Batting practice: swing (space, Swing or a tap) as each pitch nears the plate; late is a
// home run, early a miss. Three innings; three strikes are an out, four balls a walk.
// icon: line 4 21 17 8 dot 19 6 3
state t = 0;                           // ms since Start
state speed = 0;                       // 100 while the game runs
state thrown = -1;                     // when the pitch in the air was thrown; -1 none
state swung = false;
state pitches = 0;                     // pitches thrown
state pattern = [1, 0, 0, 1, 0, 1, 1, 0];  // 1 a strike, 0 a ball, if not swung at
state balls = 0;
state strikes = 0;
state outs = 0;
state inning = 1;
state runs = 0;
state bases = [false, false, false];   // first, second, third
state last = "";

fn fresh() {
  balls = 0;
  strikes = 0;
}

// The third out clears the bases and ends the inning; the third inning's ends the game.
fn out() {
  fresh();
  outs += 1;
  last = "Out";
  if outs < 3 { return; }
  for b in 0..3 { bases[b] = false; }
  if inning == 3 {
    speed = 0;
    thrown = -1;
  } else {
    outs = 0;
    inning += 1;
  }
}

fn strike() {
  strikes += 1;
  last = "Strike";
  if strikes == 3 { out(); }
}

fn ball() {
  balls += 1;
  last = "Ball";
  if balls < 4 { return; }
  if bases[0] {
    if bases[1] {
      if bases[2] { runs += 1; }
      bases[2] = true;
    }
    bases[1] = true;
  }
  bases[0] = true;
  last = "Walk";
  fresh();
}

// A hit of n bases (4 a home run): every runner and the batter move on n.
fn hit(n: int, name: string) {
  for k in 0..3 {
    let b = 2 - k;
    if bases[b] {
      bases[b] = false;
      if b + n >= 3 { runs += 1; } else { bases[b + n] = true; }
    }
  }
  if n == 4 { runs += 1; } else { bases[n - 1] = true; }
  last = name;
  thrown = -1;
  fresh();
}

fn swing() {
  if speed == 0 || thrown < 0 || swung { return; }
  swung = true;
  let age = t - thrown;
  if age >= 900 {
    hit(4, "Home run");
  } else if age >= 800 {
    hit(2, "Double");
  } else if age >= 600 {
    hit(1, "Single");
  } else {
    strike();
  }
}

fn start() {
  t = 0;
  thrown = -1;
  pitches = 0;
  fresh();
  outs = 0;
  inning = 1;
  runs = 0;
  for b in 0..3 { bases[b] = false; }
  last = "";
  speed = 100;
}

every speed {
  t += 100;
  if thrown >= 0 && t - thrown >= 1000 {
    thrown = -1;
    if !swung {
      if pattern[(pitches - 1) % 8] == 1 { strike(); } else { ball(); }
    }
  }
  if speed > 0 && t >= 1000 && (t - 1000) % 2000 == 0 {
    thrown = t;
    swung = false;
    pitches += 1;
  }
}

on key "space" { swing(); }

// The field: the pitcher at the top, the plate at the bottom, the ball between; the bases at
// the side, yellow while a runner stands there.
fn scene() {
  rect(0, 0, 120, 160, 2);
  circle(60, 16, 6, 8);
  rect(54, 144, 12, 8, 7);
  let bx = [110, 100, 90];
  let by = [80, 70, 80];
  for b in 0..3 {
    let k = 7;
    if bases[b] { k = 3; }
    rect(bx[b] - 3, by[b] - 3, 6, 6, k);
  }
  if thrown >= 0 { circle(60, 16 + (t - thrown) * 128 / 1000, 3, 7); }
  if speed == 0 && pitches > 0 { text("Game over", 60, 60, 12, 11); }
}

label "Batting practice";
label "Inning " + inning + "   Outs " + outs + "   Runs " + runs;
label "Balls " + balls + "   Strikes " + strikes + "   " + last;
canvas 120, 160, scene() { swing(); }
row {
  button "Swing" { swing(); }
  if speed == 0 { button "Start" { start(); } }
}

// Baseball scorekeeper: tap what each pitch or play was; it keeps the count, outs, runners,
// inning and runs. Four balls walk, three strikes or three outs retire, nine innings end it.
// icon: ring 12 12 9 line 8 5 10 12 8 19 line 16 5 14 12 16 19
state balls = 0;
state strikes = 0;
state outs = 0;
state inning = 1;
state bottom = false;                 // the home team bats
state bases = [false, false, false];  // first, second, third
state away = 0;
state home = 0;
state over = false;

fn score(n: int) {
  if bottom { home += n; } else { away += n; }
}

fn next() {
  balls = 0;
  strikes = 0;
}

// A hit of n bases: every runner and the batter move up n (4 brings everyone home).
fn hit(n: int) {
  if over { return; }
  for k in 0..3 {
    let b = 2 - k;
    if bases[b] {
      bases[b] = false;
      if b + n >= 3 { score(1); } else { bases[b + n] = true; }
    }
  }
  if n >= 4 { score(1); } else { bases[n - 1] = true; }
  next();
}

// Ball four: the batter takes first, pushing on only the runners forced ahead of him.
fn walk() {
  if bases[0] {
    if bases[1] {
      if bases[2] { score(1); }
      bases[2] = true;
    }
    bases[1] = true;
  }
  bases[0] = true;
  next();
}

// An out; the third ends the half inning, and the ninth inning's bottom ends the game.
fn out() {
  if over { return; }
  next();
  outs += 1;
  if outs < 3 { return; }
  outs = 0;
  for b in 0..3 { bases[b] = false; }
  if bottom {
    if inning >= 9 && away != home { over = true; }
    inning += 1;
  }
  bottom = !bottom;
}

fn half() -> string {
  if bottom { return "bottom"; }
  return "top";
}

fn onbase() -> string {
  let names = ["1st", "2nd", "3rd"];
  let s = "";
  for b in 0..3 {
    if bases[b] { s = s + " " + names[b]; }
  }
  if s == "" { return "bases empty"; }
  return "on" + s;
}

fn result() -> string {
  if away > home { return "Final: Away wins"; }
  return "Final: Home wins";
}

label "Baseball scorekeeper";
if over {
  label result();
} else {
  label "Inning " + inning + " " + half() + ", " + onbase();
  label "Balls " + balls + "  Strikes " + strikes + "  Outs " + outs;
}
label "Away " + away + "  Home " + home;
row {
  button "Ball" {
    if !over {
      balls += 1;
      if balls == 4 { walk(); }
    }
  }
  button "Strike" {
    if !over {
      strikes += 1;
      if strikes == 3 { out(); }
    }
  }
  button "Foul" {
    if !over && strikes < 2 { strikes += 1; }
  }
  button "Out" { out(); }
}
row {
  button "Single" { hit(1); }
  button "Double" { hit(2); }
  button "Triple" { hit(3); }
  button "Home run" { hit(4); }
}

// Junction: cars cross on two roads; Switch (or space) gives the green to the other road. Get 20
// cars through: a switch while a car is in the crossing crashes, a full road jams.
// icon: loop 8 2 16 2 16 22 8 22 dot 12 7 3 dot 12 17 3
state pos = [0; 0];         // each car's square along its road, in the order they came
state way = [0; 0];         // each car's road: 0 across (row 4, rightward), 1 down (column 4)
state green = 0;            // the road with the green light
state steps = 0;
state through = 0;
state speed = 0;            // ms a step: 500 while it runs
state over = "";            // Crash, Jam or You win, once it is over
state names = ["across", "down"];

// Whether a car of road w is on square p of it.
fn on(w: int, p: int) -> bool {
  for i in 0..len(pos) {
    if pos[i] == p && way[i] == w { return true; }
  }
  return false;
}

fn finish(why: string) {
  over = why;
  speed = 0;
}

// A step: every car one square on, the front ones first; a car waits behind another and at a
// red light; one driving into the crossing while the other road's car was in it crashes.
fn step() {
  steps += 1;
  let inside = [on(0, 4), on(1, 4)];
  let ahead = [99, 99];
  let np = [0; 0];
  let nw = [0; 0];
  let crash = false;
  for i in 0..len(pos) {
    let w = way[i];
    let to = pos[i] + 1;
    if to == ahead[w] || (to == 4 && green != w) { to = pos[i]; }
    if to == 4 && pos[i] == 3 && inside[1 - w] { crash = true; }
    if to > 8 {
      through += 1;
      ahead[w] = 99;
    } else {
      push(np, to);
      push(nw, w);
      ahead[w] = to;
    }
  }
  pos = np;
  way = nw;
  if crash { finish("Crash"); return; }
  let gap = [2, 3];
  for w in 0..2 {
    if over == "" && steps % gap[w] == 0 {
      if on(w, 0) { finish("Jam"); } else { push(pos, 0); push(way, w); }
    }
  }
  if over == "" && through >= 20 { finish("You win"); }
}

fn swap() {
  if over == "" { green = 1 - green; }
}

fn reset() {
  clear(pos);
  clear(way);
  green = 0;
  steps = 0;
  through = 0;
  over = "";
}

every speed { step(); }
on key "space" { swap(); }

// The board, 9 x 9 squares of 12 units: the roads gray, cars blue across and red down; a green
// mark before the crossing on the road that may go.
fn scene() {
  let cells = [-1; 81];
  for k in 0..9 {
    cells[36 + k] = 8;
    cells[k * 9 + 4] = 8;
  }
  for i in 0..len(pos) {
    if way[i] == 0 { cells[36 + pos[i]] = 4; } else { cells[pos[i] * 9 + 4] = 1; }
  }
  pixels(cells, 0, 0, 9, 12);
  if green == 0 { circle(42, 42, 3, 2); } else { circle(42, 42, 3, 10); }
  if green == 1 { circle(66, 42, 3, 2); } else { circle(66, 42, 3, 10); }
  if over != "" { text(over, 54, 24, 14, 11); }
}

label "Junction";
label "Through " + through + "   Green: " + names[green];
canvas 108, 108, scene();
row {
  button "Switch" { swap(); }
  if speed == 0 && over == "" && steps == 0 { button "Start" { speed = 500; } }
  if over != "" { button "New game" { reset(); } }
}

// Crossroads: cars from the left and the top stop at red; Switch gives the other road the green.
// Count the cars through; a car driving into the middle while another is there crashes.
// icon: line 12 2 12 22 line 2 12 22 12 dot 12 12 3
state pos = [0; 0];         // each car's square along its road (4 the middle), in the order they came
state way = [0; 0];         // its road: 0 from the left, 1 from the top
state green = 0;
state through = 0;
state speed = 0;            // ms a step: 400 while it runs
state crashed = false;
state side = false;         // the road the next car comes on
state roads = ["left", "top"];

fn on(w: int, p: int) -> bool {
  for i in 0..len(pos) {
    if pos[i] == p && way[i] == w { return true; }
  }
  return false;
}

// Every car a square on, the front ones first, waiting behind a car or at a red light; then a
// car comes, on each road in turn.
fn step() {
  let inside = [on(0, 4), on(1, 4)];
  let ahead = [99, 99];
  let np = [0; 0];
  let nw = [0; 0];
  for i in 0..len(pos) {
    let w = way[i];
    let to = pos[i] + 1;
    if to == ahead[w] || (to == 4 && green != w) { to = pos[i]; }
    if to == 4 && inside[1 - w] { crashed = true; }
    if to > 8 { through += 1; } else { push(np, to); push(nw, w); }
    ahead[w] = to;
  }
  pos = np;
  way = nw;
  let w = 0;
  if side { w = 1; }
  if !on(w, 0) { push(pos, 0); push(way, w); }
  side = !side;
  if crashed { speed = 0; }
}

every speed { step(); }

// The crossroads, 9 x 9 squares of 12 units: the cars blue and red.
fn scene() {
  let cells = [-1; 81];
  for i in 0..len(pos) {
    if way[i] == 0 { cells[36 + pos[i]] = 4; } else { cells[pos[i] * 9 + 4] = 1; }
  }
  pixels(cells, 0, 0, 9, 12);
}

label "Crossroads";
label "Through " + through + "   Green: " + roads[green] + " road";
canvas 108, 108, scene();
if crashed { label "Crash! Game over"; }
row {
  button "Switch" { if !crashed { green = 1 - green; } }
  if speed == 0 && !crashed { button "Start" { speed = 400; } }
}

// Monster route: walk with the arrows (or the buttons); every 3rd step into the tall grass meets
// a wild monster. Attack to weaken it, throw a Ball to catch it. The yellow square heals.
// icon: ring 12 12 9 line 3 12 21 12 ring 12 12 3
state px = 0;               // where you stand on the 8 x 6 map
state py = 0;
state grass = 0;            // steps taken into the grass
state met = 0;              // wild monsters met
state foe = -1;             // the wild one now: 0 Sparkit, 1 Leafo, 2 Aquee; -1 none
state hp = 0;               // its HP
state health = 20;
state balls = 5;
state caught = 0;
state got = [false, false, false];
state dex = [""; 0];        // the names caught, in order
state names = ["Sparkit", "Leafo", "Aquee"];
state full = [9, 16, 15];

fn tall(x: int, y: int) -> bool { return x >= 4 && y >= 1 && y <= 4; }

fn done() -> bool { return got[0] && got[1] && got[2]; }

fn walk(dx: int, dy: int) {
  if foe >= 0 || done() { return; }
  let nx = px + dx;
  let ny = py + dy;
  if nx < 0 || nx > 7 || ny < 0 || ny > 5 { return; }
  px = nx;
  py = ny;
  if px == 0 && py == 5 {
    health = 20;
    balls = 5;
  }
  if tall(px, py) {
    grass += 1;
    if grass % 3 == 0 {
      foe = met % 3;
      hp = full[foe];
      met += 1;
    }
  }
}

// The wild one hits back for 3; at 0 health you black out: back to the start, healed.
fn hit() {
  health -= 3;
  if health <= 0 {
    health = 20;
    px = 0;
    py = 0;
    foe = -1;
  }
}

fn attack() {
  if foe < 0 { return; }
  hp = max(0, hp - 4);
  if hp == 0 { foe = -1; } else { hit(); }
}

// A ball catches it at half its HP or less; else it breaks free and hits back.
fn ball() {
  if foe < 0 || balls == 0 { return; }
  balls -= 1;
  if hp * 2 <= full[foe] {
    caught += 1;
    got[foe] = true;
    push(dex, names[foe]);
    foe = -1;
  } else {
    hit();
  }
}

fn collection() -> string {
  let s = "";
  for i in 0..len(dex) {
    if i > 0 { s = s + ", "; }
    s = s + dex[i];
  }
  return s;
}

// The map, 8 x 6 squares of 16 units: grass green, the healing square yellow, you blue; below it
// the wild monster.
fn scene() {
  let cells = [-1; 48];
  for i in 0..48 {
    if tall(i % 8, i / 8) { cells[i] = 2; }
  }
  cells[40] = 3;
  cells[py * 8 + px] = 4;
  pixels(cells, 0, 0, 8, 16);
  if foe >= 0 {
    let tint = [3, 2, 6];
    circle(64, 116, 14, tint[foe]);
    circle(58, 112, 2, 9);
    circle(70, 112, 2, 9);
  }
  if done() { text("You caught them all!", 64, 116, 10, 11); }
}

on key "left" { walk(-1, 0); }
on key "right" { walk(1, 0); }
on key "up" { walk(0, -1); }
on key "down" { walk(0, 1); }

label "Monster route";
label "Health " + health + "   Balls " + balls + "   Caught " + caught;
canvas 128, 136, scene();
if foe >= 0 {
  label "A wild " + names[foe] + "!   HP " + hp;
  row {
    button "Attack" { attack(); }
    button "Ball" { ball(); }
    button "Run" { foe = -1; }
  }
} else {
  row {
    button "Left" { walk(-1, 0); }
    button "Up" { walk(0, -1); }
    button "Down" { walk(0, 1); }
    button "Right" { walk(1, 0); }
  }
}
label "Collection: " + collection();

