  if over != "" { button "New game" { reset(); } }
}

// Skirmish: earn a gold a second; a Soldier (5 gold) marches right and fights the enemy's on the
// way. Three hits on a base destroy it.
// icon: fill 3 20 3 10 7 10 7 14 9 14 9 20 line 11 15 21 15 fill 21 15 17 12 17 18
state mine = [0; 0];        // your soldiers' squares on a lane of 10
state foes = [0; 0];        // the enemy's
state gold = 0;
state base = 3;
state enemy = 3;
state speed = 0;            // ms a second: 1000 while it runs
state wave = 0;             // ms between enemy soldiers: 6000 while it runs
state over = "";

// A second: a gold; each soldier a square on (meeting one of the other side, both fall); one
// past the end hits that base.
fn tick() {
  gold += 1;
  for i in 0..len(mine) { mine[i] += 1; }
  for i in 0..len(foes) { foes[i] -= 1; }
  if len(mine) > 0 && len(foes) > 0 && foes[0] <= mine[0] {
    remove(mine, 0);
    remove(foes, 0);
  }
  if len(mine) > 0 && mine[0] > 9 {
    remove(mine, 0);
    enemy -= 1;
  }
  if len(foes) > 0 && foes[0] < 0 {
    remove(foes, 0);
    base -= 1;
  }
  if enemy == 0 { over = "You win"; }
  if base == 0 { over = "Your base is destroyed: you lose"; }
  if over != "" {
    speed = 0;
    wave = 0;
  }
}

every speed { tick(); }
every wave { push(foes, 9); }

// The lane, from your base on the left to the enemy's on the right: soldiers blue and red.
