// Sheet: tap a cell, type a number (or =SUM, =MAX) and press Set; formulas work on the cells
// above them and update as you go. Fill down copies a cell into the one below.
// icon: loop 3 4 21 4 21 20 3 20 line 3 9 21 9 line 9 4 9 20 line 15 4 15 20
state raw = [""; 24];       // 4 columns x 6 rows, row by row: what was typed
state nums = [0; 24];       // each cell's value (text and empty cells count 0)
state sel = 0;
state entry = "";
state letters = ["A", "B", "C", "D"];

fn formula(s: string) -> bool { return s == "=SUM" || s == "=MAX"; }

// Every cell's value, top row first, so a formula sees the values above it.
fn compute() {
  for i in 0..24 {
    let s = raw[i];
    let v = parse(s, 0);
    if formula(s) {
      v = 0;
      let k = i - 4;
      repeat i / 4 {
        if s == "=SUM" { v += nums[k]; } else { v = max(v, nums[k]); }
        k -= 4;
      }
    }
    nums[i] = v;
  }
}

// What a cell shows: a formula its value, else what was typed.
fn shown(i: int) -> string {
  if formula(raw[i]) { return "" + nums[i]; }
  return raw[i];
}

fn put(s: string) {
  raw[sel] = s;
  compute();
}

fn set() {
  put(entry);
  entry = "";
}

fn down() {
  if sel < 20 {
    raw[sel + 4] = raw[sel];
    sel += 4;
    compute();
  }
}

fn name(i: int) -> string { return letters[i % 4] + (i / 4 + 1); }

on key "enter" { set(); }

// The cells, 24 units square: the selected one blue, formulas green; each shows its value.
fn sheet() {
  let cells = [-1; 24];
  for i in 0..24 {
    if formula(raw[i]) { cells[i] = 2; }
  }
  cells[sel] = 4;
  pixels(cells, 0, 0, 4, 24);
  for i in 0..24 { text(shown(i), i % 4 * 24 + 12, i / 4 * 24 + 12, 8, 9); }
}

label "Sheet";
canvas 96, 144, sheet() { sel = min(23, y / 24 * 4 + x / 24); }
label name(sel) + " = " + shown(sel);
row {
  input entry;
  button "Set" { set(); }
  button "Clear" { put(""); }
  button "Fill down" { down(); }
}

// Sheet: type whole numbers into the boxes; each column is totalled underneath, with a grand
// total and the biggest number.
// icon: loop 3 4 21 4 21 20 3 20 line 3 9 21 9 line 9 4 9 20 line 15 4 15 20
state a1 = "";
state b1 = "";
state c1 = "";
state a2 = "";
state b2 = "";
state c2 = "";
state a3 = "";
state b3 = "";
state c3 = "";
state a4 = "";
state b4 = "";
state c4 = "";

fn n(s: string) -> int { return parse(s, 0); }

fn ta() -> int { return n(a1) + n(a2) + n(a3) + n(a4); }
fn tb() -> int { return n(b1) + n(b2) + n(b3) + n(b4); }
fn tc() -> int { return n(c1) + n(c2) + n(c3) + n(c4); }

fn most() -> int {
  let all = [a1, b1, c1, a2, b2, c2, a3, b3, c3, a4, b4, c4];
  let m = n(a1);
  for i in 0..12 { m = max(m, n(all[i])); }
  return m;
}

label "Sheet";
