// Blitz clock 3+2: Start runs White's clock; a player presses their button when their move is done,
// which adds 2 seconds to their clock and starts the other's.
// icon: loop 2 7 22 7 22 19 2 19 ring 7 13 4 ring 17 13 4 line 7 13 7 9 line 17 13 20 10 line 15 4 19 4
state white = 180;        // seconds left on each clock
state black = 180;
state whites = true;      // White's clock is the one to run, else Black's
state speed = 0;          // ms a step; 0 while both are stopped
state moves = 0;
state out = "";           // who ran out of time, else ""

// Seconds as two digits: 5 is 05.
fn two(n: int) -> string {
  if n < 10 { return "0" + n; }
  return "" + n;
}

fn clock(s: int) -> string { return s / 60 + ":" + two(s % 60); }

// A player's move is done: only while their own clock runs.
fn done(w: bool) {
  if speed == 0 || whites != w { return; }
  if w { white += 2; } else { black += 2; }
  whites = !w;
  moves += 1;
}

every speed {
  if whites { white -= 1; } else { black -= 1; }
  if white == 0 { out = "White"; }
  if black == 0 { out = "Black"; }
  if out != "" { speed = 0; }
}

label "Blitz clock 3+2";
label "White " + clock(white);
label "Black " + clock(black);
label "Moves: " + moves;
if out != "" { label out + " is out of time"; }
row {
  button "White" { done(true); }
  button "Black" { done(false); }
}
button "Start" {
  white = 180;
  black = 180;
  whites = true;
  moves = 0;
  out = "";
  speed = 1000;
}

// Blitz clock: 5 minutes each. Start runs White's clock, Move hands it to the other player, Pause
// stops it; a clock at 0:00 loses on time. Reset puts both back at 5:00.
// icon: loop 2 7 22 7 22 19 2 19 ring 7 13 4 ring 17 13 4 line 7 13 7 9 line 17 13 20 10 line 5 4 9 4
state white = 300;        // seconds left on each clock
state black = 300;
state whites = true;      // White's clock is the one to run, else Black's
state speed = 0;          // ms a step; 0 while both are stopped
state lost = "";          // who lost on time, else ""

// Seconds as two digits: 5 is 05.
fn two(n: int) -> string {
  if n < 10 { return "0" + n; }
  return "" + n;
}

fn clock(s: int) -> string { return s / 60 + ":" + two(s % 60); }

every speed {
  if whites { white -= 1; } else { black -= 1; }
  if white == 0 {
    lost = "White";
    speed = 0;
  }
  if black == 0 {
    lost = "Black";
    speed = 0;
  }
}

label "Blitz clock";
label "White " + clock(white);
label "Black " + clock(black);
if lost != "" { label lost + " lost on time"; }
row {
  button "Start" { if lost == "" { speed = 1000; } }
  button "Move" { if speed > 0 { whites = !whites; } }
  button "Pause" { speed = 0; }
  button "Reset" {
    white = 300;
    black = 300;
    whites = true;
    speed = 0;
    lost = "";
  }
}

// Contacts: type a name and press Add; tap a contact to make it a favorite, or tap again to not.
// icon: ring 9 7 3 arc 9 17 5 270 90 fill 18 9 19 12 22 12 20 14 21 17 18 15 15 17 16 14 14 12 17 12
saved state names = [""; 0];
saved state fav = [false; 0];
state typed = "";

// Where s is on the list; -1 if it is not.
fn find(s: string) -> int {
  for i in 0..len(names) {
    if names[i] == s { return i; }
  }
  return -1;
}

fn starred(i: int) -> bool { return i < len(fav) && fav[i]; }

// A star after a favorite's name.
fn star(i: int) -> string {
  if starred(i) { return " *"; }
  return "";
}

// The favorites in list order, joined by commas.
fn favorites() -> string {
  let s = "";
  for i in 0..len(names) {
    if starred(i) {
      if s != "" { s = s + ", "; }
      s = s + names[i];
    }
  }
  if s == "" { return "none"; }
  return s;
}

// A saved list may come back shorter than the names: fill it out to match them.
fn fill() {
  for k in len(fav)..len(names) { push(fav, false); }
}

label "Contact list";
row {
  input typed;
  button "Add" {
    if typed != "" && find(typed) < 0 {
      push(names, typed);
      fill();
      typed = "";
    }
  }
}
for i in 0..len(names) {
  button names[i] + star(i) {
    fill();
    fav[i] = !fav[i];
  }
}
label "Contacts: " + len(names);
label "Favorites: " + favorites();

// Phone book: type a name and a number and press Save; type a name in the last box to look up
// its number.
// icon: loop 6 2 20 2 20 22 6 22 ring 13 8 3 arc 13 17 5 270 90 line 3 6 8 6 line 3 12 8 12 line 3 18 8 18
saved state names = [""; 0];
saved state numbers = [""; 0];
state name = "";
state number = "";
state wanted = "";

// Where s is in the book; -1 if it is not.
fn find(s: string) -> int {
  for i in 0..len(names) {
    if names[i] == s { return i; }
  }
  return -1;
}

fn found() -> string {
  let i = find(wanted);
  if i < 0 || i >= len(numbers) { return "Not found"; }
  return "Number: " + numbers[i];
}

fn save() {
  if name == "" || number == "" { return; }
  let i = find(name);
  if i < 0 {
    push(names, name);
    push(numbers, number);
  } else {
    numbers[i] = number;
  }
  name = "";
  number = "";
}

label "Phone book";
row { label "Name"; input name; }
row { label "Number"; input number; }
button "Save" { save(); }
row { label "Look up"; input wanted; }
label found();
label "Contacts: " + len(names);

// Lending list: type a thing and press Lend, or Returned when it is back; Next day moves the
// calendar on, and things out more than 7 days are overdue.
// icon: loop 3 5 21 5 21 21 3 21 line 3 10 21 10 line 8 2 8 7 line 16 2 16 7 line 9 15 11 18 16 13
state day = 1;
state things = [""; 0];
state lent = [0; 0];      // the day each thing was lent
state typed = "";

// Where s is on the list; -1 if it is not out.
fn find(s: string) -> int {
  for i in 0..len(things) {
    if things[i] == s { return i; }
  }
  return -1;
}

fn late(i: int) -> bool { return day - lent[i] > 7; }

fn overdue() -> int {
  let n = 0;
  for i in 0..len(things) {
    if late(i) { n += 1; }
  }
  return n;
}

fn shown(i: int) -> string {
  let s = things[i] + ": " + (day - lent[i]) + " days";
  if late(i) { return s + " (late)"; }
  return s;
}

label "Lending list";
row {
  label "Day " + day;
  button "Next day" { day += 1; }
}
row {
  input typed;
  button "Lend" {
    if typed != "" && find(typed) < 0 {
      push(things, typed);
      push(lent, day);
      typed = "";
    }
  }
  button "Returned" {
    let i = find(typed);
    if i >= 0 {
      remove(things, i);
      remove(lent, i);
    }
  }
}
for i in 0..len(things) { label shown(i); }
label "Overdue: " + overdue();

