// Room planner: pick Bed, Desk or Chair and tap the floor to put it down by its top left
// corner; with Remove picked, a tap takes a piece away.
// icon: loop 3 3 21 3 21 21 3 21 fill 6 6 11 6 11 14 6 14 fill 13 17 19 17 19 19 13 19
state floor = [0; 80];    // 10 x 8 squares: each one's color, 0 free
state owner = [0; 80];    // the number of the piece on each square, 0 none
state made = 0;           // pieces put down so far: the last one's number
state pieces = 0;
state tool = 0;           // 0 bed, 1 desk, 2 chair, 3 remove
state ws = [2, 3, 1];     // each piece's columns, rows and color
state hs = [3, 1, 1];
state cs = [4, 3, 1];
state tools = ["Bed", "Desk", "Chair", "Remove"];

// Whether piece k fits with its top left corner on (c, r): on the floor, every square free.
fn fits(k: int, c: int, r: int) -> bool {
  if c + ws[k] > 10 || r + hs[k] > 8 { return false; }
  for a in c..c + ws[k] {
    for b in r..r + hs[k] {
      if owner[b * 10 + a] > 0 { return false; }
    }
  }
  return true;
}

fn put(k: int, c: int, r: int) {
  made += 1;
  pieces += 1;
  for a in c..c + ws[k] {
    for b in r..r + hs[k] {
      floor[b * 10 + a] = cs[k];
      owner[b * 10 + a] = made;
    }
  }
}

// Takes away the whole piece on square i, if one is there.
fn take(i: int) {
  let p = owner[i];
  if p == 0 { return; }
  for j in 0..80 {
    if owner[j] == p {
      owner[j] = 0;
      floor[j] = 0;
    }
  }
  pieces -= 1;
}

fn tap(i: int) {
  if tool == 3 {
    take(i);
  } else if fits(tool, i % 10, i / 10) {
    put(tool, i % 10, i / 10);
  }
}

