// Stacker: move the row with the arrows and drop it with space; blocks over nothing fall off and
// the next row is that much shorter. Miss completely and it is over; reach the top to win.
// icon: fill 3 17 21 17 21 22 3 22 fill 6 11 18 11 18 16 6 16 fill 9 5 15 5 15 10 9 10
state board = [0; 70];    // 7 x 10 squares: 4 a stacked block
state at = 9;             // the moving row: its row, its left column and its width
state bx = 0;
state wide = 3;
state playing = false;
state said = "";

fn start() {
  board = [0; 70];
  at = 9;
  bx = 0;
  wide = 3;
  said = "";
  playing = true;
}

fn move(d: int) {
  if playing { bx = max(0, min(7 - wide, bx + d)); }
}

// Drops the row: what has a block under it stays; the next row starts above, or it ends.
fn drop() {
  if !playing { return; }
  let kept = 0;
  let first = -1;
  for c in bx..bx + wide {
    if at == 9 || board[(at + 1) * 7 + c] == 4 {
      board[at * 7 + c] = 4;
      kept += 1;
      if first < 0 { first = c; }
    }
  }
  if kept == 0 {
    said = "Game over";
    playing = false;
  } else if at == 0 {
    said = "You win";
    playing = false;
  } else {
    at -= 1;
    bx = first;
    wide = kept;
  }
}

on key "left" { move(-1); }
on key "right" { move(1); }
on key "space" { drop(); }

fn scene() {
  let b = [-1; 70];
  for i in 0..70 {
    if board[i] == 4 { b[i] = 4; }
  }
  if playing {
    for c in bx..bx + wide { b[at * 7 + c] = 2; }
  }
  pixels(b, 0, 0, 7, 14);
