// Whether the top two cards of the pile match.
fn pair() -> bool {
  let n = len(pile);
  if n < 2 { return false; }
  return pile[n - 1] == pile[n - 2];
}

// The game ends once the deck is used up and no match is left on top.
fn over() {
  if dealt == len(deck) && !pair() {
    playing = false;
    if red > blue {
      said = "Red wins";
    } else if blue > red {
      said = "Blue wins";
    } else {
      said = "Draw";
    }
  }
}

fn deal(p: int) {
  if !playing || turn != p || dealt == len(deck) { return; }
  push(pile, deck[dealt]);
  dealt += 1;
  turn = 1 - turn;
  over();
}

fn snap(p: int) {
  if !playing { return; }
  if pair() {
    if p == 0 { red += len(pile); } else { blue += len(pile); }
    clear(pile);
  } else if p == 0 {
    blue += 1;
  } else {
    red += 1;
  }
  over();
}

fn start() {
  clear(pile);
  dealt = 0;
  red = 0;
  blue = 0;
  turn = 0;
  said = "";
  playing = true;
}

