// Chutes and ladders for you and your son with a real die: tap the number rolled to move whoever's
// turn it is, you first. Ladders climb, chutes slide; first to 100 wins.
// icon: line 6 21 6 3 line 13 21 13 3 line 6 8 13 8 line 6 14 13 14 line 18 4 21 10 15 15 19 21
state from = [3, 8, 28, 58, 80, 52, 57, 62, 88, 95];
state to = [22, 30, 84, 77, 99, 29, 40, 22, 18, 51];
state at = [0, 0];        // your square, your son's: 0 off the board
state turn = 0;           // 0 you, 1 your son
state winner = -1;

fn jump(n: int) -> int {
  for i in 0..len(from) {
    if from[i] == n { return to[i]; }
  }
  return n;
}

// A roll of d moves whoever's turn it is, unless it would go past 100; then the turn passes.
fn move(d: int) {
  if winner >= 0 { return; }
  if at[turn] + d <= 100 { at[turn] = jump(at[turn] + d); }
  if at[turn] == 100 { winner = turn; } else { turn = 1 - turn; }
}

// Square n's place on the board, 10 a row: 1 at the bottom left, the rows snaking up to 100.
fn cell(n: int) -> int {
  let r = (n - 1) / 10;
  if r % 2 == 0 { return (9 - r) * 10 + (n - 1) % 10; }
  return (9 - r) * 10 + 9 - (n - 1) % 10;
}

fn mid(n: int) -> int { return cell(n) % 10 * 12 + 6; }

fn top(n: int) -> int { return cell(n) / 10 * 12 + 6; }

// The board, ladders green and chutes yellow, and over them you red and your son blue.
fn scene() {
  pixels([7; 100], 0, 0, 10, 12);
  for i in 0..len(from) {
    let k = 2;
    if to[i] < from[i] { k = 3; }
    line(mid(from[i]), top(from[i]), mid(to[i]), top(to[i]), 2, k);
  }
  if at[0] > 0 { circle(mid(at[0]), top(at[0]), 5, 1); }
  if at[1] > 0 { circle(mid(at[1]), top(at[1]), 5, 4); }
}

fn status() -> string {
  if winner == 0 { return "You win!"; }
  if winner == 1 { return "Your son wins!"; }
  if turn == 0 { return "Your turn"; }
  return "Your son's turn";
}

