// Takuzu: fill the board red and blue: no three of a color side by side, three of each in every
// row and column, no two rows or columns alike. A tap turns a square red, then blue, then blank.
// icon: fill 3 3 11 3 11 11 3 11 ring 17 7 4 ring 7 17 4 fill 13 13 21 13 21 21 13 21
state given = [
  4, 4, 0, 0, 0, 0,
  0, 1, 0, 0, 4, 0,
  0, 0, 4, 0, 0, 4,
  0, 0, 0, 0, 1, 4,
  4, 4, 0, 0, 0, 0,
  1, 0, 0, 4, 0, 0
];                        // the puzzle, row by row from the top: 1 red, 4 blue, 0 blank
state mine = [0; 36];     // the colors I set

fn at(i: int) -> int { return given[i] + mine[i]; }

// Square j of line k: rows 0 to 5, then columns 6 to 11.
fn sq(k: int, j: int) -> int {
  if k < 6 { return k * 6 + j; }
  return j * 6 + k - 6;
}

// Whether line k breaks a rule: three of one color side by side, or more than three of one.
fn broken(k: int) -> bool {
  let reds = 0;
  let blues = 0;
  for j in 0..6 {
    let v = at(sq(k, j));
    if v == 1 { reds += 1; }
    if v == 4 { blues += 1; }
    if j >= 2 && v > 0 && at(sq(k, j - 1)) == v && at(sq(k, j - 2)) == v { return true; }
  }
  return reds > 3 || blues > 3;
}

fn errors() -> int {
  let n = 0;
  for k in 0..12 {
    if broken(k) { n += 1; }
  }
  return n;
}

fn left() -> int {
  let n = 0;
  for i in 0..36 {
    if at(i) == 0 { n += 1; }
  }
  return n;
}

fn alike(a: int, b: int) -> bool {
  for j in 0..6 {
    if at(sq(a, j)) != at(sq(b, j)) { return false; }
  }
  return true;
}

fn solved() -> bool {
  if left() > 0 || errors() > 0 { return false; }
  for a in 0..12 {
    for b in a + 1..12 {
      if (a < 6) == (b < 6) && alike(a, b) { return false; }
    }
  }
  return true;
}

// A square not given turns red, then blue, then blank.
fn tap(i: int) {
  if given[i] > 0 || solved() { return; }
  if mine[i] == 0 { mine[i] = 1; } else if mine[i] == 1 { mine[i] = 4; } else { mine[i] = 0; }
}

// The board, squares 18 units wide on gray; a given square has a dot in its corner.
fn scene() {
  rect(0, 0, 120, 120, 8);
  for i in 0..36 {
    let px = (i % 6) * 20;
    let py = (i / 6) * 20;
    rect(px + 1, py + 1, 18, 18, at(i));
    if given[i] > 0 { circle(px + 4, py + 4, 1, 9); }
  }
}

fn status() -> string {
  if solved() { return "Solved"; }
  return "Tap a square: red, blue, blank";
}

