fn run(p: int, c: int, r: int, dc: int, dr: int) -> bool {
  for k in 0..5 {
    let x = c + dc * k;
    let y = r + dr * k;
    if x < 0 || x > 5 || y < 0 || y > 5 || board[y * 6 + x] != p { return false; }
  }
  return true;
}

fn five(p: int) -> bool {
  for i in 0..36 {
    let c = i % 6;
    let r = i / 6;
    if run(p, c, r, 1, 0) || run(p, c, r, 0, 1) || run(p, c, r, 1, 1) || run(p, c, r, 1, -1) {
      return true;
    }
  }
  return false;
}

// A tap places a marble on an empty hole, or once one is placed picks the block it is in.
fn tap(c: int, r: int) {
