state suits = ["♣", "♦", "♥", "♠"];
state turn = 1;           // the 7♦'s holder starts
state winner = -1;

fn card(k: int) -> string { return ranks[k % 13] + suits[k / 13]; }

fn name(p: int) -> string {
  if p == 0 { return "Me"; }
  return "Friend";
}

// The 7♦ first; then a 7, or a card whose neighbour toward its suit's 7 is on the table.
fn playable(k: int) -> bool {
  let r = k % 13;
  if holder[k] < 0 { return false; }
  if holder[19] >= 0 { return k == 19; }
  if r == 6 { return true; }
  if r < 6 { return holder[k + 1] < 0; }
  return holder[k - 1] < 0;
}

fn can(p: int) -> bool {
  for k in 0..52 {
    if holder[k] == p && playable(k) { return true; }
  }
  return false;
}

fn play(k: int) {
  if winner >= 0 || holder[k] != turn || !playable(k) { return; }
  holder[k] = -1;
  winner = turn;
  for j in 0..52 {
    if holder[j] == turn { winner = -1; }
  }
  if winner < 0 { turn = 1 - turn; }
}

// The table: a row a suit, A to K; a played card yellow.
fn scene() {
  let b = [0; 52];
  for k in 0..52 {
    if holder[k] < 0 { b[k] = 3; }
  }
  pixels(b, 0, 0, 13, 12);
}

fn status() -> string {
  if winner == 0 { return "You win!"; }
  if winner == 1 { return "Your friend wins!"; }
  return name(turn) + ": your turn";
}

