fn begin(b: int) {
  bout = b;
  at = 0;
  speed = rates[b - 1];
}

fn shove(by: int) {
  at += by;
  if at >= 5 && bout == 3 {
    said = "You win";
    speed = 0;
  } else if at >= 5 {
    begin(bout + 1);
  } else if at <= -5 {
    said = "Game over";
    speed = 0;
  }
}

