  speed = 100;
}

// The ball reached the keeper's row: a save or a goal; then the next kick, or the end.
fn arrive() {
  if kx != bx && mine { me += 1; }
  if kx != bx && !mine { cpu += 1; }
  if !mine && round == 5 {
    speed = 0;
    if me > cpu { result = "You win"; } else if me < cpu { result = "You lose"; } else { result = "Draw"; }
    return;
  }
  if !mine { round += 1; }
  mine = !mine;
  setup();
}

every speed {
  if flight > 0 {
    by -= 1;
    if mine && flight % 2 == 0 && kx != bx { kx += (bx - kx) / abs(bx - kx); }
    flight += 1;
    if by == 1 { arrive(); }
  }
}

fn kick() {
  if speed > 0 && mine && flight == 0 { flight = 1; }
}

// Left and right: my ball while it waits, or me as the keeper.
fn side(d: int) {
  if speed == 0 { return; }
  if mine && flight == 0 { bx = min(7, max(1, bx + d)); }
  if !mine { kx = min(7, max(1, kx + d)); }
}

// A tap steps the ball (or me) a column toward it.
fn toward(c: int) {
  let at = kx;
  if mine { at = bx; }
  if c != at { side((c - at) / abs(c - at)); }
}

on key "left" { side(-1); }
on key "right" { side(1); }
on key "space" { kick(); }

