// The duck is gone, hit or not: the next one, or the round's end.
fn gone() {
  if duck < 5 {
    duck += 1;
    appear();
  } else if hits < 3 {
    result = "Game over";
    speed = 0;
  } else if round == 2 {
    result = "You win";
    speed = 0;
  } else {
    round = 2;
    duck = 1;
    hits = 0;
    appear();
  }
}

every speed {
