      if py + dy < 0 || py + dy > 6 { dy = -dy; }
      px += dx;
      py += dy;
    }
  }
}

fn shoot(c: int, r: int) {
  if speed == 0 { return; }
  if c == px && r == py {
    hits += 1;
    gone();
