// Rope swing: you hang from a swinging rope; space or Let go lets go, and you fly the way it
// swings, falling as you go. Catch the next rope, and from the last land on the far ledge.
// icon: line 4 3 10 15 line 14 3 20 13 dot 10 16 3 line 2 21 7 21 line 17 21 22 21
state rows = [2, 3, 4];         // each rope's handle: its row, the ends of its swing, where it is
state lo = [2, 6, 10];
state hi = [4, 9, 12];
state hx = [2, 9, 12];
state way = [1, -1, -1];
state hold = 0;                 // the rope held, or -1 while flying
state fx = 0;                   // the flier: square, way, steps flown, the rope let go
state fy = 0;
state fw = 0;
state flown = 0;
state from = 0;
state steps = 0;                // steps since the level began
state level = 1;
state lives = 3;
state speed = 0;                // ms a step; 0 while no game runs
state result = "";

// A level begins holding the first rope, the handles at their starts.
fn begin() {
  if level == 1 {
    hx = [2, 9, 12];
    way = [1, -1, -1];
  } else {
    hx = [2, 6, 10];
    way = [1, 1, 1];
  }
  hold = 0;
  steps = 0;
}

fn start() {
  level = 1;
  lives = 3;
  result = "";
  begin();
  speed = 100;
}

fn fall() {
  lives -= 1;
  begin();
  if lives == 0 {
    result = "Game over";
    speed = 0;
  }
}

fn land() {
  if level == 2 {
    result = "You win";
    speed = 0;
  } else {
    level = 2;
    begin();
  }
}

every speed {
  steps += 1;
  if steps % (3 - level) == 0 {
    for k in 0..3 {
      if hx[k] + way[k] < lo[k] || hx[k] + way[k] > hi[k] { way[k] = -way[k]; }
      hx[k] += way[k];
    }
  }
  if hold < 0 {
    flown += 1;
    fx += fw;
    if flown >= 2 { fy += 1; }
    if fx < 0 || fx > 15 || fy == 6 && fx < 14 {
      fall();
    } else if fy == 6 {
      land();
    } else {
      for k in 0..3 {
        if hold < 0 && k != from && hx[k] == fx && rows[k] == fy { hold = k; }
      }
    }
  }
}

fn letgo() {
  if speed > 0 && hold >= 0 {
    fx = hx[hold];
    fy = rows[hold];
    fw = way[hold];
    flown = 0;
    from = hold;
    hold = -1;
  }
}

