// JezzBall: tap an empty square to build a wall from it, up and down or (Turn, or space) left
// and right. A ball touching a growing wall breaks it and costs a life; a finished wall fills in
// the space with no ball. Fill 75% to clear a level; two levels.
// icon: ring 7 7 3 ring 17 15 3 line 12 3 12 21 fill 13 3 21 3 21 9 13 9
state filled = [false; 96];     // the board, 12 x 8: square c + 12 * r
state wall = [false; 96];       // the wall growing, if any
state building = false;
state ends = [0, 0, 0, 0];      // its two ends' squares, and whether each has stopped
state stopped = [false, false];
state down = true;              // the way walls grow: up and down, else left and right
state vertical = true;          // the way the wall growing now grows
state bx = [0; 0];              // the balls: square and way
state by = [0; 0];
state dx = [0; 0];
state dy = [0; 0];
state level = 1;
state lives = 3;
state speed = 0;                // ms a step; 0 while no game runs
state result = "";

fn solid(c: int, r: int) -> bool { return c < 0 || c > 11 || r < 0 || r > 7 || filled[r * 12 + c]; }

fn count() -> int {
  let n = 0;
  for i in 0..96 {
    if filled[i] { n += 1; }
  }
  return n;
}

fn begin() {
  for i in 0..96 {
    filled[i] = false;
    wall[i] = false;
  }
  building = false;
  bx = [2, 9];
  by = [1, 6];
  dx = [1, -1];
  dy = [1, -1];
  if level == 1 { bx = [2]; by = [1]; dx = [1]; dy = [1]; }
}

fn start() {
  level = 1;
  lives = 3;
  down = true;
  result = "";
  begin();
  speed = 200;
}

fn hits() -> bool {
  for i in 0..len(bx) {
    if building && wall[by[i] * 12 + bx[i]] { return true; }
  }
  return false;
}

fn broken() {
  for i in 0..96 { wall[i] = false; }
  building = false;
  lives -= 1;
  if lives == 0 {
    result = "Game over";
    speed = 0;
  }
}

// One end of the wall grows a square its way, or stops at the edge or a filled square.
fn grow(e: int, x: int, y: int) {
  if stopped[e] { return; }
  let c = ends[e * 2] + x;
  let r = ends[e * 2 + 1] + y;
  if solid(c, r) {
    stopped[e] = true;
  } else {
    ends[e * 2] = c;
    ends[e * 2 + 1] = r;
    wall[r * 12 + c] = true;
  }
}

// The wall is done: it fills, and so does every square no ball can reach.
fn finish() {
  let reach = [false; 96];
  let todo = [0; 0];
  for i in 0..96 {
    if wall[i] { filled[i] = true; }
    wall[i] = false;
  }
  building = false;
  for i in 0..len(bx) {
    reach[by[i] * 12 + bx[i]] = true;
    push(todo, by[i] * 12 + bx[i]);
  }
  for k in 0..96 {
    if k < len(todo) {
      let c = todo[k] % 12;
      let r = todo[k] / 12;
      let nx = [c - 1, c + 1, c, c];
      let ny = [r, r, r - 1, r + 1];
      for j in 0..4 {
        if !solid(nx[j], ny[j]) && !reach[ny[j] * 12 + nx[j]] {
          reach[ny[j] * 12 + nx[j]] = true;
          push(todo, ny[j] * 12 + nx[j]);
        }
      }
    }
  }
  for i in 0..96 {
    if !reach[i] { filled[i] = true; }
  }
}

fn bounce(i: int) {
  if solid(bx[i] + dx[i], by[i]) { dx[i] = -dx[i]; }
  if solid(bx[i], by[i] + dy[i]) { dy[i] = -dy[i]; }
  if solid(bx[i] + dx[i], by[i] + dy[i]) {
    dx[i] = -dx[i];
    dy[i] = -dy[i];
  }
  if !solid(bx[i] + dx[i], by[i] + dy[i]) {
    bx[i] += dx[i];
    by[i] += dy[i];
  }
}

every speed {
  let done = false;
  if building {
    let x = 1;
    let y = 0;
    if vertical { x = 0; y = 1; }
    grow(0, -x, -y);
    grow(1, x, y);
    if hits() {
      broken();
    } else if stopped[0] && stopped[1] {
      finish();
      done = true;
    }
  }
  if speed == 0 { return; }
  for i in 0..len(bx) { bounce(i); }
  if hits() { broken(); }
  if done && count() * 100 / 96 >= 75 {
    if level == 2 {
      result = "You win";
      speed = 0;
    } else {
      level = 2;
      begin();
    }
  }
}

fn tap(c: int, r: int) {
  if speed == 0 || building || solid(c, r) { return; }
  for i in 0..len(bx) {
    if bx[i] == c && by[i] == r { return; }
  }
  building = true;
  vertical = down;
  wall[r * 12 + c] = true;
  ends = [c, r, c, r];
  stopped = [false, false];
}

fn turn() {
  if speed > 0 { down = !down; }
}

on key "space" { turn(); }

fn way() -> string {
  if down { return "down"; }
  return "across";
}

fn scene() {
  let cells = [-1; 96];
  for i in 0..96 {
    if filled[i] { cells[i] = 8; }
    if wall[i] { cells[i] = 4; }
  }
  for i in 0..len(bx) { cells[by[i] * 12 + bx[i]] = 1; }
  pixels(cells, 0, 0, 12, 10);
  if result != "" { text(result, 60, 40, 14, 11); }
}

label "JezzBall";
label "Level: " + level + "   Lives: " + lives + "   Filled: " + count() * 100 / 96 + "%   Wall: " + way();
canvas 120, 80, scene() { tap(x / 10, y / 10); }
row {
  if speed == 0 { button "Start" { start(); } }
  button "Turn" { turn(); }
}

// Rummy against the computer: tap the stock or the discard pile to draw, then tap one of your
// cards to discard it. Make two melds of three (a set of one rank, or a run in one suit) to win.
// icon: loop 3 6 11 6 11 18 3 18 loop 8 4 16 4 16 16 8 16 loop 13 6 21 6 21 18 13 18
state deck = [9, 10, 11, 4, 20, 31, 28, 5, 6, 17, 25, 8, 14, 21, 2, 7, 3, 26, 27, 16, 19, 29,
  24, 13, 23, 18, 1, 0, 30, 15, 12, 22];   // a card is suit * 8 + rank - 1, suits S H D C
state ranks = ["A", "2", "3", "4", "5", "6", "7", "8"];
state suits = ["S", "H", "D", "C"];
state me = [0; 0];
state cpu = [0; 0];
state pile = [0; 0];
state stock = [0; 0];
state drawn = false;              // whether I have drawn this turn
state playing = false;
state result = "";

fn name(c: int) -> string { return ranks[c % 8] + suits[c / 8]; }

fn meld(a: int, b: int, c: int) -> bool {
  if a % 8 == b % 8 && b % 8 == c % 8 { return true; }
  if a / 8 != b / 8 || b / 8 != c / 8 { return false; }
  let lo = min(a, min(b, c));
  let hi = max(a, max(b, c));
  return hi - lo == 2 && a != b && b != c && a != c;
}

fn fits(a: int, b: int) -> bool { return a % 8 == b % 8 || a / 8 == b / 8 && abs(a - b) == 1; }

// Whether six cards make two melds: the first card's meld, then the other three.
fn won(h: int) -> bool {
  let cards = [0; 6];
  for i in 0..6 {
    if h == 0 { cards[i] = me[i]; } else { cards[i] = cpu[i]; }
  }
  for j in 1..6 {
    for k in j + 1..6 {
      let rest = [0; 0];
      for i in 1..6 {
        if i != j && i != k { push(rest, cards[i]); }
      }
      if meld(cards[0], cards[j], cards[k]) && meld(rest[0], rest[1], rest[2]) { return true; }
    }
  }
  return false;
}

fn inmeld(i: int) -> bool {
  for j in 0..len(cpu) {
    for k in 0..len(cpu) {
      if i != j && j != k && i != k && meld(cpu[i], cpu[j], cpu[k]) { return true; }
    }
  }
  return false;
}

fn lone(i: int) -> bool {
  for j in 0..len(cpu) {
    if j != i && fits(cpu[i], cpu[j]) { return false; }
  }
  return true;
}

fn start() {
  clear(me);
  clear(cpu);
  clear(pile);
  clear(stock);
  for i in 0..6 {
    push(me, deck[i]);
    push(cpu, deck[i + 6]);
  }
  push(pile, deck[12]);
  for i in 13..32 { push(stock, deck[i]); }
  drawn = false;
  result = "";
  playing = true;
}

fn stop(s: string) {
  result = s;
  playing = false;
}

// The computer takes the discard if it fits one of its cards, else the stock's top card; then it
// throws away its first card in no meld that fits none of the others, else its first in no meld.
fn computer() {
  let take = false;
  for i in 0..len(cpu) {
    if fits(pile[len(pile) - 1], cpu[i]) { take = true; }
  }
  if take {
    push(cpu, pile[len(pile) - 1]);
    remove(pile, len(pile) - 1);
  } else if len(stock) == 0 {
    stop("Draw");
    return;
  } else {
    push(cpu, stock[0]);
    remove(stock, 0);
  }
  let out = -1;
  for i in 0..7 {
    if out < 0 && !inmeld(i) && lone(i) { out = i; }
  }
  for i in 0..7 {
    if out < 0 && !inmeld(i) { out = i; }
  }
  out = max(out, 0);
  push(pile, cpu[out]);
  remove(cpu, out);
  if won(1) {
    stop("You lose");
  } else if len(stock) == 0 {
    stop("Draw");
  }
}

fn tap(c: int, r: int) {
  if !playing { return; }
  if r == 1 && c == 0 && !drawn && len(stock) > 0 {
    push(me, stock[0]);
    remove(stock, 0);
    drawn = true;
  } else if r == 1 && c == 1 && !drawn && len(pile) > 0 {
    push(me, pile[len(pile) - 1]);
    remove(pile, len(pile) - 1);
    drawn = true;
  } else if r == 2 && drawn && c < len(me) {
    push(pile, me[c]);
    remove(me, c);
    drawn = false;
    if won(0) { stop("You win"); } else { computer(); }
  }
}

fn card(c: int, x: int, y: int) {
  let ink = 9;
  if c / 8 == 1 || c / 8 == 2 { ink = 1; }
  rect(x * 20 + 1, y * 20 + 1, 18, 18, 7);
  text(name(c), x * 20 + 10, y * 20 + 10, 8, ink);
}

// The computer's cards face down on top, the stock and the discard's top card, then my hand.
fn scene() {
  for i in 0..len(cpu) { rect(i * 20 + 1, 1, 18, 18, 4); }
  if len(stock) > 0 { rect(1, 21, 18, 18, 4); }
  if len(pile) > 0 { card(pile[len(pile) - 1], 1, 1); }
  for i in 0..len(me) { card(me[i], i, 2); }
  if result != "" { text(result, 100, 30, 10, 11); }
}

label "Rummy";
label "Stock: " + len(stock);
