// Heist: sneak past the guards (the arrows, or a tap beside you), take the keycard, open the
// vault, grab the gold and reach the exit. A guard that lands on you catches you.
// icon: loop 4 6 20 6 20 20 4 20 ring 12 13 4 line 12 9 12 17 line 8 13 16 13
state first = [8, 8, 8, 8, 8, 8, 8, 8, 8,  8, 0, 0, 0, 8, 0, 0, 3, 8,  8, 0, 8, 0, 8, 0, 8, 0, 8,
               8, 0, 0, 0, 0, 0, 0, 0, 8,  8, 0, 8, 8, 5, 8, 8, 0, 8,  8, 6, 8, 3, 3, 3, 8, 2, 8,
               8, 8, 8, 8, 8, 8, 8, 8, 8];
state map = [8, 8, 8, 8, 8, 8, 8, 8, 8,  8, 0, 0, 0, 8, 0, 0, 3, 8,  8, 0, 8, 0, 8, 0, 8, 0, 8,
             8, 0, 0, 0, 0, 0, 0, 0, 8,  8, 0, 8, 8, 5, 8, 8, 0, 8,  8, 6, 8, 3, 3, 3, 8, 2, 8,
             8, 8, 8, 8, 8, 8, 8, 8, 8];
// 9 x 7 squares, row by row, by color: 8 wall, 0 floor, 3 gold, 6 keycard, 5 vault door, 2 exit
state px = 1;
state py = 1;
state gx = [7, 5];           // the guards: where, which way, and their stretch of row
state gy = [3, 1];
state gd = [-1, 1];
state lo = [1, 5];
state hi = [7, 7];
state loot = 0;
state moves = 0;
state card = false;
state over = "";             // Escaped or Caught, once it ends

fn on() -> bool {
  for i in 0..2 {
    if gx[i] == px && gy[i] == py { return true; }
  }
  return false;
}

fn patrol() {
  for i in 0..2 {
    if gx[i] + gd[i] < lo[i] || gx[i] + gd[i] > hi[i] { gd[i] = -gd[i]; }
    gx[i] += gd[i];
  }
}

fn reset() {
  for i in 0..63 { map[i] = first[i]; }
  px = 1;
  py = 1;
  gx[0] = 7;
  gx[1] = 5;
  gd[0] = -1;
  gd[1] = 1;
  loot = 0;
  moves = 0;
  card = false;
  over = "";
}

// A move made: take what is here; the exit ends it; else the guards step; one on you catches you.
fn moved() {
  moves += 1;
  let i = py * 9 + px;
  if map[i] == 3 {
    loot += 100;
    map[i] = 0;
  }
  if map[i] == 6 {
    card = true;
    map[i] = 0;
  }
  if map[i] == 2 {
    over = "Escaped";
    return;
  }
  if !on() { patrol(); }
  if on() { over = "Caught"; }
}

fn step(dx: int, dy: int) {
  if over != "" { return; }
  let i = (py + dy) * 9 + px + dx;
  if map[i] == 8 || map[i] == 5 && !card { return; }
  if map[i] == 5 { map[i] = 0; }
  px += dx;
  py += dy;
  moved();
}

fn wait() {
  if over == "" { moved(); }
}

fn toward(c: int, r: int) {
  if abs(c - px) + abs(r - py) == 1 { step(c - px, r - py); }
}

// The plan, 9 x 7 squares of 16 units: the guards in red over it, you in blue.
fn scene() {
  let cells = [0; 63];
  for i in 0..63 { cells[i] = map[i]; }
  for i in 0..2 { cells[gy[i] * 9 + gx[i]] = 1; }
  cells[py * 9 + px] = 4;
  pixels(cells, 0, 0, 9, 16);
  if over != "" { text(over, 72, 56, 16, 11); }
}

on key "left" { step(-1, 0); }
on key "right" { step(1, 0); }
