state step = 0;         // 50 ms steps into the current second
state timer = 0;        // ms a step while it spins; 0 at rest

// Lobe k of three, a third of a turn apart round the middle.
fn lobe(k: int) {
  let a = angle + k * 120;
  circle(50 + sin(a) * 30 / 1000, 50 - cos(a) * 30 / 1000, 16, 4);
}

fn scene() {
  for k in 0..3 { lobe(k); }
}

// Each step it turns by its speed; each 20 steps, a second, it slows by 1.
every timer {
  angle = (angle + speed * 3) % 360;
  step += 1;
  if step == 20 {
    step = 0;
    speed -= 1;
    if speed == 0 { timer = 0; }
  }
}

