// Contraction log: press Start when a contraction begins and Stop when it ends; each is logged with
// its length and how far apart. Go to the hospital shows by the 5-1-1 rule's three last ones.
// icon: ring 12 12 9 line 12 12 12 7 line 12 12 16 12
state clock = 0;          // seconds since the first Start
state speed = 0;          // ms a step; 0 until the first Start
state on = false;         // a contraction lasts
state began = 0;          // when it started
state starts = [0; 0];    // the logged ones: when each started and how long it lasted
state lasted = [0; 0];

every speed { clock += 1; }

fn mmss(s: int) -> string {
  if s % 60 < 10 { return (s / 60) + ":0" + s % 60; }
  return (s / 60) + ":" + s % 60;
}

fn entry(i: int) -> string {
  let s = (i + 1) + ". " + mmss(lasted[i]) + " long";
  if i > 0 { s = s + ", " + mmss(starts[i] - starts[i - 1]) + " apart"; }
  return s;
}

// The last three each a minute or longer, and their starts five minutes apart or less.
fn go() -> bool {
  let n = len(lasted);
  if n < 3 { return false; }
  for i in n - 3..n {
    if lasted[i] < 60 { return false; }
  }
  for i in n - 2..n {
    if starts[i] - starts[i - 1] > 300 { return false; }
  }
  return true;
}

label "Contraction log";
if on {
  label "Now: " + mmss(clock - began);
  button "Stop" {
    on = false;
    push(starts, began);
    push(lasted, clock - began);
  }
} else {
  button "Start" {
    began = clock;
    on = true;
    speed = 1000;
  }
}
label "Contractions: " + len(lasted);
if go() { label "Go to the hospital"; }
for i in 0..len(lasted) { label entry(i); }
button "Clear" {
  clear(starts);
  clear(lasted);
}

