fn cm(s: string) -> int { return min(max(parse(s, 0), 0), 100000); }

fn across(n: int, t: int) -> int { return (n + sides[t] - 1) / sides[t]; }

fn tiles(t: int) -> int { return across(cm(length), t) * across(cm(width), t); }

fn boxes(t: int) -> int { return (tiles(t) + per[t] - 1) / per[t]; }

fn cost(t: int) -> int { return boxes(t) * prices[t]; }

fn cheapest() -> int {
  let b = 0;
  for t in 1..3 {
    if cost(t) < cost(b) { b = t; }
  }
  return b;
}

