fn grams(s: string) -> int { return min(max(parse(s, 0), 0), 100000); }

fn calories() -> int { return 4 * grams(protein) + 4 * grams(carbs) + 9 * grams(fat); }

// A share of the calories as a whole percent, rounded down; 0 with none.
