fn sum(m: int) -> int {
  let n = 0;
  for i in 0..len(eaten) {
    let f = eaten[i];
    if m == 0 { n += protein[f]; }
    if m == 1 { n += carbs[f]; }
    if m == 2 { n += fat[f]; }
  }
  return n;
}

// A macro's eaten and goal, marked over past the goal.
fn tally(name: string, m: int, goal: int) -> string {
  let s = name + ": " + sum(m) + " / " + goal + " g";
  if sum(m) > goal { s = s + " over"; }
  return s;
}

