// The board anew: the trunk gray, the branches green, the lumberjack blue.
fn paint() {
  for r in 0..8 {
    let t = tree[7 - r];
    cells[r * 3] = 0;
    cells[r * 3 + 1] = 8;
    cells[r * 3 + 2] = 0;
    if t > 0 { cells[r * 3 + (t - 1) * 2] = 2; }
  }
  cells[21 + (side - 1) * 2] = 4;
}

fn start() {
  for i in 0..8 { tree[i] = pat[i]; }
  next = 8;
  side = 1;
  score = 0;
  time = 20;
  said = "";
  speed = 1000;
  paint();
}

fn over(why: string) {
  said = why;
  speed = 0;
}

// A chop from side s, unless a branch is in the way.
fn chop(s: int) {
  if speed == 0 { return; }
  side = s;
  if tree[0] == s {
    over("Game over");
  } else {
    remove(tree, 0);
    push(tree, pat[next % 10]);
    next += 1;
    score += 1;
    if tree[0] == s { over("Game over"); }
  }
  paint();
}

every speed {
  time -= 1;
  if time == 0 { over("Time's up"); }
}

on key "left" { chop(1); }
on key "right" { chop(2); }

