    best = max(best, kicks);
    return;
  }
  if up { by -= 1; } else { by += 1; }
  if by == 0 { up = false; }
  if bx + dx < 0 || bx + dx > 6 { dx = -dx; }
  bx += dx;
}

// A tap on square (c, r): a kick if it is by the ball while it falls low.
fn kick(c: int, r: int) {
  if speed == 0 || up || by < 5 || abs(c - bx) > 1 || abs(r - by) > 1 { return; }
  up = true;
  kicks += 1;
  dx = 0;
  if c < bx { dx = 1; }
  if c > bx { dx = -1; }
}

// The board, 7 x 10 squares of 12 units: the ball red.
fn scene() {
  let b = [-1; 70];
  b[by * 7 + bx] = 1;
  pixels(b, 0, 0, 7, 12);
  if over { text("Game over", 42, 40, 10, 11); }
}

