// Queens: put one queen in each row, column and color, no two touching, not even corner to
// corner. Tap a square to put a queen on it or take it off.
// icon: fill 4 18 20 18 20 21 4 21 fill 5 16 4 7 9 11 12 4 15 11 20 7 19 16
state regions = [1, 1, 1, 1, 1, 2, 1, 1, 1, 1, 2, 2, 3, 1, 1, 1, 2, 4, 3, 3, 6, 6, 5, 4, 3, 3, 6, 5, 5, 4, 6, 6, 6, 6, 6, 4];
state cells = [1, 1, 1, 1, 1, 2, 1, 1, 1, 1, 2, 2, 3, 1, 1, 1, 2, 4, 3, 3, 6, 6, 5, 4, 3, 3, 6, 5, 5, 4, 6, 6, 6, 6, 6, 4];
state queens = [false; 36];

// Whether queens on squares a and b break a rule together.
fn clash(a: int, b: int) -> bool {
  let dr = abs(a / 6 - b / 6);
  let dc = abs(a % 6 - b % 6);
  return dr == 0 || dc == 0 || regions[a] == regions[b] || (dr <= 1 && dc <= 1);
}

fn placed() -> int {
  let n = 0;
  for i in 0..36 {
    if queens[i] { n += 1; }
  }
  return n;
}

fn clashes() -> int {
  let n = 0;
  for a in 0..36 {
    for b in a + 1..36 {
      if queens[a] && queens[b] && clash(a, b) { n += 1; }
    }
  }
  return n;
}

// Square i as it shows: a queen gray, else its region's color.
fn show(i: int) {
  cells[i] = regions[i];
  if queens[i] { cells[i] = 8; }
}

label "Queens";
grid 6, cells {
  queens[cell] = !queens[cell];
  show(cell);
}
