// Spirograph helper: type the ring's and the wheel's teeth; it draws the pattern and says how
// many points it has and how many times the wheel goes round before it closes.
// icon: ring 12 12 10 ring 15 12 5 dot 17 12 2
state ring = "";
state wheel = "";

fn gcd(a: int, b: int) -> int {
  let p = a;
  let q = b;
  for i in 0..64 {
    if q == 0 { return p; }
    let t = p % q;
    p = q;
    q = t;
  }
  return p;
}

fn big() -> int { return parse(ring, 0); }
fn small() -> int { return parse(wheel, 0); }
fn fits() -> bool { return small() > 0 && big() > small() && big() <= 1000; }

// The ring, and inside it the pen's path, half way out on the wheel, 5 degrees a step until
// the pattern closes (at most 40 times round).
fn scene() {
  ring(80, 80, 78, 1, 8);
  let rt = big();
  let wt = small();
  let k = rt - wt;
  let laps = min(40, wt / gcd(rt, wt));
  let lx = 0;
  let ly = 0;
  for s in 0..laps * 72 + 1 {
    let t = s * 5;
    let px = 80 + (k * cos(t) + wt / 2 * cos(k * t / wt)) * 70 / rt / 1000;
    let py = 80 - (k * sin(t) - wt / 2 * sin(k * t / wt)) * 70 / rt / 1000;
    if s > 0 { line(lx, ly, px, py, 1, 4); }
    lx = px;
    ly = py;
  }
}

label "Spirograph helper";
row { label "Ring teeth"; input ring; label "Wheel teeth"; input wheel; }
if fits() {
  canvas 160, 160, scene();
  label "Points: " + big() / gcd(big(), small()) + "   Wheel goes round: " + small() / gcd(big(), small());
}

