// Pie poll: tap a color to vote for it; the pie shows each color's share, clockwise from the
// top in the order red, green, blue, yellow. Reset clears the votes.
// icon: ring 12 12 9 fill 12 12 12 3 21 12
state votes = [0, 0, 0, 0];   // red, green, blue, yellow
state tints = [1, 2, 4, 3];
state names = ["Red", "Green", "Blue", "Yellow"];

fn total() -> int { return votes[0] + votes[1] + votes[2] + votes[3]; }

fn share(i: int) -> int {
  if total() == 0 { return 0; }
  return votes[i] * 100 / total();
}

// The color at degree d clockwise from 12 o'clock: the slice whose share reaches past d's middle.
fn tint(d: int, all: int) -> int {
  let upto = 0;
  for i in 0..4 {
    upto += votes[i];
    if (2 * d + 1) * all < 720 * upto { return tints[i]; }
  }
  return 8;
}

