// War: press Deal, then Flip; the higher card wins both, and a tie is a war for six cards.
// One time through the deck: whoever wins more cards wins.
// icon: loop 3 6 12 4 15 18 6 20 loop 10 7 18 5 21 18 13 20
state mine = [7, 3, 9, 5, 5, 2, 8, 6, 4, 10];     // your pile, top first
state theirs = [4, 8, 9, 6, 1, 3, 7, 5, 2, 9];   // the computer's
state at = 0;             // the cards used from each pile
state you = 0;            // cards won
state comp = 0;
state up = [0, 0];        // the cards turned up last: yours, the computer's
state war = false;
state playing = false;

fn flip() {
  let a = mine[at];
  let b = theirs[at];
  at += 1;
  let pot = 2;
  war = false;
  repeat 4 {
    if a == b && at + 2 <= 10 {
      war = true;
      at += 2;
      a = mine[at - 1];
      b = theirs[at - 1];
      pot += 4;
    }
  }
  if a > b { you += pot; } else { comp += pot; }
  up[0] = a;
  up[1] = b;
  if at >= 10 { playing = false; }
}

fn card(x: int, n: int) {
  rect(x, 10, 40, 56, 7);
  if n > 0 { text(n, x + 20, 38, 20, 9); }
}

fn scene() {
  card(20, up[0]);
  card(100, up[1]);
  text("You", 40, 76, 8, 10);
  text("Computer", 120, 76, 8, 10);
}

