  found = false;
  over = false;
}

// Treasure hunt: one player taps a square to hide the treasure; the other taps squares to dig,
// and each dig tells how many squares away it is (across plus up or down).
// icon: line 5 5 19 19 line 19 5 5 19 ring 12 12 9
state spot = -1;          // the treasure's square; -1 until it is hidden
state look = [2; 36];     // 2 grass, 8 dug, 3 the treasure found
state said = "Tap a square to hide the treasure";
state found = false;

fn tap(i: int) {
  if found { return; }
  if spot < 0 {
    spot = i;
    said = "Hidden! Now dig";
    return;
  }
  let d = abs(i % 6 - spot % 6) + abs(i / 6 - spot / 6);
  if d == 0 {
    found = true;
    look[i] = 3;
    said = "You found it!";
  } else {
    look[i] = 8;
    said = d + " squares away";
