// Missionaries and cannibals: get all six across in a boat for two. Put people in the boat
// and Cross; never leave a bank with more cannibals than missionaries.
// icon: fill 3 13 21 13 18 18 6 18 line 12 13 12 4 fill 12 4 19 10 12 10 line 2 21 22 21
state m = [3, 0];         // missionaries on the left and right banks
state c = [3, 0];         // cannibals
