// Pancakes: tap a pancake to flip it and all those above it. Sort the stack, smallest on top,
// in as few flips as you can.
// icon: fill 9 5 15 5 15 8 9 8 fill 6 10 18 10 18 13 6 13 fill 3 15 21 15 21 18 3 18 line 12 20 22 20
state stack = [3, 6, 1, 4, 2, 5];     // the sizes, top first
state flips = 0;

fn sorted() -> bool {
  for i in 0..6 {
    if stack[i] != i + 1 { return false; }
  }
  return true;
}

// Flips the pancakes from the top down to row r: their order reverses.
fn flip(r: int) {
  if r == 0 || sorted() { return; }
  for i in 0..(r + 1) / 2 {
    let t = stack[i];
    stack[i] = stack[r - i];
    stack[r - i] = t;
  }
  flips += 1;
}

// A pancake a row 16 units tall, centered, 24 units wide for each size.
fn scene() {
  for r in 0..6 { rect(80 - stack[r] * 12, r * 16 + 2, stack[r] * 24, 12, stack[r]); }
}

