// Tetravex: tap a tile in the tray, then an empty place on the board; it goes there only if its
// numbers match the tiles beside it. Tap a placed tile to send it back. Place all nine to win.
// icon: loop 3 3 21 3 21 21 3 21 line 3 3 21 21 line 21 3 3 21
state tops = [7, 7, 0, 3, 9, 6, 6, 1, 7];       // the tiles, as they start in the tray
state rights = [4, 0, 2, 1, 0, 4, 9, 7, 1];
state bottoms = [1, 5, 7, 3, 6, 7, 7, 1, 3];
state lefts = [1, 7, 6, 9, 9, 4, 2, 1, 7];
state on = [-1; 9];       // the tile on each board place; -1 none
state sel = -1;           // the selected tray tile; -1 none

// The board place tile t is on, or -1 while it is in the tray.
fn where(t: int) -> int {
  for b in 0..9 {
    if on[b] == t { return b; }
  }
  return -1;
}

fn placed() -> int {
  let n = 0;
  for b in 0..9 {
    if on[b] >= 0 { n += 1; }
  }
  return n;
}

// Whether tile t matches every tile beside board place b.
fn fits(t: int, b: int) -> bool {
  if b % 3 > 0 && on[b - 1] >= 0 && rights[on[b - 1]] != lefts[t] { return false; }
  if b % 3 < 2 && on[b + 1] >= 0 && lefts[on[b + 1]] != rights[t] { return false; }
  if b >= 3 && on[b - 3] >= 0 && bottoms[on[b - 3]] != tops[t] { return false; }
  if b < 6 && on[b + 3] >= 0 && tops[on[b + 3]] != bottoms[t] { return false; }
  return true;
}

fn tap(c: int, r: int) {
  if placed() == 9 { return; }
  let b = r * 3 + c;
  if c < 3 && on[b] >= 0 {
    on[b] = -1;
    sel = -1;
  } else if c < 3 && sel >= 0 && fits(sel, b) {
    on[b] = sel;
    sel = -1;
  } else if c >= 4 && where(r * 3 + c - 4) < 0 {
    sel = r * 3 + c - 4;
  }
}

fn tile(t: int, x: int, y: int, k: int) {
  rect(x, y, 29, 29, k);
  text(tops[t], x + 14, y + 5, 8, 9);
  text(rights[t], x + 24, y + 14, 8, 9);
  text(bottoms[t], x + 14, y + 24, 8, 9);
  text(lefts[t], x + 4, y + 14, 8, 9);
}

// Cells 30 units wide: the board on the left, the tray on the right.
fn scene() {
  for b in 0..9 {
    if on[b] >= 0 {
      tile(on[b], b % 3 * 30, b / 3 * 30, 3);
    } else {
      rect(b % 3 * 30, b / 3 * 30, 29, 29, 8);
    }
  }
  for t in 0..9 {
    let k = 3;
    if t == sel { k = 2; }
    if where(t) < 0 { tile(t, 120 + t % 3 * 30, t / 3 * 30, k); }
  }
}

fn status() -> string {
  if placed() == 9 { return "Solved"; }
  return "Pick a tile, then a place";
}

