state books = [0, 0];
state over = "";

fn total(p: int) -> int {
  let n = 0;
  for r in 0..6 { n += have[p * 6 + r]; }
  return n;
}

fn deal() {
  for i in 0..12 { have[i] = 0; }
  clear(pond);
  for k in 0..5 {
    have[deck[k * 2]] += 1;
    have[6 + deck[k * 2 + 1]] += 1;
  }
  for k in 10..24 { push(pond, deck[k]); }
  books[0] = 0;
  books[1] = 0;
  over = "";
}

// Player p lays down any four of a kind; when all six books are down, the most books win.
fn book(p: int) {
  for r in 0..6 {
    if have[p * 6 + r] == 4 {
      have[p * 6 + r] = 0;
      books[p] += 1;
    }
  }
  if books[0] + books[1] == 6 && books[0] > books[1] { over = "You win!"; }
  if books[0] + books[1] == 6 && books[1] > books[0] { over = "Computer wins"; }
  if books[0] + books[1] == 6 && books[0] == books[1] { over = "Tie"; }
}

// Player p asks for rank r: whether they got some and ask again; else they draw.
fn ask(p: int, r: int) -> bool {
  let q = 6 - p * 6;
  let n = have[q + r];
  if n == 0 {
    if len(pond) > 0 {
      have[p * 6 + pond[0]] += 1;
      remove(pond, 0);
      book(p);
    }
    return false;
  }
  have[q + r] = 0;
  have[p * 6 + r] += n;
  book(p);
  return true;
}

// The computer asks for what it holds most of, the lowest on a tie, until it has to go fish.
fn computer() {
  let going = true;
  repeat 30 {
    if going && over == "" && total(1) > 0 {
      let best = 0;
      for r in 1..6 {
        if have[6 + r] > have[6 + best] { best = r; }
      }
      going = ask(1, best);
    }
  }
}

fn mine(r: int) {
  if over == "" && have[r] > 0 && !ask(0, r) { computer(); }
}

