// Square k along line n from side d: 0 above, 1 below, 2 left, 3 right.
fn at(d: int, n: int, k: int) -> int {
  if d == 0 { return h[k * 4 + n]; }
  if d == 1 { return h[(3 - k) * 4 + n]; }
  if d == 2 { return h[n * 4 + k]; }
  return h[n * 4 + 3 - k];
}

fn seen(d: int, n: int) -> int {
  let tall = 0;
  let count = 0;
  for k in 0..4 {
    if at(d, n, k) > tall {
      tall = at(d, n, k);
