// Shikaku: cut the board into rectangles, each holding one number, its size. Tap two squares to
// make the rectangle they are corners of; tap a rectangle to take it away.
// icon: loop 3 3 21 3 21 21 3 21 line 12 3 12 21 line 12 12 21 12 dot 7 12 2
state nums = ["", "", "", "", "", "",
              "", "", "3", "", "6", "",
              "", "", "", "", "2", "3",
              "", "8", "", "", "", "",
              "", "2", "", "6", "2", "",
              "", "2", "", "", "2", ""];
state owner = [-1; 36];   // the rectangle each square is in: its top left square, -1 none
state corner = -1;        // the square marked as a corner, -1 none
state tint = [0; 36];     // what each square shows: 0 blank, 1 red, 2 green, 3 the corner

// Rectangle o (its squares those whose owner is o): one number, equal to its size.
fn good(o: int) -> bool {
  let size = 0;
  let count = 0;
  let n = 0;
  for i in 0..36 {
    if owner[i] == o {
      size += 1;
      if nums[i] != "" {
        count += 1;
        n = parse(nums[i], 0);
      }
    }
  }
  return count == 1 && n == size;
}

fn solved() -> bool {
  for i in 0..36 {
    if owner[i] < 0 || !good(owner[i]) { return false; }
  }
  return true;
}

// The rectangle with corners a and b, taking away every rectangle it overlaps.
fn make(a: int, b: int) {
  let c0 = min(a % 6, b % 6);
  let c1 = max(a % 6, b % 6);
  let r0 = min(a / 6, b / 6);
  let r1 = max(a / 6, b / 6);
  let gone = [false; 36];
  for i in 0..36 {
    let inside = i % 6 >= c0 && i % 6 <= c1 && i / 6 >= r0 && i / 6 <= r1;
    if inside && owner[i] >= 0 { gone[owner[i]] = true; }
  }
  for i in 0..36 {
    let inside = i % 6 >= c0 && i % 6 <= c1 && i / 6 >= r0 && i / 6 <= r1;
    if owner[i] >= 0 && gone[owner[i]] { owner[i] = -1; }
    if inside { owner[i] = r0 * 6 + c0; }
  }
}

fn tap(i: int) {
  if solved() { return; }
  if corner >= 0 {
    make(corner, i);
    corner = -1;
  } else if owner[i] >= 0 {
    let o = owner[i];
    for k in 0..36 {
      if owner[k] == o { owner[k] = -1; }
    }
  } else {
    corner = i;
  }
}

// The colors anew after a change.
fn paint() {
  for i in 0..36 {
    tint[i] = 0;
    if owner[i] >= 0 && good(owner[i]) { tint[i] = 2; } else if owner[i] >= 0 { tint[i] = 1; }
  }
  if corner >= 0 { tint[corner] = 3; }
}

