    bx += dx;
    by += dy;
  }
  moves += 1;
  let ex = bx;
  let ey = by;
  if way == 1 { ex += 1; }
  if way == 2 { ey += 1; }
  if !floor(bx, by) || !floor(ex, ey) {
    falls += 1;
    home();
  }
}

