// A quarter turn toward dx, dy: tip over, stand up or roll sideways.
fn turn(dx: int, dy: int) {
  if done { return; }
  if way == 0 {
    if dx > 0 || dy > 0 { bx += dx; by += dy; } else { bx += dx * 2; by += dy * 2; }
    if dx != 0 { way = 1; } else { way = 2; }
  } else if (way == 1 && dx != 0) || (way == 2 && dy != 0) {
    if dx > 0 || dy > 0 { bx += dx * 2; by += dy * 2; } else { bx += dx; by += dy; }
    way = 0;
  } else {
    bx += dx;
    by += dy;
  }
  let ex = bx;
  let ey = by;
  if way == 1 { ex += 1; }
  if way == 2 { ey += 1; }
  if square(bx, by) == 0 || square(ex, ey) == 0 {
    start();
  } else if way == 0 && square(bx, by) == 2 {
    if lv == 0 {
