// Tapper: up and down move the bartender between the four bars, space (or Serve) slides a mug
// down his bar. Serve every customer before he reaches the end. Two levels, three lives.
// icon: loop 5 6 15 6 15 20 5 20 line 15 9 19 9 19 16 15 16 line 7 10 7 16 line 11 10 11 16
state cr = [0; 0];              // the customers: bar (row) and column
state cc = [0; 0];
state mr = [0; 0];              // the mugs sliding: bar and column
state mc = [0; 0];
state bars = [0, 2, 1, 3, 1];   // the bar each customer of a level comes in at, in turn
state me = 0;                   // the bartender's bar
state level = 1;
state steps = 0;                // steps since the level began
state come = 0;                 // customers come in this level
state score = 0;
state lives = 3;
state speed = 0;                // ms a step; 0 while no game runs
state said = "";

fn begin(l: int) {
  level = l;
  steps = 0;
  come = 0;
  clear(cr);
  clear(cc);
  clear(mr);
  clear(mc);
}

fn lose() {
  lives -= 1;
  if lives == 0 {
    said = "Game over";
    speed = 0;
  }
}

// The customer on bar r, column c, or -1.
fn customer(r: int, c: int) -> int {
  for i in 0..len(cr) {
    if cr[i] == r && cc[i] == c { return i; }
  }
  return -1;
}

// Mug j meets a customer on its square: both are gone. Whether it did.
fn meet(j: int) -> bool {
  let i = customer(mr[j], mc[j]);
  if i < 0 { return false; }
  remove(cr, i);
  remove(cc, i);
  remove(mr, j);
  remove(mc, j);
  score += 50;
  return true;
}

fn serve() {
  if speed > 0 {
    push(mr, me);
    push(mc, 6);
    meet(len(mc) - 1);
  }
}

fn slide() {
  let j = 0;
  for n in 0..len(mc) {
    if j < len(mc) {
      mc[j] -= 1;
      if mc[j] < 0 {
        remove(mr, j);
        remove(mc, j);
        lose();
      } else if !meet(j) {
        j += 1;
      }
    }
  }
}

fn walk() {
  let i = 0;
  for n in 0..len(cc) {
    if i < len(cc) {
      cc[i] += 1;
      let k = -1;
      for j in 0..len(mc) {
        if mr[j] == cr[i] && mc[j] == cc[i] { k = j; }
      }
      if cc[i] == 7 {
        remove(cr, i);
        remove(cc, i);
        lose();
      } else if k >= 0 {
        meet(k);
      } else {
        i += 1;
      }
    }
  }
}

fn step() {
  steps += 1;
  slide();
  if speed > 0 && steps % (4 - level) == 0 { walk(); }
  if speed > 0 && steps % 6 == 0 && come < 5 {
    push(cr, bars[come]);
    push(cc, 0);
    come += 1;
  }
  if speed > 0 && come == 5 && len(cr) == 0 {
    if level == 2 {
      said = "You win";
      speed = 0;
    } else {
      begin(2);
    }
  }
}

every speed { step(); }

fn move(d: int) {
  if speed > 0 { me = min(3, max(0, me + d)); }
}

on key "up" { move(-1); }
on key "down" { move(1); }
on key "space" { serve(); }

fn scene() {
  let cells = [-1; 32];
  for i in 0..len(cr) { cells[cr[i] * 8 + cc[i]] = 1; }
  for j in 0..len(mr) { cells[mr[j] * 8 + mc[j]] = 3; }
  cells[me * 8 + 7] = 4;
  pixels(cells, 0, 0, 8, 20);
  if said != "" { text(said, 80, 40, 16, 11); }
}

label "Tapper";
label "Level: " + level + "   Score: " + score + "   Lives: " + lives;
canvas 160, 80, scene() { if speed > 0 { me = y / 20; } }
row {
  if speed == 0 {
    button "Start" {
      score = 0;
      lives = 3;
      said = "";
      me = 0;
      begin(1);
      speed = 200;
    }
  }
  button "Serve" { serve(); }
}

// Tapper: up and down move you between the three bars, space slides a beer down yours. Serve
// each customer before he reaches you; after six served they hurry. Three lives.
// icon: loop 5 6 15 6 15 20 5 20 line 15 9 19 9 19 16 15 16 line 7 10 7 16 line 11 10 11 16
state cb = [0; 0];              // the customers: bar, and how far along (0 the door, 60 you)
state cx = [0; 0];
state bb = [0; 0];              // the beers sliding: bar, and how far along
state bx = [0; 0];
state me = 0;                   // your bar, 0 the top
state ticks = 0;
state come = 0;
state served = 0;
state lives = 3;
state speed = 0;                // ms a tick; 0 while no game runs

fn arrive() {
  push(cb, come % 3);
  push(cx, 0);
  come += 1;
}

fn lose() {
  lives -= 1;
  if lives == 0 { speed = 0; }
}

// The customer on bar b a beer at x has reached (at or past him), nearest you first; -1 if none.
fn catcher(b: int, x: int) -> int {
  let k = -1;
  for i in 0..len(cb) {
    if cb[i] == b && cx[i] >= x && (k < 0 || cx[i] > cx[k]) { k = i; }
  }
  return k;
}

fn pace() -> int {
  if served >= 6 { return 2; }
  return 1;
}

fn tick() {
  ticks += 1;
  for j in 0..len(bx) { bx[j] -= 6; }
  for i in 0..len(cx) { cx[i] += pace(); }
  let j = 0;
  for n in 0..len(bx) {
    if j < len(bx) {
      let k = catcher(bb[j], bx[j]);
      if k >= 0 {
        remove(cb, k);
        remove(cx, k);
        served += 1;
      }
      if k >= 0 || bx[j] <= 0 {
        if k < 0 { lose(); }
        remove(bb, j);
        remove(bx, j);
      } else {
        j += 1;
      }
    }
  }
  let i = 0;
  for n in 0..len(cx) {
    if i < len(cx) && cx[i] >= 60 {
      remove(cb, i);
      remove(cx, i);
      lose();
    } else {
      i += 1;
    }
  }
  if speed > 0 && ticks % 30 == 0 { arrive(); }
}

