// Liar's dice against the computer: type a bid as count and face (35 is three fives) and press
// Bid, or call Liar on the computer's bid. Losing a call costs a die; the last with dice wins.
// icon: loop 3 8 13 8 13 18 3 18 dot 6 11 1 dot 10 15 1 loop 11 4 21 4 21 14 11 14 dot 16 9 1
state seq = [2, 5, 5, 3, 6, 1, 5, 4, 5, 2, 4, 6, 3, 3, 1, 2, 2, 6, 4, 4, 5, 1, 6, 3, 2];
state pos = 0;                  // the next number of seq to roll
state mine = [0; 0];
state its = [0; 0];
state nme = 4;                  // dice left
state nit = 4;
state q = 0;                    // the bid: at least q dice show face f; q 0 before the first
state f = 0;
state entry = "";
state said = "";
state on = false;

fn roll() {
  clear(mine);
  clear(its);
  for i in 0..nme {
    push(mine, seq[pos]);
    pos = (pos + 1) % len(seq);
  }
  for i in 0..nit {
    push(its, seq[pos]);
    pos = (pos + 1) % len(seq);
  }
  q = 0;
  f = 0;
}

fn own(face: int) -> int {
  let n = 0;
  for i in 0..len(its) {
    if its[i] == face { n += 1; }
  }
  return n;
}

fn all(face: int) -> int {
  let n = own(face);
  for i in 0..len(mine) {
    if mine[i] == face { n += 1; }
  }
  return n;
}

// The face the computer has most of, the higher on a tie.
fn best() -> int {
  let b = 1;
  for face in 2..7 {
    if own(face) >= own(b) { b = face; }
  }
  return b;
}

// The bid is called, by me or not: the caller loses a die if it stands, else the bidder; the
// loser bids first in the next round, the computer at once.
fn called(byMe: bool) {
  let stands = all(f) >= q;
  let iLose = stands == byMe;
  if iLose { nme -= 1; } else { nit -= 1; }
  if nme == 0 {
    said = "You lose";
    on = false;
  } else if nit == 0 {
    said = "You win";
    on = false;
  } else {
    roll();
    if !iLose {
      f = best();
      q = own(f);
    }
  }
}

fn bid() {
  let v = parse(entry, 0);
  let nq = v / 10;
  let nf = v % 10;
  if !on || nq < 1 || nf < 1 || nf > 6 || nq < q || (nq == q && nf <= f) { return; }
  q = nq;
  f = nf;
  entry = "";
  if q > own(f) + 2 {
    called(false);
  } else {
    let b = best();
    if b <= f { q += 1; }
    f = b;
  }
}

fn bidText() -> string {
  if q == 0 { return "Bid: none"; }
  return "Bid: " + q + " x " + f;
}

fn dice() -> string {
  let s = "Your dice:";
  for i in 0..len(mine) { s = s + " " + mine[i]; }
  return s;
}

