// balloon hit splits in two small ones; a small one pops. Clear two levels; a touch ends it.
// icon: ring 9 9 6 dot 18 6 3 line 15 22 15 13 fill 12 22 18 22 15 18
state bx = [0; 0];              // the balloons: square, way across and up or down, size (2 big)
state by = [0; 0];
state bdx = [0; 0];
state bdy = [0; 0];
state size = [0; 0];
