fn add(x: int, y: int, dx: int, dy: int, s: int) {
  push(bx, x);
  push(by, y);
  push(bdx, dx);
  push(bdy, dy);
  push(size, s);
}

fn drop(i: int) {
  remove(bx, i);
  remove(by, i);
  remove(bdx, i);
  remove(bdy, i);
  remove(size, i);
}

fn begin(l: int) {
  level = l;
  steps = 0;
  hx = -1;
  px = 5;
  clear(bx);
  clear(by);
  clear(bdx);
  clear(bdy);
  clear(size);
  add(2, 1, 1, 1, 2);
  if l == 2 { add(9, 1, -1, 1, 2); }
}

// The lowest balloon on the harpoon is hit: a big one splits, a small one pops.
fn hits() {
  if hx < 0 { return; }
  let k = -1;
  for i in 0..len(bx) {
    if bx[i] == hx && by[i] >= tip && by[i] <= 6 && (k < 0 || by[i] > by[k]) { k = i; }
  }
  if k < 0 { return; }
  hx = -1;
  if size[k] == 2 {
    score += 50;
    add(bx[k], by[k], -1, -1, 1);
    add(bx[k], by[k], 1, -1, 1);
  } else {
    score += 100;
  }
  drop(k);
}

fn touch() {
  for i in 0..len(bx) {
    if bx[i] == px && by[i] == 7 {
      said = "Game over";
      speed = 0;
    }
  }
}

fn step() {
  steps += 1;
  for i in 0..len(bx) {
    if size[i] == 1 || steps % 2 == 0 {
      if bx[i] + bdx[i] < 0 || bx[i] + bdx[i] > 11 { bdx[i] = -bdx[i]; }
      if by[i] + bdy[i] < 0 || by[i] + bdy[i] > 7 { bdy[i] = -bdy[i]; }
      bx[i] += bdx[i];
      by[i] += bdy[i];
    }
  }
  if hx >= 0 && tip == 0 {
    hx = -1;
  } else if hx >= 0 {
    tip -= 1;
  }
  hits();
  touch();
  if speed > 0 && len(bx) == 0 {
    if level == 2 {
      said = "You win";
      speed = 0;
    } else {
      begin(2);
    }
  }
}

every speed { step(); }

fn fire() {
  if speed > 0 && hx < 0 {
    hx = px;
    tip = 6;
    hits();
  }
}

fn move(d: int) {
  if speed > 0 {
    px = min(11, max(0, px + d));
    touch();
