// Magnet Ball: an arrow switches on the magnet on that side, which pulls the ball faster and
// faster until a wall stops it. Pits send it back to the start; roll it over the hole.
// icon: arc 12 10 7 270 90 line 5 10 5 17 line 19 10 19 17 dot 12 19 3
state box = [0, 8080800, 1000028, 801, 0];
                                // inside the walls, a row a number, a digit a square's color:
                                // 0 floor, 8 wall, 1 pit, 2 the hole
state bx = 3;                   // the ball, from its start
state by = 3;
state dx = 0;                   // the pull: the magnet that is on, as a way
state dy = 0;
state v = 0;                    // squares a step
state said = "";
state speed = 0;               // ms a step; 0 while the ball rests

fn at(c: int, r: int) -> int {
  if c < 0 || c > 6 || r < 0 || r > 4 { return 8; }
  let d = 1;
  for k in c..6 { d = d * 10; }
  return box[r] / d % 10;
}

fn pull(x0: int, y0: int) {
  if said == "" {
    dx = x0;
    dy = y0;
    v = 0;
    speed = 150;
  }
}

every speed {
  if said == "" && dx + dy != 0 {
    v = min(3, v + 1);
    for k in 0..v {
      if at(bx + dx, by + dy) == 8 {
        v = 0;
        speed = 0;
      } else if v > 0 {
        bx += dx;
        by += dy;
        if at(bx, by) == 1 {
          bx = 3;
          by = 3;
          dx = 0;
          dy = 0;
          v = 0;
          speed = 0;
        } else if at(bx, by) == 2 {
          said = "You win";
          v = 0;
          speed = 0;
        }
      }
    }
  }
}

