// Burger Time: the arrows walk the chef along the floors and up and down the ladders at the ends.
// Step on every part of a burger piece to drop it on the plate; keep away from the sausage.
// icon: fill 4 10 6 5 18 5 20 10 line 3 13 21 13 fill 4 16 20 16 19 20 5 20
state pressed = [false; 9];     // the pieces' squares, floor by floor, columns 3 to 5
state served = [false, false, false];
state tints = [3, 2, 3];
state cx = 0;                   // the chef
state cy = 4;
state n = 0;                    // the sausage's steps
state lives = 3;
state speed = 0;                // ms a step; 0 while no game runs
state result = "";

fn sausage() -> int {
  let k = n % 12;
  if k <= 6 { return 1 + k; }
  return 13 - k;
}

fn count() -> int {
  let s = 0;
  for f in 0..3 {
    if served[f] { s += 1; }
  }
  return s;
}

fn caught() {
  if speed > 0 && cy == 2 && cx == sausage() {
    lives -= 1;
    cx = 0;
    cy = 4;
    if lives == 0 {
      result = "Game over";
      speed = 0;
    }
  }
}

// The chef steps onto (cx, cy): a piece's square there is pressed; a piece pressed all over drops.
fn press() {
  let f = cy / 2;
  if cy % 2 == 0 && cx >= 3 && cx <= 5 && !served[f] {
    pressed[f * 3 + cx - 3] = true;
    if pressed[f * 3] && pressed[f * 3 + 1] && pressed[f * 3 + 2] { served[f] = true; }
    if count() == 3 {
      result = "You win";
      speed = 0;
    }
  }
}

fn walk(dx: int, dy: int) {
  if speed == 0 { return; }
  if dx != 0 && cy % 2 == 0 { cx = min(8, max(0, cx + dx)); }
  if dy != 0 && (cx == 0 || cx == 8) { cy = min(4, max(0, cy + dy)); }
  press();
  caught();
}

fn start() {
  for i in 0..9 { pressed[i] = false; }
  for f in 0..3 { served[f] = false; }
  cx = 0;
  cy = 4;
  n = 0;
  lives = 3;
  result = "";
  speed = 300;
}

every speed {
  n += 1;
  caught();
}

on key "left" { walk(-1, 0); }
on key "right" { walk(1, 0); }
on key "up" { walk(0, -1); }
on key "down" { walk(0, 1); }

