// The raiders at the end of years 3, 6 and 9.
fn raiders() -> int {
  if year == 3 { return 5; }
  if year == 6 { return 15; }
  if year == 9 { return 25; }
  return 0;
}

fn season() {
  if over { return; }
  food += 10 * count(2);
  if food >= people + soldiers {
    food -= people + soldiers;
  } else {
    food = 0;
    people = max(0, people - 2);
  }
  gold += people;
  people += 3 * count(3);
  soldiers += 2 * count(4);
  news = "";
  let r = raiders();
  if r > 0 && soldiers >= r {
    news = "Raid repelled";
  } else if r > 0 {
    gold -= gold / 2;
    news = "Raided";
  }
  if year == 10 { over = true; } else { year += 1; }
}

