// Oregon Trail: Go and Stop the wagon (20 miles a day); buy food at the Fort, ford or ferry the
// River, Rest or Hunt while stopped. Reach mile 300 before your party's health runs out.
// icon: loop 3 8 15 8 15 16 3 16 loop 15 10 19 10 21 13 21 16 15 16 ring 7 18 3 ring 17 18 3
state day = 1;
state miles = 0;
state food = 60;
state money = 40;
state health = 10;
state speed = 0;            // ms a day while the wagon rolls
state crossed = false;      // the River behind us
state over = false;

fn place() -> string {
  if miles == 100 && speed == 0 { return "Fort"; }
  if miles == 200 && !crossed { return "River"; }
  return "";
}

// A day passes: the party eats, or goes hungry; at Health 0 it dies.
fn pass() {
  day += 1;
  if food >= 5 {
    food -= 5;
  } else {
    food = 0;
    health -= 1;
  }
  if health <= 0 {
    health = 0;
    speed = 0;
    over = true;
  }
}

every speed {
  miles += 20;
  pass();
  if miles == 100 || miles == 200 { speed = 0; }
  if miles >= 300 {
    speed = 0;
    over = true;
  }
}

fn go() {
  if !over && (miles != 200 || crossed) { speed = 1000; }
}

fn stay(hunt: bool) {
  if over || speed > 0 { return; }
  pass();
  if hunt && !over { food += 15; }
}

fn begin() {
  day = 1;
  miles = 0;
  food = 60;
  money = 40;
  health = 10;
  speed = 0;
  crossed = false;
  over = false;
}

