// Oregon trail: Travel goes 20 miles a day, Hunt brings 30 food; every day eats 4. Reach mile
// 500 before the food runs out.
// icon: loop 3 8 15 8 15 16 3 16 loop 15 10 19 10 21 13 21 16 15 16 ring 7 18 3 ring 17 18 3
state miles = 0;
state food = 80;

fn playing() -> bool { return miles < 500 && food > 0; }

fn spend(go: int, got: int) {
  if !playing() { return; }
