// Werewolf hunt: the arrows (or a tap beside you) move you; take the silver bullet, and at night,
// when the werewolf comes beside you, Shoot. By night it takes two steps for each of yours.
// icon: fill 4 10 6 3 10 8 14 8 18 3 20 10 18 17 12 21 6 17
state hx = 0;               // the hunter
state hy = 0;
state wx = 8;               // the werewolf
state wy = 8;
state moves = 0;
state silver = 0;           // 0 lying on its square, 1 carried
state end = "";             // You win, or Game over

fn night() -> bool { return (moves / 6) % 2 == 1; }

fn sgn(n: int) -> int {
  if n > 0 { return 1; }
  if n < 0 { return -1; }
  return 0;
}

// One step toward the hunter: across first, else up or down; onto the hunter catches him.
fn stalk() {
  let nx = wx;
  let ny = wy;
  if wx != hx { nx = wx + sgn(hx - wx); } else { ny = wy + sgn(hy - wy); }
  if nx == hx && ny == hy {
    end = "Game over";
    return;
  }
  wx = nx;
  wy = ny;
}

fn step(dx: int, dy: int) {
  let c = hx + dx;
  let r = hy + dy;
  if end != "" || c < 0 || c > 8 || r < 0 || r > 8 || (c == wx && r == wy) { return; }
  hx = c;
  hy = r;
  moves += 1;
  if silver == 0 && c == 2 && r == 2 { silver = 1; }
  if night() {
    stalk();
    if end == "" { stalk(); }
  }
}

fn shoot() {
  if end == "" && silver == 1 && night() && abs(wx - hx) + abs(wy - hy) == 1 { end = "You win"; }
}

fn restart() {
  hx = 0;
  hy = 0;
  wx = 8;
  wy = 8;
  moves = 0;
  silver = 0;
  end = "";
}

fn status() -> string {
  let s = "Moves " + moves + "   ";
  if night() { s = s + "Night"; } else { s = s + "Day"; }
  if silver == 1 { s = s + "   Silver"; }
  return s;
}

// The village, 9 x 9 squares of 12 units.
fn scene() {
  let cells = [2; 81];
  if silver == 0 { cells[20] = 6; }
  if night() { cells[wy * 9 + wx] = 1; } else { cells[wy * 9 + wx] = 5; }
  cells[hy * 9 + hx] = 4;
  pixels(cells, 0, 0, 9, 12);
  if end != "" { text(end, 54, 54, 14, 11); }
}

on key "left" { step(-1, 0); }
on key "right" { step(1, 0); }
on key "up" { step(0, -1); }
on key "down" { step(0, 1); }
on key "space" { shoot(); }

label "Werewolf hunt";
label status();
canvas 108, 108, scene() {
  if abs(x / 12 - hx) + abs(y / 12 - hy) == 1 { step(x / 12 - hx, y / 12 - hy); }
}
row {
  button "Shoot" { shoot(); }
  button "New game" { restart(); }
}

// Werewolf: tap a name to vote that player out; then night falls and the werewolf eats the first
// player left on the list. Vote out the werewolf (Dan, for now) to win.
// icon: fill 4 10 6 3 10 8 14 8 18 3 20 10 18 17 12 21 6 17
state names = ["Ann", "Ben", "Cat", "Dan", "Eve", "Fin"];
state alive = [true, true, true, true, true, true];
state news = "Day 1: vote someone out";
state over = false;

fn left() -> int {
  let n = 0;
  for i in 0..6 {
    if alive[i] { n += 1; }
  }
  return n;
}

// The night: the first player left, not the werewolf, is eaten.
fn night() {
  for i in 0..6 {
    if alive[i] && i != 3 {
      alive[i] = false;
      news = names[i] + " was eaten in the night. Vote again";
      return;
    }
  }
}

fn vote(i: int) {
  if over || !alive[i] { return; }
  alive[i] = false;
  if i == 3 {
    news = "Dan was the werewolf: the village wins!";
    over = true;
    return;
  }
  night();
  if left() <= 2 {
    news = "Only two left: the werewolf wins!";
    over = true;
  }
}

fn restart() {
  for i in 0..6 { alive[i] = true; }
  news = "Day 1: vote someone out";
  over = false;
}

label "Werewolf";
label news;
row {
  for i in 0..6 {
    if alive[i] { button names[i] { vote(i); } }
  }
}
button "New game" { restart(); }

// Rocket missions: buy Engines ($30) and Tanks ($10) with $100, Undo the last, then Launch. Reach
// each mission's height: 50, then 90, then 120. Too many tanks and it is too heavy to lift.
// icon: fill 12 2 16 8 16 17 8 17 8 8 fill 8 13 4 20 8 18 fill 16 13 20 20 16 18 line 12 18 12 22
state parts = [0; 0];       // bottom to top: 1 an engine, 2 a tank
state money = 100;
state mission = 1;
state height = 0;
state speed = 0;
state fuel = 0;
state flying = 0;           // ms a step: 100 while it flies
state news = "";
state won = false;

fn count(k: int) -> int {
  let n = 0;
  for i in 0..len(parts) {
    if parts[i] == k { n += 1; }
  }
  return n;
}

fn target() -> int {
  if mission == 1 { return 50; }
  if mission == 2 { return 90; }
  return 120;
}

fn cost(k: int) -> int {
  if k == 1 { return 30; }
  return 10;
}

fn add(k: int) {
  if flying == 0 && !won && money >= cost(k) {
    push(parts, k);
    money -= cost(k);
  }
}

fn undo() {
  if flying == 0 && !won && len(parts) > 0 {
    money += cost(parts[len(parts) - 1]);
    remove(parts, len(parts) - 1);
  }
}

fn launch() {
  if flying > 0 || won { return; }
  if 4 * count(1) <= len(parts) + 1 {
    news = "Too heavy";
    return;
  }
  news = "";
  height = 0;
  speed = 0;
  fuel = 5 * count(2);
  flying = 100;
}

// The flight is over: a mission won or failed, and a new rocket.
fn land() {
  flying = 0;
  if height >= target() {
    if mission == 3 {
      news = "You win";
      won = true;
    } else {
      news = "Success";
      mission += 1;
    }
  } else {
    news = "Failed";
  }
  clear(parts);
  money = 100;
}

every flying {
  if fuel > 0 {
    fuel = max(0, fuel - count(1));
    speed += 4 * count(1) - len(parts) - 1;
  } else {
    speed -= 2;
  }
  if speed > 0 { height += speed; } else { land(); }
}

// The rocket, red engines under yellow tanks under its capsule, rising a unit for every 2 of height.
fn scene() {
  rect(0, 112, 80, 8, 2);
  let base = 112 - min(height / 2, 80);
  for i in 0..len(parts) {
    let c = 3;
    if parts[i] == 1 { c = 1; }
    rect(32, base - 6 - i * 6, 16, 6, c);
  }
  circle(40, base - 6 * len(parts) - 4, 6, 7);
  text(news, 40, 8, 8, 11);
}

label "Rocket missions";
label "Mission " + mission + "   Target " + target() + "   Money " + money;
label "Engines " + count(1) + "   Tanks " + count(2);
label "Height " + height + "   Speed " + speed + "   Fuel " + fuel;
canvas 80, 120, scene();
row {
  button "Engine" { add(1); }
  button "Tank" { add(2); }
  button "Undo" { undo(); }
  button "Launch" { launch(); }
}

