state site = [3; 36];       // yellow dirt, green half dug, blank cleared, purple a statue piece
state digs = 20;
state score = 0;

fn piece(i: int) -> bool { return i == 14 || i == 15 || i == 20 || i == 21; }

fn dig(i: int) {
  if digs == 0 || dirt[i] == 0 { return; }
  digs -= 1;
  dirt[i] -= 1;
  site[i] = 2;
  if dirt[i] == 0 {
    site[i] = 0;
    if piece(i) {
      site[i] = 5;
      score += 100;
    }
  }
}

