// Palindrome numbers: type a whole number and press Check to see if it reads the same backwards.
// icon: line 3 8 21 8 line 17 4 21 8 17 12 line 21 16 3 16 line 7 12 3 16 7 20
state typed = "";
state said = "";        // what the last Check found

// n's digits backwards: 1230 is 321.
fn backwards(n: int) -> int {
  let m = n;
  let r = 0;
  repeat 18 {
    if m > 0 {
      r = r * 10 + m % 10;
      m = m / 10;
    }
  }
  return r;
}

fn check() {
  let n = parse(typed, -1);
  if n < 0 || n > 999999999999999999 {
    said = "Type a whole number of up to 18 digits";
  } else if backwards(n) == n {
    said = n + " is a palindrome";
  } else {
    said = n + " is not a palindrome";
  }
}

