// Fewest coins: type an amount and press Count for the fewest coins of 1, 3 and 4 that make it.
// icon: ring 8 8 5 ring 16 8 5 ring 12 16 5
state typed = "";
state coins = -1;       // the fewest for the amount last counted; -1 before the first Count

// The fewest coins for each amount from 0 up to n, each built on a smaller one.
fn fewest(n: int) -> int {
  let best = [0; 1001];
  for a in 1..n + 1 {
    let b = best[a - 1] + 1;
    if a >= 3 { b = min(b, best[a - 3] + 1); }
    if a >= 4 { b = min(b, best[a - 4] + 1); }
    best[a] = b;
  }
  return best[n];
}

