// Googly eyes: Roll turns the loose pupils a quarter turn round their eyes, opposite ways; Drop drops them.
// icon: ring 7 12 5 ring 17 12 5 dot 7 15 2 dot 17 15 2
state turns = 0;        // quarter turns since the pupils fell: 0 bottom
state ax = [0, -1, 0, 1];  // the left pupil, clockwise from the bottom: bottom, left, top, right
state ay = [1, 0, -1, 0];

// An eye of radius 45 at (cx, 45), its pupil a third of it across, touching its edge.
fn eye(cx: int, px: int, py: int) {
  circle(cx, 45, 45, 7);
  circle(cx + px * 30, 45 + py * 30, 15, 4);
}

// The right pupil turns the other way: across mirrored.
fn scene() {
  eye(45, ax[turns], ay[turns]);
  eye(135, -ax[turns], ay[turns]);
}

label "Googly eyes";
canvas 180, 90, scene();
row {
  button "Roll" { turns = (turns + 1) % 4; }
  button "Drop" { turns = 0; }
}

// Googly eyes: tap anywhere and both eyes look that way; tap between them and they cross.
// icon: ring 7 12 5 ring 17 12 5 dot 9 12 2 dot 15 12 2
state lx = 0;           // the left pupil's place in its eye: -1, 0 or 1 across
state ly = 0;           // and down
state rx = 0;           // the right pupil's
state ry = 0;

fn sign(v: int) -> int {
  if v < 0 { return -1; }
  if v > 0 { return 1; }
  return 0;
}

// Whether a tap (dx, dy) from an eye's middle is on its middle square, 30 units a side.
fn middle(dx: int, dy: int) -> bool { return dx >= -15 && dx < 15 && dy >= -15 && dy < 15; }

// Where a pupil goes, across and down, for a tap (dx, dy) from its eye's middle.
fn across(dx: int, dy: int) -> int {
  if middle(dx, dy) || abs(dx) <= abs(dy) { return 0; }
  return sign(dx);
}

fn down(dx: int, dy: int) -> int {
  if middle(dx, dy) || abs(dx) > abs(dy) { return 0; }
  return sign(dy);
}

// An eye of radius 45 at (cx, 45), its pupil a third of it across, a third of it from the middle.
fn eye(cx: int, px: int, py: int) {
  circle(cx, 45, 45, 7);
  circle(cx + px * 30, 45 + py * 30, 15, 4);
}

fn scene() {
  eye(45, lx, ly);
  eye(135, rx, ry);
}

label "Googly eyes";
canvas 180, 90, scene() {
  lx = across(x - 45, y - 45);
  ly = down(x - 45, y - 45);
  rx = across(x - 135, y - 45);
  ry = down(x - 135, y - 45);
}

