state m = 0;              // the minutes, by fives
state hours = ["twelve", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
               "ten", "eleven"];
state fives = ["o'clock", "five past", "ten past", "quarter past", "twenty past",
               "twenty-five past", "half past", "twenty-five to", "twenty to", "quarter to",
               "ten to", "five to"];

fn digits() -> string {
  if m < 10 { return h + ":0" + m; }
  return h + ":" + m;
}

// Past the hour up to half past; after that, to the next one.
fn words() -> string {
  if m == 0 { return hours[h % 12] + " o'clock"; }
  if m <= 30 { return fives[m / 5] + " " + hours[h % 12]; }
  return fives[m / 5] + " " + hours[(h + 1) % 12];
}

