fn total() -> int {
  let t = 0;
  for i in 0..len(trips) { t += trips[i]; }
  return t;
}

fn longest() -> int {
  let m = 0;
  for i in 0..len(trips) { m = max(m, trips[i]); }
  return m;
}

fn average() -> int {
  if len(trips) == 0 { return 0; }
  return total() / len(trips);
}

