// make. Clear lowers them all.
// icon: dot 8 5 2 dot 16 5 2 dot 8 12 2 ring 16 12 2 ring 8 19 2 dot 16 19 2
state dots = [0; 6];       // the cell, 2 a row: 4 (blue) raised, 0 lowered
