             "n", "o", "p", "q", "r", "s", "t", "u", "v", "w", "x", "y", "z"];

// Letter k's dots, dot d as 2 to the power d - 1: a to j, then dot 3 (4) and dot 6 (32) added.
fn code(k: int) -> int {
  let m = [1, 3, 9, 25, 17, 11, 27, 19, 10, 26];
  if k < 10 { return m[k]; }
  if k < 20 { return m[k - 10] + 4; }
  if k == 22 { return m[9] + 32; }
  if k < 22 { return m[k - 20] + 36; }
  return m[k - 21] + 36;
}

// The raised dots the same way; dot d is the square in column (d - 1) / 3, row (d - 1) % 3.
fn raised() -> int {
  let n = 0;
  let bit = 1;
  for d in 0..6 {
    if dots[(d % 3) * 2 + d / 3] != 0 { n += bit; }
    bit = bit * 2;
  }
  return n;
}

fn letter() -> string {
  let m = raised();
  for k in 0..26 {
    if code(k) == m { return abc[k]; }
  }
  return "none";
}

