// Shell game: watch the cups swap (the two swapping glow yellow), then tap the cup that
// hides the ball. Each round starts with the ball where the last one ended.
// icon: fill 3 18 6 8 10 8 13 18 fill 13 18 16 8 20 8 23 18 dot 8 21 2
state ball = 1;           // the ball's cup: 0 left, 1 middle, 2 right
state step = 0;           // 0 the ball shows, 1 to 4 a swap, 5 the pick
state speed = 0;          // ms a step; 0 between rounds and at the pick
state picking = false;
state sa = [0, 1, 0, 0];  // the swaps' cups, in order
state sb = [1, 2, 2, 1];
state wins = 0;
state losses = 0;
state said = "";

// A cup's color: the ball's green while it shows, a swap's two yellow, the rest red.
fn hue(i: int) -> int {
  if speed > 0 && step > 0 {
    if i == sa[step - 1] || i == sb[step - 1] { return 3; }
    return 1;
  }
  if !picking && i == ball { return 2; }
  return 1;
}

fn scene() {
  let b = [0, 0, 0];
  for i in 0..3 { b[i] = hue(i); }
  pixels(b, 0, 0, 3, 32);
}

fn start() {
  step = 0;
  said = "";
  speed = 500;
}

fn guess(i: int) {
  if !picking { return; }
  picking = false;
  if i == ball {
    said = "Found it!";
    wins += 1;
  } else {
    said = "Missed";
    losses += 1;
  }
}

every speed {
  step += 1;
  if step <= 4 {
    let a = sa[step - 1];
    let b = sb[step - 1];
    if ball == a {
      ball = b;
    } else if ball == b {
      ball = a;
    }
  } else {
    speed = 0;
    picking = true;
  }
}

