state said = "Tap a cup to hide the ball under it";

// The cups as they look: the ball's cup green for the one hiding it, a picked cup yellow;
// all alike while the friend guesses; the ball shown again once told.
fn paint() {
  for i in 0..3 {
    cups[i] = 4;
    if phase != 2 && i == ball { cups[i] = 2; }
    if i == picked { cups[i] = 3; }
  }
}

fn swap(c: int) {
  if picked < 0 {
    picked = c;
    return;
  }
  if ball == picked {
    ball = c;
  } else if ball == c {
    ball = picked;
  }
  picked = -1;
}

fn tap(c: int) {
  if phase == 0 {
    ball = c;
    phase = 1;
    said = "Tap two cups to swap them; Done when mixed";
  } else if phase == 1 {
    swap(c);
  } else if phase == 2 {
    phase = 3;
    if c == ball {
      said = "Found it!";
    } else {
      said = "Wrong cup, the ball was elsewhere";
    }
  }
  paint();
}

label "Shell game";
grid 3, cups { tap(cell); }
label said;
row {
  if phase == 1 {
    button "Done" {
      phase = 2;
      picked = -1;
      said = "Friend: tap the cup hiding the ball";
      paint();
    }
  }
  if phase == 3 {
    button "Play again" {
      phase = 0;
      ball = -1;
      said = "Tap a cup to hide the ball under it";
      paint();
    }
  }
}

// Beetle: Red and Blue take turns to Roll; 6 is the body, 5 the head, 4 a leg, 3 an eye,
// 2 a feeler, 1 the tail. A body comes first, a head before eyes and feelers.
// icon: fill 12 8 17 11 18 16 16 20 12 21 8 20 6 16 7 11 dot 12 5 3 line 7 13 3 11 line 17 13 21 11 line 7 18 3 20 line 17 18 21 20
state rolls = [5, 6, 3, 6, 4, 5, 4, 2, 1, 5, 6, 4, 3, 3, 4, 2, 4, 6, 4, 1, 4, 3, 2, 4, 5];
state next = 0;           // the next roll of the list
state last = 0;           // the last roll, 0 before any
state turn = 0;           // 0 Red, 1 Blue
state body = [0, 0];      // each beetle's parts: Red's, then Blue's
state head = [0, 0];
state legs = [0, 0];
state eyes = [0, 0];
state feel = [0, 0];
state tail = [0, 0];
state won = -1;           // the winner, -1 while playing

fn parts(p: int) -> int { return body[p] + head[p] + legs[p] + eyes[p] + feel[p] + tail[p]; }

// The roll r on player p's beetle, if it can be used.
fn grow(p: int, r: int) {
  if r == 6 && body[p] == 0 { body[p] = 1; }
  if body[p] == 0 { return; }
  if r == 5 { head[p] = 1; }
  if r == 4 { legs[p] = min(6, legs[p] + 1); }
  if r == 1 { tail[p] = 1; }
  if head[p] == 0 { return; }
  if r == 3 { eyes[p] = min(2, eyes[p] + 1); }
  if r == 2 { feel[p] = min(2, feel[p] + 1); }
}

fn roll() {
  if won >= 0 { return; }
  last = rolls[next];
  next = (next + 1) % len(rolls);
  grow(turn, last);
  if parts(turn) == 13 { won = turn; }
  turn = 1 - turn;
}

fn fresh() {
  for p in 0..2 {
    body[p] = 0; head[p] = 0; legs[p] = 0; eyes[p] = 0; feel[p] = 0; tail[p] = 0;
  }
  next = 0;
  last = 0;
  turn = 0;
  won = -1;
}

// One beetle around x = cx, in its player's color.
fn beetle(p: int, cx: int, k: int) {
  if tail[p] == 1 { line(cx, 80, cx, 96, 2, k); }
  for i in 0..legs[p] { line(cx, 50 + i / 2 * 12, cx - 24 + i % 2 * 48, 44 + i / 2 * 12, 2, k); }
  if body[p] == 1 { circle(cx, 60, 18, k); }
  for i in 0..feel[p] { line(cx, 28, cx - 12 + i * 24, 12, 2, k); }
  if head[p] == 1 { circle(cx, 32, 9, k); }
  for i in 0..eyes[p] { circle(cx - 4 + i * 8, 30, 2, 9); }
}

fn scene() {
  beetle(0, 40, 1);
  beetle(1, 120, 4);
}

fn name(p: int) -> string {
  if p == 0 { return "Red"; }
  return "Blue";
}

fn rolled() -> string {
  if last == 0 { return "-"; }
  return "" + last;
}

label "Beetle";
canvas 160, 104, scene();
label "Rolled: " + rolled();
label "Red: " + parts(0) + "   Blue: " + parts(1);
