// Doublets: turn COLD into WARM a letter at a time. Type the next word (in capitals) and
// press Step; each must be a listed word one letter from the last. Back undoes a step.
// icon: line 6 3 6 21 line 18 3 18 21 line 6 7 18 7 line 6 12 18 12 line 6 17 18 17
state words = ["BOLD", "BOLT", "BOND", "CARD", "CARE", "COLD", "COLT", "CORD", "CORE", "WARD", "WARE", "WARM", "WOLD", "WORD", "WORE", "WORM"];
state letters = ["B", "O", "L", "D", "B", "O", "L", "T", "B", "O", "N", "D", "C", "A", "R", "D", "C", "A", "R", "E", "C", "O", "L", "D", "C", "O", "L", "T", "C", "O", "R", "D", "C", "O", "R", "E", "W", "A", "R", "D", "W", "A", "R", "E", "W", "A", "R", "M", "W", "O", "L", "D", "W", "O", "R", "D", "W", "O", "R", "E", "W", "O", "R", "M"];
state ladder = [5];       // the words of the ladder, as places in the list: COLD first
state typed = "";
state said = "";
state solved = false;

// The place of word w in the list, or -1.
fn find(w: string) -> int {
  for i in 0..len(words) {
    if words[i] == w { return i; }
  }
  return -1;
}

// How many letters words a and b (places in the list) differ in.
fn apart(a: int, b: int) -> int {
  let n = 0;
  for k in 0..4 {
    if letters[a * 4 + k] != letters[b * 4 + k] { n += 1; }
  }
  return n;
}

fn step() {
  if solved { return; }
  let w = find(typed);
  if w < 0 {
    said = "Not a word";
    return;
  }
  if apart(ladder[len(ladder) - 1], w) != 1 {
    said = "One letter only";
    return;
  }
  push(ladder, w);
  typed = "";
  said = "";
  if words[w] == "WARM" { solved = true; }
}

fn shown() -> string {
  let s = words[ladder[0]];
  for i in 1..len(ladder) { s = s + " > " + words[ladder[i]]; }
  return s;
}

fn message() -> string {
  if solved { return "Solved in " + (len(ladder) - 1) + " steps!"; }
  return said;
}

