state letters = ["c", "a", "t", "c", "o", "t", "c", "o", "g", "d", "o", "g", "d", "o", "t", "c", "u", "t", "h", "a", "t", "h", "o", "t", "h", "o", "g", "b", "a", "t", "b", "a", "g", "b", "o", "g"];
