fn known(w: string) -> bool {
  for i in 0..len(names) {
    if names[i] == w { return true; }
  }
  return false;
}

fn children(p: int) -> int {
  let n = 0;
  for i in 0..len(names) {
    if parent[i] == p { n += 1; }
  }
  return n;
