// Everyone below p: a person is if their parent is p or below p (parents come first).
fn descendants(p: int) -> int {
  let below = [false; len(names)];
  let n = 0;
  for i in 0..len(names) {
    let up = parent[i];
    if up == p || (up >= 0 && below[up]) {
      below[i] = true;
      n += 1;
    }
  }
  return n;
