fn removed(r: int) -> string {
  if r == 0 { return ""; }
  if r == 1 { return " once removed"; }
  if r == 2 { return " twice removed"; }
  return " " + r + " times removed";
}

fn greats(n: int) -> string {
  let s = "";
  repeat n { s = s + "great-"; }
  return s;
}

// What two people a and b generations below their closest shared ancestor are.
fn relation(a: int, b: int) -> string {
  if a < 1 || b < 1 { return "Type two numbers, 1 or more"; }
  let near = min(a, b);
  let far = max(a, b);
  if far == 1 { return "Siblings"; }
  if near == 1 { return greats(far - 2) + "aunt or uncle and " + greats(far - 2) + "niece or nephew"; }
  if near - 1 > len(nth) { return "Cousins too far apart to name"; }
  return nth[near - 2] + " cousins" + removed(far - near);
}

