// Rubik's cube, unfolded as a cross: U D L R F B turn a face a quarter clockwise as you look at
// it, U' D' L' R' F' B' turn it back. Scramble mixes it the same way each time; Reset solves it.
// icon: loop 3 3 21 3 21 21 3 21 line 9 3 9 21 line 15 3 15 21 line 3 9 21 9 line 3 15 21 15
state cube = [
  0, 0, 0, 6, 6, 6, 0, 0, 0, 0, 0, 0,
  0, 0, 0, 6, 6, 6, 0, 0, 0, 0, 0, 0,
  0, 0, 0, 6, 6, 6, 0, 0, 0, 0, 0, 0,
  5, 5, 5, 2, 2, 2, 1, 1, 1, 4, 4, 4,
  5, 5, 5, 2, 2, 2, 1, 1, 1, 4, 4, 4,
  5, 5, 5, 2, 2, 2, 1, 1, 1, 4, 4, 4,
  0, 0, 0, 3, 3, 3, 0, 0, 0, 0, 0, 0,
  0, 0, 0, 3, 3, 3, 0, 0, 0, 0, 0, 0,
  0, 0, 0, 3, 3, 3, 0, 0, 0, 0, 0, 0
];                        // the net, 12 x 9 squares: top, then left front right back, then bottom
// Each face's quarter turn: five cycles of four squares, each square's color moving to the next.
state turns = [
  3, 5, 29, 27, 4, 17, 28, 15, 36, 45, 42, 39, 37, 46, 43, 40, 38, 47, 44, 41,
  60, 63, 66, 69, 61, 64, 67, 70, 62, 65, 68, 71, 75, 77, 101, 99, 76, 89, 100, 87,
  3, 39, 75, 71, 15, 51, 87, 59, 27, 63, 99, 47, 36, 38, 62, 60, 37, 50, 61, 48,
  5, 69, 77, 41, 17, 57, 89, 53, 29, 45, 101, 65, 42, 44, 68, 66, 43, 56, 67, 54,
  27, 42, 77, 62, 28, 54, 76, 50, 29, 66, 75, 38, 39, 41, 65, 63, 40, 53, 64, 51,
  3, 60, 101, 44, 4, 48, 100, 56, 5, 36, 99, 68, 45, 47, 71, 69, 46, 59, 70, 57
];
state faces = ["U", "D", "L", "R", "F", "B"];
state sides = [5, 2, 1, 4];   // left, front, right, back
state moves = 0;

fn turn(f: int) {
  for k in 0..5 {
    let at = f * 20 + k * 4;
    let t = cube[turns[at + 3]];
    cube[turns[at + 3]] = cube[turns[at + 2]];
    cube[turns[at + 2]] = cube[turns[at + 1]];
    cube[turns[at + 1]] = cube[turns[at]];
    cube[turns[at]] = t;
  }
}

fn play(f: int, times: int) {
  repeat times { turn(f); }
  moves += 1;
}

// Square i's color on a solved cube.
fn home(i: int) -> int {
  let band = i / 36;
  let c = i % 12 / 3;
  if band == 1 { return sides[c]; }
  if c != 1 { return 0; }
  if band == 0 { return 6; }
  return 3;
}

fn reset() {
  for i in 0..108 { cube[i] = home(i); }
  moves = 0;
}

fn scene() { pixels(cube, 0, 0, 12, 10); }

// Every square matches its face's middle square.
fn solved() -> bool {
  for i in 0..108 {
    if cube[i] != cube[i / 36 * 36 + 12 + i % 12 / 3 * 3 + 1] { return false; }
  }
  return true;
}

