}

// Whether square b lies along square a's arrow.
fn along(a: int, b: int) -> bool {
  let c = a % 4;
  let r = a / 4;
  if dx[a] == 0 && dy[a] == 0 { return false; }
  for k in 0..3 {
    c += dx[a];
    r += dy[a];
    if c >= 0 && c < 4 && r >= 0 && r < 4 && r * 4 + c == b { return true; }
  }
  return false;
}

fn tap(i: int) {
  if top == 16 { return; }
  if num[i] == top && top > 1 {
    num[i] = 0;
    top -= 1;
  } else if num[i] == 0 && along(find(top), i) {
    top += 1;
    num[i] = top;
  }
}

fn shade(i: int) -> int {
  if num[i] > 0 { return 3; }
  return 0;
}

