// Twiddle: turn 2 x 2 blocks of tiles until the rows are red, green, yellow and blue. Tap a tile to
// turn the block it is the top left of clockwise; Undo turns the last one back.
// icon: loop 4 4 20 4 20 20 4 20 arc 12 12 5 300 200 line 7 9 7 13 11 13
state tiles = [1, 1, 2, 1, 1, 2, 3, 2, 2, 3, 3, 4, 4, 4, 3, 4];
state done = [0; 0];      // the block of each turn made, by its top left square

// Turns the block with top left square a: clockwise, or back the other way.
fn spin(a: int, back: bool) {
  let t = tiles[a];
  if back {
    tiles[a] = tiles[a + 1];
    tiles[a + 1] = tiles[a + 5];
    tiles[a + 5] = tiles[a + 4];
    tiles[a + 4] = t;
  } else {
    tiles[a] = tiles[a + 4];
    tiles[a + 4] = tiles[a + 5];
    tiles[a + 5] = tiles[a + 1];
    tiles[a + 1] = t;
  }
}

fn solved() -> bool {
  for i in 0..16 {
    if tiles[i] != i / 4 + 1 { return false; }
  }
  return true;
}

fn tap(i: int) {
  if solved() || i % 4 == 3 || i >= 12 { return; }
  spin(i, false);
  push(done, i);
}

fn undo() {
  let n = len(done);
  if n == 0 { return; }
  spin(done[n - 1], true);
  remove(done, n - 1);
}

fn restart() {
  let start = [1, 1, 2, 1, 1, 2, 3, 2, 2, 3, 3, 4, 4, 4, 3, 4];
  for i in 0..16 { tiles[i] = start[i]; }
  clear(done);
}

