state sea = [false; 25];

fn shaded(c: int, r: int) -> bool {
  if c < 0 || c > 4 || r < 0 || r > 4 { return false; }
  return sea[r * 5 + c];
}

// Whether the 2 x 2 block with top left square (c, r) is all sea.
fn block(c: int, r: int) -> bool {
  return shaded(c, r) && shaded(c + 1, r) && shaded(c, r + 1) && shaded(c + 1, r + 1);
}

fn pool(i: int) -> bool {
  let c = i % 5;
  let r = i / 5;
  return block(c, r) || block(c - 1, r) || block(c, r - 1) || block(c - 1, r - 1);
}

fn count() -> int {
  let n = 0;
  for i in 0..25 {
    if sea[i] { n += 1; }
  }
  return n;
}

fn solved() -> bool {
  let group = [0; 25];
  for i in 0..25 {
    group[i] = i;
    if sea[i] && pool(i) { return false; }
  }
  // Each square takes the least group of a neighbour of its own kind, until all have spread.
  for pass in 0..25 {
    for i in 0..25 {
      if i % 5 > 0 && sea[i - 1] == sea[i] { group[i] = min(group[i], group[i - 1]); }
      if i % 5 < 4 && sea[i + 1] == sea[i] { group[i] = min(group[i], group[i + 1]); }
      if i >= 5 && sea[i - 5] == sea[i] { group[i] = min(group[i], group[i - 5]); }
      if i < 20 && sea[i + 5] == sea[i] { group[i] = min(group[i], group[i + 5]); }
    }
  }
  let size = [0; 25];
  let nums = [0; 25];
  let want = [0; 25];
  let ocean = -1;
  for i in 0..25 {
    if sea[i] {
      if ocean >= 0 && group[i] != ocean { return false; }
      ocean = group[i];
    } else {
      size[group[i]] += 1;
      if clue[i] > 0 {
        nums[group[i]] += 1;
        want[group[i]] = clue[i];
      }
    }
  }
  for i in 0..25 {
    if !sea[i] && group[i] == i && (nums[i] != 1 || size[i] != want[i]) { return false; }
  }
  return true;
}

fn tap(i: int) {
  if clue[i] == 0 && !solved() { sea[i] = !sea[i]; }
}

fn shade(i: int) -> int {
  if clue[i] > 0 { return 3; }
  if sea[i] && pool(i) { return 1; }
  if sea[i] { return 4; }
  return 0;
}

