// Konane: jump your red stones over the computer's blue ones, straight along a row or column, taking
// them off. Tap a stone, then where it lands; whoever cannot jump on their turn loses.
// icon: ring 7 7 4 dot 17 7 4 dot 7 17 4 ring 17 17 4 line 10 7 14 7
state stones = [
  1, 4, 1, 4, 1, 4,
  4, 1, 4, 1, 4, 1,
  1, 4, 0, 0, 1, 4,
  4, 1, 4, 1, 4, 1,
  1, 4, 1, 4, 1, 4,
  4, 1, 4, 1, 4, 1
];                        // 1 mine (red), 4 the computer's (blue), 0 empty
state dxs = [0, 1, 0, -1];   // up, right, down, left
state dys = [-1, 0, 1, 0];
state pick = -1;
state over = 0;           // who won: 1 me, 4 the computer

// Whether player p's stone at f may jump to t: straight, over the other's stones with empty
// squares between them, landing on an empty square.
fn legal(f: int, t: int, p: int) -> bool {
  let fc = f % 6;
  let fr = f / 6;
  let dist = abs(t % 6 - fc) + abs(t / 6 - fr);
  if stones[f] != p || stones[t] != 0 || (t % 6 != fc && t / 6 != fr) || dist % 2 == 1 { return false; }
  let sx = (t % 6 - fc) / dist;
  let sy = (t / 6 - fr) / dist;
  for k in 1..dist {
    let i = (fr + sy * k) * 6 + fc + sx * k;
    if k % 2 == 1 && stones[i] != 5 - p { return false; }
    if k % 2 == 0 && stones[i] != 0 { return false; }
  }
  return true;
}

// Where square i's stone lands jumping one stone in direction d, or -1 off the board.
fn beyond(i: int, d: int) -> int {
  let c = i % 6 + dxs[d] * 2;
  let r = i / 6 + dys[d] * 2;
  if c < 0 || c > 5 || r < 0 || r > 5 { return -1; }
  return r * 6 + c;
}

fn can(p: int) -> bool {
  for i in 0..36 {
    for d in 0..4 {
      if beyond(i, d) >= 0 && legal(i, beyond(i, d), p) { return true; }
    }
  }
  return false;
}

// Takes off every stone from f up to t and puts p's stone on t.
fn jump(f: int, t: int, p: int) {
  let dist = abs(t % 6 - f % 6) + abs(t / 6 - f / 6);
  let step = (t - f) / dist;
  for k in 0..dist { stones[f + step * k] = 0; }
  stones[t] = p;
}

fn computer() {
  for i in 0..36 {
    for d in 0..4 {
      if beyond(i, d) >= 0 && legal(i, beyond(i, d), 4) {
        jump(i, beyond(i, d), 4);
        return;
      }
    }
  }
}

fn tap(i: int) {
  if over > 0 { return; }
  if stones[i] == 1 {
    pick = i;
  } else if pick >= 0 && legal(pick, i, 1) {
    jump(pick, i, 1);
    pick = -1;
    if !can(4) {
      over = 1;
      return;
    }
    computer();
    if !can(1) { over = 4; }
  }
}

fn hue(i: int) -> int {
  if i == pick { return 2; }
  return stones[i];
}

fn scene() {
  rect(0, 0, 120, 120, 8);
  for i in 0..36 {
    rect(i % 6 * 20, i / 6 * 20, 19, 19, 0);
    if stones[i] > 0 { circle(i % 6 * 20 + 10, i / 6 * 20 + 10, 7, hue(i)); }
  }
}

fn status() -> string {
  if over == 1 { return "You win"; }
  if over == 4 { return "Computer wins"; }
  return "Your move";
}

