state over = false;

// Steps between squares a and b, counting corners as one.
fn far(a: int, b: int) -> int { return max(abs(a % 5 - b % 5), abs(a / 5 - b / 5)); }

fn count(p: int) -> int {
  let n = 0;
  for i in 0..25 {
    if cells[i] == p { n += 1; }
  }
  return n;
}

fn legal(p: int, f: int, t: int) -> bool {
  return cells[f] == p && cells[t] == 0 && (far(f, t) == 1 || far(f, t) == 2);
}

fn can(p: int) -> bool {
  for f in 0..25 {
    for t in 0..25 {
      if legal(p, f, t) { return true; }
    }
  }
  return false;
}

// The pieces p gains moving from f to t: one for a copy, and each piece it turns.
fn gain(p: int, f: int, t: int) -> int {
  let g = 0;
  if far(f, t) == 1 { g = 1; }
  for j in 0..25 {
    if far(j, t) == 1 && cells[j] == 5 - p { g += 1; }
  }
  return g;
}

fn put(p: int, f: int, t: int) {
  if far(f, t) == 2 { cells[f] = 0; }
  cells[t] = p;
  for j in 0..25 {
    if far(j, t) == 1 && cells[j] == 5 - p { cells[j] = p; }
  }
}

// The computer's best move: the most pieces, a copy before a jump, then the first landing and the
// first piece in reading order.
fn computer() {
  let best = -1;
  let bf = 0;
  let bt = 0;
  for t in 0..25 {
    for f in 0..25 {
      if legal(4, f, t) {
        let s = gain(4, f, t) * 2;
        if far(f, t) == 1 { s += 1; }
        if s > best {
          best = s;
          bf = f;
          bt = t;
        }
      }
    }
  }
  put(4, bf, bt);
}

// The computer moves, and again while I cannot.
fn reply() {
  for k in 0..25 {
    if !can(4) { return; }
    computer();
    if can(1) { return; }
  }
}

fn tap(i: int) {
  if over { return; }
  if cells[i] == 1 {
    pick = i;
  } else if pick >= 0 && legal(1, pick, i) {
    put(1, pick, i);
    pick = -1;
    reply();
    over = !can(1) && !can(4);
  }
}

fn hue(i: int) -> int {
  if i == pick { return 2; }
  return cells[i];
}

fn scene() {
  rect(0, 0, 100, 100, 8);
  for i in 0..25 {
    rect(i % 5 * 20, i / 5 * 20, 19, 19, 0);
    if cells[i] > 0 { circle(i % 5 * 20 + 10, i / 5 * 20 + 10, 7, hue(i)); }
  }
}

fn status() -> string {
  if !over { return "Your move"; }
  if count(1) > count(4) { return "You win"; }
  if count(4) > count(1) { return "Computer wins"; }
  return "Draw";
}

label "Ataxx";
