// Sandcastle: tap a column to drop a scoop of sand there. The tide rises a row every half
// second and floods whatever it can reach; build a wall high enough to keep the castle dry.
// icon: fill 4 20 4 10 8 10 8 13 10 13 10 6 14 6 14 13 16 13 16 10 20 10 20 20
state sand = [false; 80];       // 10 x 8: square c + 10 * r
state water = [false; 80];
state tide = 0;                 // rows risen this level
state scoops = 6;
state level = 1;
state speed = 0;                // ms a step; 0 while no game runs
state said = "";

fn begin() {
  for i in 0..80 {
    sand[i] = false;
    water[i] = false;
  }
  tide = 0;
  scoops = 5 + level;
  speed = 500;
}

fn stop(s: string) {
  said = s;
  speed = 0;
}

// The water: every square not sand, at or below the tide's row, reached from column 0.
fn flood() {
  let top = 8 - tide;
  let todo = [0; 0];
  for r in top..8 {
    if !sand[r * 10] && !water[r * 10] {
      water[r * 10] = true;
      push(todo, r * 10);
    }
  }
  for k in 0..80 {
    if k < len(todo) {
      let c = todo[k] % 10;
      let r = todo[k] / 10;
      let nc = [c - 1, c + 1, c, c];
      let nr = [r, r, r - 1, r + 1];
      for j in 0..4 {
        let i = nr[j] * 10 + nc[j];
        if nc[j] >= 0 && nc[j] < 10 && nr[j] >= top && nr[j] < 8 && !sand[i] && !water[i] {
          water[i] = true;
          push(todo, i);
        }
      }
    }
  }
}

every speed {
  tide += 1;
  flood();
  if water[79] {
    stop("Game over");
  } else if tide == 4 + level && level == 2 {
    stop("You win");
  } else if tide == 4 + level {
    level = 2;
    begin();
  }
}

// A scoop dropped into column c lands on top of its sand.
