// At row 5 the falling clown lands on the free end, flinging the other up; else he falls.
fn down() {
  let free = 2 - sit;
  if fx == s + free {
    fx = s + sit;
    sit = free;
    up = true;
  } else {
    lives -= 1;
    fx = s + free;
    up = true;
    if lives == 0 { stop("Game over"); }
  }
}

every speed {
