// Speed: tap one of your cards to play it on a pile one rank above or below (ace and 8 meet);
// the computer plays every two seconds. Empty your hand and stock before it does.
// icon: loop 3 6 11 6 11 18 3 18 loop 13 6 21 6 21 18 13 18 line 7 10 7 14 line 17 10 17 14
state deck = [12, 27, 20, 31, 22, 9, 29, 1, 8, 6, 16, 10, 4, 14, 18, 30, 26, 24, 15, 19, 23, 2,
  21, 11, 0, 7, 13, 5, 28, 17];  // a card is suit * 8 + rank - 1, suits S H D C
state ranks = ["A", "2", "3", "4", "5", "6", "7", "8"];
state suits = ["S", "H", "D", "C"];
state me = [-1, -1, -1, -1];   // the hands: -1 an empty place
state cpu = [-1, -1, -1, -1];
state mine = [0; 0];           // the stocks, top first, and the spare stack
state its = [0; 0];
state spare = [0; 0];
state piles = [-1, -1];
state speed = 0;               // ms a computer turn; 0 while no game runs
state result = "";

fn name(c: int) -> string { return ranks[c % 8] + suits[c / 8]; }

fn fits(a: int, b: int) -> bool {
  let d = abs(a % 8 - b % 8);
  return d == 1 || d == 7;
}

// Cards left in a hand and its stock: mine (who 0) or the computer's (who 1).
fn count(who: int) -> int {
  let n = len(mine);
  if who == 1 { n = len(its); }
  for i in 0..4 {
    if who == 0 && me[i] >= 0 { n += 1; }
    if who == 1 && cpu[i] >= 0 { n += 1; }
  }
  return n;
}

// Plays the card in place i of a hand on the first pile it fits; the stock refills the place.
fn play(who: int, i: int) -> bool {
  let c = me[i];
  if who == 1 { c = cpu[i]; }
  let p = 0;
  if c >= 0 && !fits(c, piles[0]) { p = 1; }
  if c < 0 || !fits(c, piles[p]) { return false; }
  piles[p] = c;
  if who == 0 {
    me[i] = -1;
    if len(mine) > 0 {
      me[i] = mine[0];
      remove(mine, 0);
    }
  } else {
    cpu[i] = -1;
    if len(its) > 0 {
      cpu[i] = its[0];
      remove(its, 0);
    }
  }
  return true;
}

fn start() {
  clear(mine);
  clear(its);
  clear(spare);
  for i in 0..4 {
    me[i] = deck[i];
    cpu[i] = deck[i + 4];
  }
  piles[0] = deck[8];
  piles[1] = deck[9];
  for i in 10..16 { push(mine, deck[i]); }
  for i in 16..22 { push(its, deck[i]); }
  for i in 22..30 { push(spare, deck[i]); }
  result = "";
  speed = 2000;
}

// The computer's turn: its leftmost card that fits, else two spare cards onto the piles.
every speed {
  let done = false;
  for i in 0..4 {
    if !done && play(1, i) { done = true; }
  }
  if done && count(1) == 0 {
    result = "You lose";
    speed = 0;
  } else if !done && len(spare) >= 2 {
    piles[0] = spare[0];
    piles[1] = spare[1];
    remove(spare, 0);
    remove(spare, 0);
  }
}

fn tap(c: int, r: int) {
  if speed > 0 && r == 2 && c < 4 && play(0, c) && count(0) == 0 {
    result = "You win";
    speed = 0;
  }
}

fn face(c: int, x: int, y: int) {
  rect(x * 20 + 1, y * 20 + 1, 18, 18, 7);
  let ink = 9;
  if c / 8 == 1 || c / 8 == 2 { ink = 1; }
  text(name(c), x * 20 + 10, y * 20 + 10, 8, ink);
}

fn back(x: int, y: int) { rect(x * 20 + 1, y * 20 + 1, 18, 18, 4); }

fn scene() {
  for i in 0..4 {
    if cpu[i] >= 0 { back(i, 0); }
    if me[i] >= 0 { face(me[i], i, 2); }
  }
  if len(its) > 0 { back(5, 0); }
  if len(spare) > 0 { back(5, 1); }
  if len(mine) > 0 { back(5, 2); }
  for p in 0..2 {
    if piles[p] >= 0 { face(piles[p], p + 1, 1); }
  }
  if result != "" { text(result, 80, 30, 8, 11); }
}

