fn start() {
  level = 1;
  stones = 3;
  power = 5;
  dist = 0;
  skips = 0;
  v = 0;
  result = "";
  playing = true;
}

fn throw() {
  if playing && v == 0 && stones > 0 {
    stones -= 1;
    dist = 0;
    skips = 0;
    moves = 0;
    v = power;
  }
}

fn sunk() {
  if dist >= lows[level - 1] && dist <= highs[level - 1] && level == 3 {
    result = "You win";
    playing = false;
  } else if dist >= lows[level - 1] && dist <= highs[level - 1] {
    level += 1;
    stones = 3;
  } else if stones == 0 {
    result = "Game over";
    playing = false;
  }
}

fn tick() -> int {
  if v > 0 { return 100; }
  return 0;
}

every tick() {
  dist += v;
  moves += 1;
  if moves % 3 == 0 {
    v -= 1;
    if v > 0 { skips += 1; } else { sunk(); }
  }
}

fn aim(d: int) {
  if playing && v == 0 { power = min(9, max(1, power + d)); }
}

