state mine = 0;                // the totals
state its = 0;
state last = 0;                // my last throw's power
state cpu = [7, 9, 10];
state playing = true;
state result = "";

// A stone of power p skips p times, going p + (p - 1) + ... + 1: past 50 it hits the bank.
fn skips(p: int) -> int {
  if p * (p + 1) / 2 > 50 { return 0; }
  return p;
}

fn start() {
  rounds = 0;
  mine = 0;
  its = 0;
  last = 0;
  result = "";
  playing = true;
}

fn throw() {
  if !playing { return; }
  last = power;
  mine += skips(power);
  its += skips(cpu[rounds]);
  rounds += 1;
  if rounds == 3 && mine > its {
    result = "You win";
  } else if rounds == 3 && mine < its {
    result = "Computer wins";
  } else if rounds == 3 {
    result = "A tie";
  }
  playing = rounds < 3;
}

on key "up" { power = min(10, power + 1); }
on key "down" { power = max(1, power - 1); }
on key "space" { throw(); }

// My last stone's touches on the water, 3 units a unit of distance; the bank at 50.
fn scene() {
  line(150, 0, 150, 40, 3, 2);
  let d = 0;
  for k in 0..last {
    d += last - k;
    if d <= 50 { circle(d * 3, 20, 2, 8); }
  }
}

label "Skipping Contest";
label "Power: " + power;
label "You: " + mine + "   Computer: " + its;
canvas 160, 40, scene();
label result;
if !playing { button "New game" { start(); } }

// Coaster: tap the board to move a column's track (1 coin a change); Ride sends the car along,
// each drop adding thrill, paid as coins; a column as high as the start rolls it back.
// icon: line 2 20 6 6 11 18 16 9 22 16 dot 6 5 3
state hs = [8, 6, 4, 2, 5, 7, 3, 1, 4, 2];   // each column's track height, 1 to 10
state coins = 5;
state thrill = 0;
state car = -1;                               // the car's column; -1 while no ride runs
state speed = 0;                              // ms a move: 500 while it rides
state said = "";                              // Complete or Rollback, after a ride

fn at(c: int) -> int { return (10 - hs[c]) * 10 + c; }

// The board, 10 x 10 squares of 10 units: gray supports under each green piece of track, and
// the red car on its column's piece.
fn scene() {
  let cells = [-1; 100];
  for c in 0..10 {
    for r in 11 - hs[c]..10 { cells[r * 10 + c] = 8; }
    cells[at(c)] = 2;
  }
  if car >= 0 { cells[at(car)] = 1; }
  pixels(cells, 0, 0, 10, 10);
  if said != "" { text(said, 50, 6, 10, 11); }
}

fn build(c: int, r: int) {
  if speed > 0 || coins == 0 || hs[c] == 10 - r { return; }
  hs[c] = 10 - r;
  coins -= 1;
}

fn finish(why: string) {
  car = -1;
  speed = 0;
  said = why;
  if why == "Complete" { coins += thrill; }
}

every speed {
  let next = car + 1;
  if next > 9 {
    finish("Complete");
  } else if hs[next] >= hs[0] {
    finish("Rollback");
  } else {
    if hs[next] < hs[car] { thrill += hs[car] - hs[next]; }
    car = next;
  }
}

label "Coaster";
label "Coins " + coins + "   Thrill " + thrill;
canvas 100, 100, scene() { build(x / 10, y / 10); }
if speed == 0 {
  button "Ride" {
    thrill = 0;
    said = "";
    car = 0;
    speed = 500;
  }
}

// Coaster tycoon: build roller coasters for $200 each; every coaster's riders pay $5 a second.
// icon: line 2 20 6 6 11 18 16 9 22 16 dot 6 5 3
state money = 500;
state coasters = 0;
state speed = 0;          // ms a payday: 1000 once a coaster stands

every speed { money += coasters * 5; }

label "Coaster tycoon";
label "Money $" + money;
label "Coasters " + coasters;
button "Build coaster" {
  if money >= 200 {
    money -= 200;
    coasters += 1;
    speed = 1000;
  }
}

// Auto chess: buy knights (4 gold) and archers (3) for your row; Fight, and each fights the
// goblin in its column by itself. Clear the goblins to go on; each one left costs a life.
// icon: fill 8 3 16 3 16 8 13 8 15 16 9 16 11 8 8 8 fill 6 17 18 17 18 21 6 21
state gob = [0, 5, 0, 5, 0];       // each column's goblin's health, 0 for none
state mine = [0; 5];               // your unit's health in each column, 0 for none
state kind = [0; 5];               // 1 a knight, 2 an archer
state pick = 1;
state gold = 10;
state lives = 3;
state round = 1;
state speed = 0;                   // ms a step: 500 while a fight runs
state over = false;

fn attack(k: int) -> int {
  if k == 1 { return 2; }
  return 3;
}

// The round's goblins, all at full health.
fn wave() {
  for c in 0..5 {
    gob[c] = 0;
    if round >= 3 || (round == 1 && c % 2 == 1) || (round == 2 && c % 2 == 0) { gob[c] = 5; }
  }
}

// A tap on your row places the unit chosen: a knight (4 gold, 7 health) or an archer (3, 3).
fn place(c: int, r: int) {
  let cost = 4;
  let health = 7;
  if pick == 2 {
    cost = 3;
    health = 3;
  }
  if r != 1 || mine[c] > 0 || gold < cost || speed > 0 || over { return; }
  gold -= cost;
  kind[c] = pick;
  mine[c] = health;
}

fn duels() -> bool {
  for c in 0..5 {
    if gob[c] > 0 && mine[c] > 0 { return true; }
  }
  return false;
}

fn finish() {
  speed = 0;
  gold += 5;
  let left = 0;
  for c in 0..5 {
    if gob[c] > 0 { left += 1; }
  }
  if left == 0 {
    round += 1;
  } else {
    lives = max(0, lives - left);
    over = lives == 0;
  }
  wave();
}

every speed {
  for c in 0..5 {
    if gob[c] > 0 && mine[c] > 0 {
      gob[c] = max(0, gob[c] - attack(kind[c]));
      mine[c] = max(0, mine[c] - 2);
      if mine[c] == 0 { kind[c] = 0; }
    }
  }
  if !duels() { finish(); }
}

// The board, 5 x 2 squares of 20 units, each unit's health on it.
fn scene() {
  let cells = [-1; 10];
  let hue = [-1, 4, 2];
  for c in 0..5 {
    if gob[c] > 0 { cells[c] = 1; }
    cells[5 + c] = hue[kind[c]];
  }
  pixels(cells, 0, 0, 5, 20);
  for c in 0..5 {
    if gob[c] > 0 { text(gob[c], c * 20 + 10, 10, 8, 9); }
    if mine[c] > 0 { text(mine[c], c * 20 + 10, 30, 8, 9); }
  }
  if over { text("Game over", 50, 20, 12, 11); }
}

label "Auto chess";
label "Gold " + gold + "   Lives " + lives + "   Round " + round;
canvas 100, 40, scene() { place(x / 20, y / 20); }
row {
  button "Knight" { pick = 1; }
  button "Archer" { pick = 2; }
  if speed == 0 && !over { button "Fight" { speed = 500; } }
  if over {
    button "New game" {
      for c in 0..5 {
        mine[c] = 0;
        kind[c] = 0;
      }
      gold = 10;
      lives = 3;
      round = 1;
      over = false;
      wave();
    }
  }
}

// Auto battler: buy soldiers at 3 gold each, then Fight: your army and the enemy's 2 trade blows
// on their own until one is wiped out. 5 more gold after each battle.
// icon: line 4 20 20 4 line 4 4 20 20 line 14 4 20 4 20 10 line 4 14 4 20 10 20
state gold = 10;
state mine = 0;          // your army's health: 3 a soldier
state foe = 0;           // the enemy's
state speed = 0;         // ms a blow: 500 while they fight
state said = "";

fn men(hp: int) -> int { return (hp + 2) / 3; }

// A blow each way: every soldier standing deals 1.
every speed {
  let a = men(mine);
  mine = max(0, mine - men(foe));
  foe = max(0, foe - a);
  if foe == 0 || mine == 0 {
    speed = 0;
    gold += 5;
    said = "The enemy wins";
    if foe == 0 { said = "You win!"; }
  }
}

label "Auto battler";
label "Gold " + gold;
label "Your army: " + men(mine) + "   Enemy: " + men(foe);
label said;
if speed == 0 {
  row {
    button "Buy soldier" {
      if gold >= 3 {
        gold -= 3;
        mine += 3;
      }
    }
    button "Fight" {
      foe = 6;
      said = "";
      speed = 500;
    }
  }
}

// Wedding planner: add guests by name; tap a name once they say they're coming, x removes them.
// They sit in order at 3 tables of 4; each coming guest costs 150 of the budget.
// icon: ring 9 12 6 ring 15 12 6
saved state names = [""; 0];
saved state coming = [false; 0];
state typed = "";

fn listed(n: string) -> bool {
  for i in 0..len(names) {
    if names[i] == n { return true; }
  }
  return false;
}

// The budget left: 2500, less the venue and 150 a coming guest.
fn left() -> int {
  let n = 1500;
  for i in 0..len(coming) {
    if coming[i] { n -= 150; }
  }
  return n;
}

fn seat(i: int) -> int {
  if i >= len(names) { return 0; }
  if coming[i] { return 2; }
  return 3;
}

fn reply(on: bool) -> string {
  if on { return "coming"; }
  return "not yet";
}

fn warn() -> string {
  let s = "";
  if len(names) >= 12 { s = "   Full"; }
  if left() < 0 { s = s + "   Over budget"; }
  return s;
}

// The tables: a row of 4 seats each, table 1 at the top.
fn scene() {
  for t in 0..3 {
    for s in 0..4 { circle(s * 20 + 10, t * 20 + 10, 8, seat(t * 4 + s)); }
  }
}

label "Wedding planner";
row {
  input typed;
  button "Add" {
    if typed != "" && !listed(typed) && len(names) < 12 {
      push(names, typed);
      push(coming, false);
    }
    typed = "";
  }
}
label "Guests " + len(names) + "   Left " + left() + warn();
canvas 80, 60, scene();
for i in 0..len(names) {
  row {
    button names[i] { coming[i] = !coming[i]; }
    label reply(coming[i]);
    button "x" {
      remove(names, i);
      remove(coming, i);
    }
  }
}

