// Eye color: type each parent's genes (BB, Bb or bb); the Punnett square shows their four kids
// and the chance of brown eyes, brown B beating blue b.
// icon: ring 12 12 9 dot 12 12 4
state mom = "Bb";
state dad = "Bb";

// Letter k (0 or 1) of the genes typed: B or b.
fn allele(s: string, k: int) -> string {
  if s == "BB" || (k == 0 && s == "Bb") || (k == 1 && s == "bB") { return "B"; }
  return "b";
}

// The kid of mom's letter i and dad's letter j.
fn kid(i: int, j: int) -> string { return allele(mom, i) + allele(dad, j); }

fn brown() -> int {
  let n = 0;
  for i in 0..4 {
    if kid(i / 2, i % 2) != "bb" { n += 25; }
  }
  return n;
}

