fn flip() {
  keep();
  let was = [0; 256];
  for i in 0..256 { was[i] = art[i]; }
  for i in 0..256 { art[i] = was[i / 16 * 16 + 15 - i % 16]; }
}

fn turn() {
  keep();
  let was = [0; 256];
  for i in 0..256 { was[i] = art[i]; }
