}

// 3D maze: up walks forward, left and right turn. Find the green door out.
// icon: fill 2 4 7 7 7 17 2 20 fill 22 4 17 7 17 17 22 20 loop 9 9 15 9 15 15 9 15
state map = ["#", "#", "#", "#", "#", "#",  "#", ".", ".", ".", "#", "#",
             "#", "#", ".", "#", ".", "#",  "#", ".", ".", "#", "E", "#",
             "#", ".", ".", ".", ".", "#",  "#", "#", "#", "#", "#", "#"];
state dxs = [0, 1, 0, -1];
state dys = [-1, 0, 1, 0];
state px = 1;
state py = 1;
state face = 1;              // 0 north, 1 east, 2 south, 3 west
state won = false;

fn at(x: int, y: int) -> string { return map[y * 6 + x]; }

fn walk() {
  let x = px + dxs[face];
  let y = py + dys[face];
  if won || at(x, y) == "#" { return; }
  px = x;
  py = y;
  if at(x, y) == "E" { won = true; }
}

// A ray a column, 40 of 4 units, walked square by square (DDA) in thousandths; the wall is 100
// tall right in front, shorter with distance. Walls are blue, the exit green.
fn column(c: int) {
  let k = (2 * c - 39) * 25;
  let rx = dxs[face] * 1000 - dys[face] * k * 2 / 3;
  let ry = dys[face] * 1000 + dxs[face] * k * 2 / 3;
  let gx = 1000000 / max(1, abs(rx));
  let gy = 1000000 / max(1, abs(ry));
  let sx = gx / 2;
  let sy = gy / 2;
  let mx = px;
  let my = py;
  let d = 0;
  for s in 0..12 {
    if at(mx, my) != "#" && at(mx, my) != "E" || s == 0 {
      if sx < sy {
        d = sx;
        sx += gx;
        mx += rx / max(1, abs(rx));
      } else {
        d = sy;
        sy += gy;
        my += ry / max(1, abs(ry));
      }
    }
  }
  let h = min(100, 50000 / max(1, d));
  let color = 4;
  if at(mx, my) == "E" { color = 2; }
  rect(c * 4, 50 - h / 2, 4, h, color);
}

fn scene() {
  rect(0, 50, 160, 50, 8);
  for c in 0..40 { column(c); }
  if won { text("You got out!", 80, 20, 12, 11); }
}

