// After an order, the enemy's shot, unless the shields take it.
fn shot() {
  if enemy == 0 {
    over = "You win!";
  } else if blocks > 0 {
    blocks -= 1;
  } else {
    hull = max(0, hull - 4);
    if hull == 0 { over = "You lose: your ship is destroyed"; }
  }
}

fn reset() {
  hull = 20;
  enemy = 30;
  blocks = 0;
  over = "";
}

fn scene() {
  rect(10, 20, 30, 14, 4);
  rect(120, 20, 30, 14, 1);
  if blocks > 0 { ring(25, 27, 20, blocks, 6); }
  if over != "" { text(over, 80, 50, 8, 11); }
}

label "Space battle";
label "My hull " + hull + "   Enemy hull " + enemy;
canvas 160, 60, scene();
if over == "" {
  row {
    button "Fire" {
      enemy = max(0, enemy - 5);
      shot();
    }
    button "Shields" {
      blocks = 2;
      shot();
    }
    button "Repair" {
      hull = min(20, hull + 3);
      shot();
    }
