// Ordinals: +1, -1 and +10 change the number; it shows it as an ordinal, 1st, 2nd, 3rd, 4th, 11th.
// icon: line 4 6 7 4 7 18 line 4 18 10 18 ring 16 14 4
state n = 1;

// st, nd and rd after a last digit 1, 2 and 3, except in the teens; th for the rest.
fn ending() -> string {
  let teen = n % 100 >= 11 && n % 100 <= 13;
  if !teen && n % 10 == 1 { return "st"; }
  if !teen && n % 10 == 2 { return "nd"; }
  if !teen && n % 10 == 3 { return "rd"; }
  return "th";
}

label "Ordinals";
label n + ending();
row {
  button "-1" { n = max(1, n - 1); }
  button "+1" { n += 1; }
  button "+10" { n += 10; }
}

