// Digit sum: type a whole number; it adds up its digits.
// icon: line 18 4 6 4 13 12 6 20 18 20
state num = "";

// The sum of the digits of n.
fn digits(n: int) -> int {
  let k = n;
  let s = 0;
  repeat 19 {
    s += abs(k % 10);
    k = k / 10;
  }
  return s;
}

label "Digit sum";
input num;
label "Sum: " + digits(parse(num, 0));

// Digital root: +1, +10 and +100 count up; it adds the digits again and again down to one digit.
// icon: line 3 13 6 11 9 20 14 4 21 4
state n = 0;

// The sum of the digits of k.
fn digits(k: int) -> int {
  let m = k;
  let s = 0;
  repeat 19 {
    s += m % 10;
    m = m / 10;
  }
  return s;
}

// The digits summed until one is left.
fn root() -> int {
  let r = n;
  repeat 5 { r = digits(r); }
  return r;
}

label "Digital root";
label "Number: " + n;
label "Root: " + root();
row {
  button "+1" { n += 1; }
  button "+10" { n += 10; }
  button "+100" { n += 100; }
  button "Reset" { n = 0; }
}

