// A color's digit, or -1 for a word that is not a color.
fn digit(s: string) -> int {
  for i in 0..len(names) {
    if names[i] == s { return i; }
  }
  return -1;
}

fn known() -> bool { return digit(b1) >= 0 && digit(b2) >= 0 && digit(b3) >= 0; }

