// A type's place in the list, or -1: its group is place / 2 (O 0, A 1, B 2, AB 3), Rh+ odd.
fn find(s: string) -> int {
  for i in 0..len(types) {
    if types[i] == s { return i; }
  }
  return -1;
}

fn hasa(t: int) -> bool { return (t / 2) % 2 == 1; }

fn hasb(t: int) -> bool { return t / 2 >= 2; }

// The patient has every antigen the donor has: A, B and Rh.
fn gives(d: int, p: int) -> bool {
  if hasa(d) && !hasa(p) { return false; }
  if hasb(d) && !hasb(p) { return false; }
  return d % 2 <= p % 2;
}

fn verdict() -> string {
  let d = find(donor);
  let p = find(patient);
  if d < 0 || p < 0 { return "Unknown type"; }
  if gives(d, p) { return "Compatible"; }
  return "Not compatible";
}

