// Sowing dates: type the month and day of your last spring frost; it counts back and on to the
// day to sow each crop, in a year that is not a leap year.
// icon: line 12 21 12 11 fill 12 14 5 10 4 15 fill 12 11 19 5 20 11 line 4 21 20 21
state month = "";
