// The frost as a day of the year, from 1.
fn frost() -> int {
  let m = min(12, max(1, parse(month, 1)));
  let d = min(31, max(1, parse(day, 1)));
  for i in 0..m - 1 { d += lengths[i]; }
  return d;
}

// Day n of the year as month/day; a day before or after the year wraps round it.
fn date(n: int) -> string {
  let d = (n - 1) % 365;
  if d < 0 { d += 365; }
  d += 1;
  for i in 0..12 {
    if d <= lengths[i] { return (i + 1) + "/" + d; }
    d -= lengths[i];
  }
  return "";
}

