// Domineering: tap a square to lay your blue domino on it and the one below; the computer
// answers side to side in red. Whoever cannot lay one loses.
// icon: fill 4 3 10 3 10 21 4 21 loop 13 9 21 9 21 15 13 15
state board = [0; 36];        // 0 empty, 4 yours, 1 the computer's
state over = 0;               // 0 playing, 1 you won, 2 the computer won

// Whether a domino fits on (c, r) and the square dc across, dr down from it.
fn fits(c: int, r: int, dc: int, dr: int) -> bool {
  if c + dc > 5 || r + dr > 5 { return false; }
  return board[r * 6 + c] == 0 && board[(r + dr) * 6 + c + dc] == 0;
}

// The places a domino of that way still fits.
fn places(dc: int, dr: int) -> int {
  let n = 0;
  for i in 0..36 {
    if fits(i % 6, i / 6, dc, dr) { n += 1; }
  }
  return n;
}

// The computer's answer: the first place in reading order.
fn answer() {
  for i in 0..36 {
    if fits(i % 6, i / 6, 1, 0) {
      board[i] = 1;
      board[i + 1] = 1;
      if places(0, 1) == 0 { over = 2; }
      return;
    }
  }
  over = 1;
}

fn lay(c: int, r: int) {
  if over > 0 || !fits(c, r, 0, 1) { return; }
  board[r * 6 + c] = 4;
  board[r * 6 + 6 + c] = 4;
  answer();
}

