fn way(who: int) -> int {
  if who == 2 { return 1; }
  return -1;
}

fn empty(i: int) -> bool { return i >= 0 && i < 8 && strip[i] == 0; }

// Where the creature on square i goes, or -1 if it cannot move.
fn dest(i: int) -> int {
  let who = strip[i];
  if who == 0 { return -1; }
  let d = way(who);
  if empty(i + d) { return i + d; }
  if i + d >= 0 && i + d < 8 && strip[i + d] == 6 - who && empty(i + 2 * d) { return i + 2 * d; }
  return -1;
}

fn can(who: int) -> bool {
  for i in 0..8 {
    if strip[i] == who && dest(i) >= 0 { return true; }
  }
  return false;
}

fn tap(i: int) {
  if winner > 0 || strip[i] != side || dest(i) < 0 { return; }
  strip[dest(i)] = side;
  strip[i] = 0;
  moves += 1;
  side = 6 - side;
  if !can(side) { winner = 6 - side; }
}

fn name(who: int) -> string {
  if who == 2 { return "Toads"; }
  return "Frogs";
}

