// 24: tap a card, an operation, then a second card to combine them; make the last card 24.
// Reset puts the cards back; Next deals the next puzzle once it is solved.
// icon: loop 3 5 11 5 11 19 3 19 loop 13 5 21 5 21 19 13 19 line 7 9 7 15 line 15 12 19 12
state deals = [4, 7, 8, 8, 1, 2, 3, 4, 3, 4, 5, 6, 2, 2, 6, 6, 2, 4, 5, 7];
state puzzle = 0;             // from 0
state cards = [4, 7, 8, 8];
state here = [true; 4];       // whether a card is in each square
state picked = -1;
state op = "";
state solved = 0;
state done = false;

fn deal() {
  for i in 0..4 {
    cards[i] = deals[puzzle * 4 + i];
    here[i] = true;
  }
  picked = -1;
  op = "";
  done = false;
}

fn left() -> int {
  let n = 0;
  for i in 0..4 {
    if here[i] { n += 1; }
  }
  return n;
}

// Combines the picked card into card i; a division that is not whole only drops the operation.
fn combine(i: int) -> bool {
  let a = cards[picked];
  let b = cards[i];
  if op == "/" && (b == 0 || a % b != 0) {
    op = "";
    return false;
  }
  if op == "+" { cards[i] = a + b; }
  if op == "-" { cards[i] = a - b; }
  if op == "*" { cards[i] = a * b; }
  if op == "/" { cards[i] = a / b; }
  here[picked] = false;
  picked = -1;
  op = "";
  return true;
}

fn tap(i: int) {
  if done || !here[i] { return; }
  if picked < 0 || op == "" || picked == i {
    picked = i;
  } else if combine(i) && left() == 1 && cards[i] == 24 {
    done = true;
    solved += 1;
  }
}

fn operate(o: string) {
  if picked >= 0 && !done { op = o; }
}

fn scene() {
  for i in 0..4 {
    if here[i] {
      let c = 4;
      if i == picked { c = 3; }
      rect(i * 40 + 2, 2, 36, 36, c);
      text(cards[i], i * 40 + 20, 20, 14, 9);
    }
  }
}

fn last() -> bool { return left() == 1 && !done; }

