state lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

fn leap(y: int) -> bool { return y % 4 == 0 && (y % 100 != 0 || y % 400 == 0); }

fn last(y: int, m: int) -> int {
  if m == 2 && leap(y) { return 29; }
  return lengths[m - 1];
}

// Days from Monday 1 January 1900 to y-m-d.
fn since(y: int, m: int, d: int) -> int {
  let t = d - 1;
  for i in 1900..y {
    t += 365;
    if leap(i) { t += 1; }
  }
  for i in 1..m { t += last(y, i); }
  return t;
}

fn real() -> bool {
  let y = parse(year, 0);
  let m = parse(month, 0);
  let d = parse(day, 0);
  return y >= 1900 && y <= 2100 && m >= 1 && m <= 12 && d >= 1 && d <= last(y, m);
}

// The anniversary's day of the month: 29 February falls back to the 28th in common years.
fn mday() -> int {
  let d = parse(day, 0);
  if d == 29 && parse(month, 0) == 2 && !leap(parse(year, 0) + n) { return 28; }
  return d;
}

fn two(v: int) -> string {
  if v < 10 { return "0" + v; }
  return "" + v;
}

fn then() -> int { return since(parse(year, 0) + n, parse(month, 0), mday()); }

