// tile in the bin. Three of a color in a line clear. Three missed tiles end it.
// icon: fill 3 3 21 3 21 7 3 7 fill 3 17 9 17 9 21 3 21 fill 9 17 15 17 15 21 9 21 fill 15 17 21 17 21 21 15 21 fill 9 10 15 10 15 13 9 13
state lanes = [2, 0, 4, 1, 3, 2, 0, 4];   // each tile's lane and color, in turn
state hues = [1, 1, 1, 4, 4, 4, 2, 3];
state tl = [0; 0];                        // tiles on the ramp: lane, row, color
state tr = [0; 0];
state tc = [0; 0];
state pad = 2;
state held = [0; 0];                      // the paddle's tiles, top last
state bin = [0; 25];                      // 5 x 5, row 0 at the top
state score = 0;
state missed = 0;
state t = 0;
state k = 0;
state speed = 0;
state over = false;

fn spawn() {
  push(tl, lanes[k % 8]);
  push(tr, 0);
  push(tc, hues[k % 8]);
  k += 1;
}

fn same(c: int, r: int, dc: int, dr: int) -> bool {
  let v = bin[r * 5 + c];
  let c2 = c + dc * 2;
  let r2 = r + dr * 2;
  if v == 0 || c2 < 0 || c2 > 4 || r2 < 0 || r2 > 4 { return false; }
  return bin[(r + dr) * 5 + c + dc] == v && bin[r2 * 5 + c2] == v;
}

// Clears every line of three or more, lets the tiles above fall, and again until none is left.
fn settle() {
  let dcs = [1, 0, 1, 1];
  let drs = [0, 1, 1, -1];
  repeat 12 {
    let gone = [false; 25];
    let any = false;
    for i in 0..25 {
      for d in 0..4 {
        if same(i % 5, i / 5, dcs[d], drs[d]) {
          any = true;
          for j in 0..3 { gone[(i / 5 + drs[d] * j) * 5 + i % 5 + dcs[d] * j] = true; }
        }
      }
    }
    if any {
      for i in 0..25 {
        if gone[i] {
          bin[i] = 0;
          score += 1;
        }
      }
      for c in 0..5 {
        let stack = [0; 0];
        for j in 0..5 {
          if bin[(4 - j) * 5 + c] > 0 { push(stack, bin[(4 - j) * 5 + c]); }
        }
        for j in 0..5 {
          bin[(4 - j) * 5 + c] = 0;
          if j < len(stack) { bin[(4 - j) * 5 + c] = stack[j]; }
        }
      }
    }
  }
}

fn drop() {
  if speed == 0 || len(held) == 0 || bin[pad] > 0 { return; }
  let r = 4;
  repeat 4 {
    if bin[r * 5 + pad] > 0 { r -= 1; }
  }
  bin[r * 5 + pad] = held[len(held) - 1];
  remove(held, len(held) - 1);
  settle();
}

fn steer(d: int) {
  if speed > 0 { pad = max(0, min(4, pad + d)); }
}

fn start() {
  clear(tl);
  clear(tr);
  clear(tc);
  clear(held);
  for i in 0..25 { bin[i] = 0; }
  pad = 2;
  score = 0;
  missed = 0;
  t = 0;
  k = 0;
  over = false;
  spawn();
  speed = 500;
}

every speed {
  t += 1;
  for j in 0..len(tl) {
    let i = len(tl) - 1 - j;
    tr[i] += 1;
    if tr[i] > 4 {
      if tl[i] == pad { push(held, tc[i]); } else { missed += 1; }
      remove(tl, i);
      remove(tr, i);
      remove(tc, i);
    }
  }
  if missed >= 3 {
    speed = 0;
    over = true;
  } else if t % 4 == 0 {
    spawn();
  }
}

fn scene() {
  let b = [0; 55];
  for i in 0..len(tl) { b[tr[i] * 5 + tl[i]] = tc[i]; }
  b[25 + pad] = 8;
  if len(held) > 0 { b[25 + pad] = held[len(held) - 1]; }
  for i in 0..25 { b[30 + i] = bin[i]; }
  pixels(b, 0, 0, 5, 12);
}

