// Jungle chess for two: New game sets up; tap your animal, then where it goes. It takes an enemy no
// stronger (the rat takes the elephant); lions and tigers jump the rivers. Reach the enemy den to win.
// icon: fill 12 3 20 9 17 21 7 21 4 9 dot 9 10 1 dot 15 10 1
state side = [0; 63];                             // 1 red, 4 blue; set up by New game
state kind = [0; 63];
state homes = [0, 6, 8, 12, 14, 16, 18, 20];   // blue's squares; red's mirror them (62 - i)
state ranks = [7, 6, 3, 2, 1, 5, 4, 8];          // 1 rat 2 cat 3 dog 4 wolf 5 leopard 6 tiger 7 lion 8 elephant
state turn = 1;
state pick = -1;
state win = 0;

fn water(i: int) -> bool {
  let c = i % 7;
  return i / 7 >= 3 && i / 7 <= 5 && c != 0 && c != 3 && c != 6;
}

fn den(s: int) -> int {
  if s == 1 { return 59; }
  return 3;
}

// Whether square i is one of the traps around side s's den.
fn trap(s: int, i: int) -> bool {
  let d = den(s);
  return i != d && (abs(i - d) == 1 || abs(i - d) == 7);
}

// An animal in an enemy trap counts as rank 0.
fn rank(i: int) -> int {
  if trap(5 - side[i], i) { return 0; }
  return kind[i];
}

fn near(a: int, b: int) -> bool {
  return abs(a - b) == 7 || (abs(a - b) == 1 && a / 7 == b / 7);
}

// Where a jump from a stepping d lands across the river, else -1 (no river there, or a rat in it).
fn jump(a: int, d: int) -> int {
  if (d == -1 && a % 7 == 0) || (d == 1 && a % 7 == 6) || a + d < 0 || a + d > 62 { return -1; }
  let q = a + d;
  if !water(q) { return -1; }
  repeat 3 {
    if water(q) {
      if side[q] > 0 { return -1; }
      q += d;
    }
  }
  return q;
}

fn reach(a: int, b: int) -> bool {
  if near(a, b) { return !water(b) || kind[a] == 1; }
  if kind[a] != 6 && kind[a] != 7 { return false; }
  return jump(a, -7) == b || jump(a, 7) == b || jump(a, -1) == b || jump(a, 1) == b;
}

fn legal(a: int, b: int) -> bool {
  if b == den(side[a]) || side[b] == side[a] || !reach(a, b) { return false; }
  if side[b] == 0 { return true; }
  if water(a) != water(b) { return false; }
  if kind[a] == 1 && kind[b] == 8 { return true; }
  if kind[a] == 8 && kind[b] == 1 { return false; }
  return kind[a] >= rank(b);
}

fn left(s: int) -> int {
  let n = 0;
  for i in 0..63 {
    if side[i] == s { n += 1; }
  }
  return n;
}

fn tap(i: int) {
  if win > 0 { return; }
  if side[i] == turn {
    pick = i;
  } else if pick >= 0 && legal(pick, i) {
    side[i] = turn;
    kind[i] = kind[pick];
    side[pick] = 0;
    kind[pick] = 0;
    pick = -1;
    if i == den(5 - turn) || left(5 - turn) == 0 { win = turn; }
    turn = 5 - turn;
  }
}

fn setup() {
  for i in 0..63 {
    side[i] = 0;
    kind[i] = 0;
  }
  for k in 0..8 {
    side[homes[k]] = 4;
    kind[homes[k]] = ranks[k];
    side[62 - homes[k]] = 1;
    kind[62 - homes[k]] = ranks[k];
  }
  turn = 1;
  pick = -1;
  win = 0;
}

fn hue(i: int) -> int {
  if i == pick { return 2; }
  return side[i];
}

fn scene() {
  for i in 0..63 {
    let x = i % 7 * 20;
    let y = i / 7 * 20;
    if water(i) { rect(x, y, 20, 20, 6); }
    if i == 3 || i == 59 { ring(x + 10, y + 10, 8, 2, 3); }
    if trap(1, i) || trap(4, i) { ring(x + 10, y + 10, 7, 1, 8); }
    if side[i] > 0 {
      rect(x + 2, y + 2, 16, 16, hue(i));
      text(kind[i], x + 5, y + 5, 7, 9);
    }
  }
}

fn who(s: int) -> string {
  if s == 1 { return "Red"; }
  return "Blue";
}

