  rect(0, 0, 100, 100, 8);
  for i in 0..25 { rect(i % 5 * 20, i / 5 * 20, 19, 19, 0); }
  for t in 0..8 { tube(t); }
  for k in 0..5 {
    text(need[k], 110, k * 20 + 10, 10, 9);
    text(needc[k], k * 20 + 10, 110, 10, 9);
  }
}

