// What is k squares from p in direction (dx, dy): 0 empty, 1 or 4 a marble, -1 off the board.
fn ahead(p: int, dx: int, dy: int, k: int) -> int {
  let c = p % 7 + dx * k;
  let r = p / 7 + dy * k;
  if c < 0 || c > 6 || r < 0 || r > 6 { return -1; }
  return board[r * 7 + c];
}

fn shove(dx: int, dy: int) {
