state must = 0;           // the color that must move; 0 any
state pick = -1;
state winner = 0;

fn hue(i: int) -> int { return (i % 5 + 2 * (i / 5)) % 5 + 1; }

// Whether the tower on f may go to t: ahead, straight or diagonal, nothing on the way.
fn legal(f: int, t: int) -> bool {
  let ahead = 1;
  if own[f] == 2 { ahead = -1; }
  let dr = t / 5 - f / 5;
  let dc = t % 5 - f % 5;
  if dr * ahead <= 0 || (dc != 0 && abs(dc) != abs(dr)) { return false; }
  let n = abs(dr);
  for k in 1..n + 1 {
    if own[f + (dr / n * 5 + dc / n) * k] != 0 { return false; }
  }
  return true;
}

fn stuck(f: int) -> bool {
  for t in 0..25 {
    if legal(f, t) { return false; }
  }
  return true;
}

fn find(p: int, color: int) -> int {
  for i in 0..25 {
    if own[i] == p && tc[i] == color { return i; }
  }
  return 0;
}

fn go(f: int, t: int) {
  own[t] = own[f];
  tc[t] = tc[f];
  own[f] = 0;
  tc[f] = 0;
  pick = -1;
  if (turn == 1 && t / 5 == 4) || (turn == 2 && t / 5 == 0) {
    winner = turn;
    return;
  }
  turn = 3 - turn;
  must = hue(t);
  let next = find(turn, must);
  if stuck(next) {
    turn = 3 - turn;
    must = hue(next);
  }
}

fn tap(i: int) {
  if winner > 0 { return; }
  if own[i] == turn && (must == 0 || tc[i] == must) {
    pick = i;
  } else if pick >= 0 && legal(pick, i) {
    go(pick, i);
  }
}

fn middle(i: int) -> int {
  if own[i] == 1 { return 9; }
  return 0;
}

fn scene() {
