// What square (x, y) holds: -1 off the board, 0 empty, 2 a block, 8 a wall.
fn kind(x: int, y: int) -> int {
  if x < 0 || x > 8 || y < 0 || y > 8 { return -1; }
  return board[y * 9 + x];
}

fn at(x: int, y: int) -> bool { return (cat || cheese) && x == cx && y == cy; }

fn start() {
  for i in 0..81 { board[i] = level[i]; }
  mx = 4;
  my = 4;
  cx = 0;
  cy = 0;
  cat = true;
  cheese = false;
  score = 0;
  speed = 1000;
  result = "";
}

fn step(dx: int, dy: int) {
  if speed == 0 { return; }
  let tx = mx + dx;
  let ty = my + dy;
  if cheese && tx == cx && ty == cy {
    cheese = false;
    score += 100;
    mx = tx;
    my = ty;
    result = "You win";
    speed = 0;
    return;
  }
  if kind(tx, ty) < 0 || kind(tx, ty) == 8 || at(tx, ty) { return; }
  if kind(tx, ty) == 2 {
    let n = 0;
    for k in 0..9 {
      if n == k && kind(tx + dx * k, ty + dy * k) == 2 { n += 1; }
    }
    let ex = tx + dx * n;
    let ey = ty + dy * n;
    if kind(ex, ey) != 0 || at(ex, ey) { return; }
    board[ey * 9 + ex] = 2;
    board[ty * 9 + tx] = 0;
  }
  mx = tx;
  my = ty;
}

// Where the cat may step: an empty square or the mouse's.
fn free(x: int, y: int) -> bool { return kind(x, y) == 0; }

fn toward(a: int, b: int) -> int {
  if b > a { return 1; }
  return -1;
}

every speed {
  if !cat { return; }
  if !free(cx + 1, cy) && !free(cx - 1, cy) && !free(cx, cy + 1) && !free(cx, cy - 1) {
    cat = false;
    cheese = true;
    return;
  }
  let moved = false;
  if cx != mx && free(cx + toward(cx, mx), cy) {
    cx += toward(cx, mx);
    moved = true;
  }
  if !moved && cy != my && free(cx, cy + toward(cy, my)) { cy += toward(cy, my); }
  if cx == mx && cy == my {
    result = "Caught! Game over";
    speed = 0;
    cat = false;
  }
}

fn scene() {
  rect(0, 0, 180, 180, 10);
  for i in 0..81 { rect(i % 9 * 20, i / 9 * 20, 19, 19, board[i]); }
  if cat { circle(cx * 20 + 10, cy * 20 + 10, 8, 1); }
  if cheese { rect(cx * 20 + 3, cy * 20 + 4, 14, 12, 3); }
  if speed > 0 || result != "" { circle(mx * 20 + 10, my * 20 + 10, 7, 4); }
}

