// Turf claim: the arrows move you, and every square you step on turns yours. The computer sweeps
// the rows from the bottom; after 30 seconds, whoever owns more squares wins.
// icon: fill 3 3 12 3 12 12 3 12 loop 12 12 21 12 21 21 12 21 dot 7 7 2
state own = [0; 64];           // the 8 x 8 board, c + 8 * r: 0 nobody's, 2 mine, 1 the computer's
state me = 0;
state it = 63;
state steps = 0;               // the computer's steps, 60 in all
state speed = 0;               // ms a step; 0 while no game runs
state result = "";

fn count(v: int) -> int {
  let n = 0;
  for i in 0..64 {
    if own[i] == v { n += 1; }
  }
  return n;
}

fn start() {
  for i in 0..64 { own[i] = 0; }
  me = 0;
  it = 63;
  own[0] = 2;
  own[63] = 1;
  steps = 0;
  result = "";
  speed = 500;
}

fn move(dc: int, dr: int) {
  let c = me % 8 + dc;
  let r = me / 8 + dr;
  if speed == 0 || c < 0 || c >= 8 || r < 0 || r >= 8 { return; }
  me = r * 8 + c;
  own[me] = 2;
}

// The computer's next square: leftward on rows 7, 5, 3, 1, rightward on 6, 4, 2, 0, up at a row's end.
fn next() -> int {
  let c = it % 8;
  if it / 8 % 2 == 1 && c > 0 { return it - 1; }
  if it / 8 % 2 == 0 && c < 7 { return it + 1; }
  return it - 8;
}

every speed {
  it = next();
  own[it] = 1;
  steps += 1;
  if steps == 60 {
    speed = 0;
    if count(2) > count(1) {
      result = "You win";
    } else if count(2) < count(1) {
      result = "You lose";
    } else {
      result = "Draw";
    }
  }
}

on key "left" { move(-1, 0); }
on key "right" { move(1, 0); }
on key "up" { move(0, -1); }
on key "down" { move(0, 1); }

fn scene() {
  let cells = [-1; 64];
  for i in 0..64 {
    if own[i] > 0 { cells[i] = own[i]; }
  }
  if speed > 0 || result != "" {
    cells[it] = 5;
    cells[me] = 4;
  }
  pixels(cells, 0, 0, 8, 12);
  if result != "" { text(result, 48, 48, 12, 11); }
}

