// Deep sea diver: the arrows swim; grab the treasures and bring them up before your air runs out.
// The shark swims along its row each time you move.
// icon: ring 12 9 5 line 12 14 12 20 line 7 17 17 17 dot 12 9 2
state rock = [17, 18, 20, 21, 51];       // squares of the 8 x 8 board, c + 8 * r
state gold = [0; 0];                     // the treasures still down there
state me = 3;
state shark = 40;
state way = 1;                           // the shark's way along row 5
state air = 15;
state carry = 0;
state score = 0;
state playing = false;
state result = "";

fn isRock(i: int) -> bool {
  for k in 0..len(rock) {
    if rock[k] == i { return true; }
  }
  return false;
}

fn stop(s: string) {
  result = s;
  playing = false;
}

fn start() {
  clear(gold);
  push(gold, 30);
  push(gold, 32);
  push(gold, 50);
  me = 3;
  shark = 40;
  way = 1;
  air = 15;
  carry = 0;
  score = 0;
  result = "";
  playing = true;
}

fn swim() {
  if shark % 8 + way < 0 || shark % 8 + way > 7 { way = -way; }
  shark += way;
  if shark == me { stop("Game over"); }
}

fn take() {
  let k = -1;
  for i in 0..len(gold) {
    if gold[i] == me { k = i; }
  }
  if k >= 0 {
    remove(gold, k);
    carry += 1;
  }
}

// After a step: on the surface the treasure is banked and the air filled; under water, a breath.
fn breathe() {
  if me < 8 {
    score += carry;
    carry = 0;
    air = 15;
    if score == 3 {
      stop("You win");
      return;
    }
  } else {
    air -= 1;
    if air == 0 {
      stop("Game over");
      return;
    }
  }
  swim();
}

fn move(dc: int, dr: int) {
  let c = me % 8 + dc;
  let r = me / 8 + dr;
  if !playing || c < 0 || c > 7 || r < 0 || r > 7 || isRock(r * 8 + c) { return; }
  me = r * 8 + c;
  if me == shark {
    stop("Game over");
    return;
  }
  take();
  breathe();
}

