// then reach the exit. A boulder that falls onto you ends it.
// icon: ring 9 14 6 fill 17 3 21 8 17 13 13 8
// The cave, 8 x 8, square c + 8 * r: 0 empty, 3 dirt, 8 a boulder, 6 a diamond, 4 a wall, 1 the exit.
state cave = [0; 64];
