  3, 3, 4, 3, 3, 3, 3, 3, 3, 6, 4, 3, 3, 8, 0, 0, 3, 3, 4, 3, 3, 3, 3, 3,
  3, 3, 3, 3, 3, 3, 6, 3, 4, 4, 4, 4, 4, 4, 4, 1];
