}

// Every boulder over an empty square falls as far as it can, from the bottom row up.
fn fall() {
  for k in 0..56 {
    let i = 55 - k;
    if cave[i] == 8 {
      let j = i;
      for s in 0..7 {
        if j + 8 < 64 && cave[j + 8] == 0 && j + 8 != me { j += 8; }
      }
      if j != i {
        cave[i] = 0;
        cave[j] = 8;
        if j + 8 == me { stop("Game over"); }
      }
    }
  }
}

fn move(dc: int, dr: int) {
  let c = me % 8 + dc;
  let r = me / 8 + dr;
  if !playing || c < 0 || c > 7 || r < 0 || r > 7 { return; }
  let t = r * 8 + c;
  if cave[t] == 4 || cave[t] == 1 && gems < 3 { return; }
  if cave[t] == 8 {
    if dr != 0 || c + dc < 0 || c + dc > 7 || cave[t + dc] != 0 { return; }
    cave[t + dc] = 8;
  }
  if cave[t] == 6 { gems += 1; }
  me = t;
  if cave[t] == 1 {
    stop("You win");
    return;
  }
  cave[t] = 0;
  fall();
}

