state result = "";

fn isRock(i: int) -> bool {
  for k in 0..len(rock) {
    if rock[k] == i { return true; }
  }
  return false;
}

fn isGem(i: int) -> bool {
  for k in 0..len(gem) {
    if gem[k] == i { return true; }
  }
  return false;
}

fn empty(i: int) -> bool { return i < 36 && dug[i] && i != me && !isRock(i) && !isGem(i); }

// Each rock over an empty square falls a square at a time as far as it can; one that has fallen
// and stops on you squashes you.
fn fall() {
  for k in 0..len(rock) {
    let moved = false;
    for s in 0..5 {
      if empty(rock[k] + 6) {
        rock[k] += 6;
        moved = true;
      }
    }
    if moved && rock[k] + 6 == me { result = "Squashed! Game over"; }
  }
}

fn move(dc: int, dr: int) {
  let c = me % 6 + dc;
  let r = me / 6 + dr;
