  dug[me] = true;
  me = r * 6 + c;
  dug[me] = true;
  for k in 0..len(gem) {
    if gem[k] == me {
      remove(gem, k);
      if len(gem) == 0 { result = "You win!"; }
      return;
    }
  }
  fall();
}

