fn begin(n: int) {
  level = n;
  frog = 4;
  if n == 1 {
    fly(0, 1, 1);
    fly(3, 2, 1);
    fly(6, 3, 1);
  } else {
    fly(8, 1, 1);
    fly(2, 2, -1);
    fly(5, 3, 1);
