// The tongue: the lowest fly in the frog's column, else a miss.
fn snap() {
  if speed == 0 { return; }
  let k = -1;
  for i in 0..len(fx) {
    if fx[i] == frog && (k < 0 || fy[i] > fy[k]) { k = i; }
  }
  if k < 0 {
    misses += 1;
    if misses == 3 { stop("Game over"); }
    return;
  }
  remove(fx, k);
  remove(fy, k);
  remove(fd, k);
  score += 1;
  if len(fx) == 0 && level == 1 {
    begin(2);
  } else if len(fx) == 0 {
    stop("You win");
  }
}

