// Hungry hippos: marbles roll along the pen; space or Chomp makes your hippo eat the one in its
// column. The computer's hippo chomps every second. Eat more in 10 seconds.
// icon: ring 12 13 8 dot 9 10 2 dot 15 10 2 line 8 17 16 17
state mx = [0; 0];             // the marbles: column, row (1 to 5) and way (1 right, -1 left)
state my = [0; 0];
state md = [0; 0];
state steps = 0;               // 500 ms steps, 20 in all
state me = 0;
state it = 0;
state speed = 0;               // ms a step; 0 while no game runs
state result = "";

fn marble(x: int, y: int, d: int) {
  push(mx, x);
  push(my, y);
  push(md, d);
}

fn start() {
  clear(mx);
  clear(my);
  clear(md);
  marble(0, 1, 1);
  marble(4, 2, -1);
  marble(1, 3, 1);
  marble(3, 4, -1);
  marble(2, 5, 1);
  steps = 0;
  me = 0;
  it = 0;
  result = "";
  speed = 500;
}

fn finish() {
  speed = 0;
  if me > it {
    result = "You win";
  } else if me < it {
    result = "You lose";
  } else {
    result = "Draw";
  }
}

// The marble in column 2 nearest the top (or the bottom): its index, else -1.
fn nearest(top: bool) -> int {
  let k = -1;
  for i in 0..len(mx) {
    if mx[i] == 2 && (k < 0 || top && my[i] < my[k] || !top && my[i] > my[k]) { k = i; }
  }
  return k;
}

// A hippo eats; whether it got one.
fn eat(top: bool) -> bool {
  let k = nearest(top);
  if k < 0 { return false; }
  remove(mx, k);
  remove(my, k);
  remove(md, k);
  return true;
}

fn chomp() {
  if speed > 0 && eat(false) {
    me += 1;
    if len(mx) == 0 { finish(); }
  }
}

every speed {
  steps += 1;
  for i in 0..len(mx) {
    if mx[i] + md[i] < 0 || mx[i] + md[i] > 4 { md[i] = -md[i]; }
    mx[i] += md[i];
  }
  if steps % 2 == 0 && eat(true) { it += 1; }
  if len(mx) == 0 || steps == 20 { finish(); }
}

on key "space" { chomp(); }

