every 500 {
  if result == "" && !marble {
    ticks -= 1;
    if ticks == 0 { marble = true; }
  }
}

// Player p (0 or 1) chomps.
fn chomp(p: int) {
  if result != "" || !marble { return; }
  score[p] += 1;
  marble = false;
  ticks = 4;
  if score[p] == 5 { result = "Player " + (p + 1) + " wins!"; }
