}

// President against the computer: click a card higher than the pile's top, or Pass to give it
// the lead. The first to play all their cards wins.
// icon: loop 4 6 12 4 15 18 7 20 loop 11 5 19 3 21 17 14 19 line 8 10 10 16
state mine = [2, 3, 6, 8, 9];
state its = [1, 4, 5, 7, 7];
state top = 0;                 // the pile's top card, 0 while it is clear
state result = "";

fn deal() {
  let a = [2, 3, 6, 8, 9];
  let b = [1, 4, 5, 7, 7];
  clear(mine);
  clear(its);
  for i in 0..5 {
    push(mine, a[i]);
    push(its, b[i]);
  }
  top = 0;
  result = "";
}

// The computer's turn: its lowest card that beats the top (any card when it leads), else it
// passes and the pile clears for me. Its hand is kept lowest first.
fn answer() {
  for i in 0..len(its) {
    if its[i] > top {
      top = its[i];
      remove(its, i);
      if len(its) == 0 { result = "The computer wins"; }
      return;
    }
  }
  top = 0;
}

fn play(i: int) {
  if result != "" || mine[i] <= top { return; }
  top = mine[i];
  remove(mine, i);
  if len(mine) == 0 {
    result = "You win!";
    return;
  }
  answer();
}

fn pass() {
  if result != "" || top == 0 { return; }
  top = 0;
  answer();
}

fn pile() -> string {
  if top == 0 { return "clear"; }
  return "" + top;
}

