// Sushi draft: tap a card to take it; the computer takes its first, then you swap hands. Wasabi
// triples the next nigiri, tempura pairs, sashimi threes and dumplings add up.
// icon: ring 12 12 9 dot 12 12 4
state mine = [""; 0];          // the hand I hold
state its = [""; 0];
state got = [""; 0];           // the cards taken
state took = [""; 0];
state playing = false;
state result = "";

fn nigiri(c: string) -> int {
  if c == "Egg" { return 1; }
  if c == "Salmon" { return 2; }
  if c == "Squid" { return 3; }
  return 0;
}

fn dumplings(n: int) -> int {
  if n >= 5 { return 15; }
  return n * (n + 1) / 2;
}

// The score of my cards taken (me) or the computer's.
fn points(me: bool) -> int {
  let cards = took;
  if me { cards = got; }
  let s = 0;
  let wasabi = 0;
  let tempura = 0;
  let sashimi = 0;
  let dumpling = 0;
  for i in 0..len(cards) {
    let c = cards[i];
    if c == "Wasabi" { wasabi += 1; }
    if nigiri(c) > 0 && wasabi > 0 {
      s += 3 * nigiri(c);
      wasabi -= 1;
    } else {
      s += nigiri(c);
    }
    if c == "Tempura" { tempura += 1; }
    if c == "Sashimi" { sashimi += 1; }
    if c == "Dumpling" { dumpling += 1; }
  }
  return s + tempura / 2 * 5 + sashimi / 3 * 10 + dumplings(dumpling);
}

fn start() {
  mine = ["Tempura", "Squid", "Wasabi", "Sashimi", "Egg", "Dumpling"];
  its = ["Salmon", "Tempura", "Sashimi", "Dumpling", "Sashimi", "Wasabi"];
  clear(got);
  clear(took);
  result = "";
  playing = true;
}

fn pick(i: int) {
  push(got, mine[i]);
  remove(mine, i);
  push(took, its[0]);
  remove(its, 0);
  let held = mine;
  mine = its;
  its = held;
  if len(mine) == 0 {
    playing = false;
    if points(true) > points(false) { result = "You win"; }
    if points(true) < points(false) { result = "You lose"; }
    if points(true) == points(false) { result = "A tie"; }
  }
}

