fn tint(h: int) -> int {
  if h == 0 { return 0; }
  if h <= 2 { return 1; }
  if h == 3 { return 3; }
  return 2;
}

fn treat(b: int) {
  if !begun || over || energy < 1 || health[b] == 0 { return; }
  energy -= 1;
  health[b] += 1;
  if health[b] >= 5 {
    health[b] = 0;
    saved += 1;
  }
}

fn arrive() {
  for b in 0..4 {
    if health[b] == 0 {
      health[b] = 2;
      return;
    }
  }
}

fn reset() {
  health = [2, 3, 4, 1];
  time = 0;
  energy = 3;
  saved = 0;
  lost = 0;
  speed = 0;
  begun = false;
  over = false;
