every speed {
  time += 1;
  if time % 2 == 0 { energy = min(5, energy + 1); }
  if time % 3 == 0 {
    for b in 0..4 {
      if health[b] > 0 {
        health[b] -= 1;
        if health[b] == 0 { lost += 1; }
      }
    }
  }
  if time % 4 == 0 { arrive(); }
  if lost >= 3 {
    over = true;
    speed = 0;
  }
}

