// Settlers: every 2 seconds each settlement gathers from the land beside it (forest wood, hills
// brick, fields grain). Tap a square next to one to build there for 1 of each; 6 settlements win.
// icon: fill 4 20 4 12 12 5 20 12 20 20 loop 10 20 10 14 14 14 14 20
state land = [2, 2, 3, 3, 1,  2, 3, 3, 1, 1,  2, 2, 3, 1, 3,  3, 2, 2, 1, 3,  3, 3, 2, 2, 1];
state towns = [12];          // the squares with a settlement
state wood = 1;
state brick = 1;
state grain = 1;
state time = 0;
state speed = 0;             // 1000 while the clock runs
state begun = false;
state won = false;

fn town(i: int) -> bool {
  for k in 0..len(towns) {
    if towns[k] == i { return true; }
  }
  return false;
}

fn near(i: int, j: int) -> bool { return abs(i % 5 - j % 5) + abs(i / 5 - j / 5) == 1; }

fn beside(i: int) -> bool {
  for k in 0..len(towns) {
    if near(towns[k], i) { return true; }
  }
  return false;
}

fn gather(j: int) {
  if town(j) { return; }
  if land[j] == 2 { wood += 1; }
  if land[j] == 1 { brick += 1; }
  if land[j] == 3 { grain += 1; }
}

fn harvest() {
  for k in 0..len(towns) {
    for j in 0..25 {
      if near(towns[k], j) { gather(j); }
    }
  }
}

fn build(i: int) {
  if !begun || won || town(i) || !beside(i) || wood < 1 || brick < 1 || grain < 1 { return; }
  wood -= 1;
  brick -= 1;
  grain -= 1;
  push(towns, i);
  if len(towns) >= 6 {
    won = true;
    speed = 0;
  }
}

fn reset() {
  clear(towns);
  push(towns, 12);
  wood = 1;
  brick = 1;
  grain = 1;
  time = 0;
  speed = 0;
  begun = false;
  won = false;
}

every speed {
  time += 1;
  if time % 2 == 0 { harvest(); }
}

// The island, 5 x 5 squares of 24 units; settlements purple.
fn scene() {
  let b = [0; 25];
  for i in 0..25 { b[i] = land[i]; }
  for k in 0..len(towns) { b[towns[k]] = 5; }
  pixels(b, 0, 0, 5, 24);
  if won { text("You win", 60, 4, 8, 9); }
}

label "Settlers";
label "Wood " + wood + "   Brick " + brick + "   Grain " + grain;
label "Points " + len(towns) + "   Time " + time;
canvas 120, 120, scene() {
  if x < 120 && y < 120 { build(y / 24 * 5 + x / 24); }
}
if !begun {
  button "Start" {
    begun = true;
    speed = 1000;
  }
}
if won { button "New game" { reset(); } }

