// Penguin launch: Hit (space) when the power meter is high; the penguin flies on, slowing 1 each
// step. Three tries; your best distance counts.
// icon: fill 9 6 15 6 17 14 15 21 9 21 7 14 dot 12 13 3 line 16 9 21 7
state power = 0;
state up = true;             // the meter rising
state speed = 0;             // the penguin's speed in flight
state flying = false;
state distance = 0;
state best = 0;
state tries = 3;
state tick = 0;              // 200 while anything moves
state begun = false;

fn land() {
  flying = false;
  tries -= 1;
  best = max(best, distance);
  power = 0;
  up = true;
  if tries == 0 { tick = 0; }
}

fn hit() {
  if !begun || flying || tries == 0 { return; }
  distance = 0;
  speed = power;
  flying = true;
  if speed == 0 { land(); }
}

fn swing() {
  if up {
    power += 1;
    if power == 10 { up = false; }
  } else {
    power -= 1;
    if power == 0 { up = true; }
  }
}

every tick {
  if flying {
    distance += speed;
    speed -= 1;
    if speed == 0 { land(); }
  } else {
    swing();
  }
}

on key "space" { hit(); }

// The ice, the yeti, the penguin along its way, higher while it is fast.
fn scene() {
  rect(0, 50, 160, 10, 6);
  rect(4, 30, 10, 20, 7);
  circle(9, 26, 5, 7);
  let px = 20 + distance * 2;
  let py = 46 - speed * 3;
  if !flying { px = 20; py = 46; }
  circle(px, py, 3, 9);
  if begun && tries == 0 { text("Game over", 80, 10, 10, 11); }
}

label "Penguin launch";
label "Power " + power + "   Distance " + distance + "   Best " + best + "   Tries left " + tries;
canvas 160, 60, scene();
row {
  if !begun {
    button "Start" {
      begun = true;
      tick = 200;
    }
  }
  button "Hit" { hit(); }
  if begun && tries == 0 {
    button "New game" {
      power = 0;
      up = true;
      distance = 0;
      best = 0;
      tries = 3;
      begun = false;
    }
  }
}

// Penguin launch: set the power with + and -, then Launch; the penguin flies the power in meters
// the first second, a meter less each second after. Three tries; the best counts.
// icon: fill 9 6 15 6 17 14 15 21 9 21 7 14 dot 12 13 3 line 16 9 21 7
state power = 5;
state speed = 0;
state tick = 0;              // 1000 while it flies
state meters = 0;
state best = 0;
state tries = 3;

every tick {
  meters += speed;
  speed -= 1;
  if speed == 0 {
    tick = 0;
    best = max(best, meters);
  }
}

// The penguin along the ice.
fn scene() { circle(10 + meters * 2 / 5, 44, 4, 9); }

label "Penguin launch";
label "Power " + power;
label "Distance " + meters + " m   Best " + best + " m   Tries left " + tries;
canvas 160, 60, scene();
if tick == 0 && tries > 0 {
  row {
    button "-" { power = max(1, power - 1); }
    button "+" { power = min(10, power + 1); }
    button "Launch" {
      tries -= 1;
      meters = 0;
      speed = power;
      tick = 1000;
    }
  }
}
if tick == 0 && tries == 0 { label "No tries left"; }

// Lair keeper: dig out from the heart (1 mana a square); gold veins give 10 gold; summon imps (10
// gold) to mine and to fight the heroes who raid every 5 seconds. Lose the heart's 3 lives: fallen.
// icon: fill 3 21 3 10 12 3 21 10 21 21 fill 9 21 9 14 15 14 15 21
state dug = [false; 36];     // the squares dug to floor
state gold = 0;
state mana = 3;
state imps = 0;
state heart = 3;
state time = 0;
state speed = 0;             // 1000 while the clock runs
state begun = false;
state fallen = false;

fn vein(i: int) -> bool { return i == 8 || i == 22 || i == 25; }

fn open(c: int, r: int) -> bool {
  if c < 0 || c > 5 || r < 0 || r > 5 { return false; }
  return r * 6 + c == 0 || dug[r * 6 + c];
}

fn dig(i: int) {
  if !begun || fallen || mana < 1 || i == 0 || dug[i] { return; }
  let c = i % 6;
  let r = i / 6;
  if !(open(c - 1, r) || open(c + 1, r) || open(c, r - 1) || open(c, r + 1)) { return; }
  dug[i] = true;
  mana -= 1;
  if vein(i) { gold += 10; }
}

fn reset() {
  for i in 0..36 { dug[i] = false; }
  gold = 0;
  mana = 3;
  imps = 0;
  heart = 3;
  time = 0;
  speed = 0;
  begun = false;
  fallen = false;
}

every speed {
  time += 1;
  mana = min(5, mana + 1);
  gold += imps;
  if time % 5 == 0 {
    if imps > 0 {
      imps -= 1;
    } else {
      heart -= 1;
    }
  }
  if heart == 0 {
    fallen = true;
    speed = 0;
  }
}

// The lair, 6 x 6 squares of 20 units: rock purple, veins yellow, the heart red.
fn scene() {
  let b = [0; 36];
  for i in 0..36 {
    b[i] = 5;
    if vein(i) { b[i] = 3; }
    if dug[i] { b[i] = 0; }
  }
  b[0] = 1;
  pixels(b, 0, 0, 6, 20);
  if fallen { text("Lair fallen", 60, 114, 8, 9); }
}

label "Lair keeper";
label "Gold " + gold + "   Mana " + mana + "   Imps " + imps + "   Heart " + heart + "   Time " + time;
canvas 120, 120, scene() {
  if x < 120 && y < 120 { dig(y / 20 * 6 + x / 20); }
}
row {
  button "Summon imp" {
    if begun && !fallen && gold >= 10 {
      gold -= 10;
      imps += 1;
    }
  }
  if !begun {
    button "Start" {
      begun = true;
      speed = 1000;
    }
  }
  if fallen { button "New game" { reset(); } }
}

// Lair keeper: Dig rooms (each earns a gold a second), Hire monsters (10 gold). Every 10 seconds
// a hero raids: a monster dies holding him off, or he steals 10 gold.
