// Kaiju dice: set the six dice to what you rolled (tap one to turn it), then End turn scores them
// for the monster playing. 0 health loses; 20 stars win.
// icon: loop 4 4 20 4 20 20 4 20 dot 9 9 2 dot 15 15 2 dot 15 9 2 dot 9 15 2
state faces = ["1", "2", "3", "Claw", "Heart", "Bolt"];
state dice = [0, 0, 0, 0, 0, 0];      // each die's face, an index into faces
state shown = ["1", "1", "1", "1", "1", "1"];
state health = [10, 10];
state stars = [0, 0];
state energy = [0, 0];
state names = ["Gorg", "Vex"];
state turn = 0;
state winner = "";

fn count(f: int) -> int {
  let n = 0;
  for i in 0..6 {
    if dice[i] == f { n += 1; }
  }
  return n;
}

fn reset() {
  for i in 0..6 {
    dice[i] = 0;
    shown[i] = "1";
  }
}

fn score() {
  if winner != "" { return; }
  let me = turn;
  let foe = 1 - turn;
  for f in 0..3 {
    if count(f) >= 3 { stars[me] += f + 1 + count(f) - 3; }
  }
  health[foe] = max(0, health[foe] - count(3));
  health[me] = min(10, health[me] + count(4));
  energy[me] += count(5);
  if health[foe] == 0 || stars[me] >= 20 { winner = names[me]; }
  reset();
  turn = foe;
}

fn again() {
  reset();
  for m in 0..2 {
    health[m] = 10;
    stars[m] = 0;
    energy[m] = 0;
  }
  turn = 0;
  winner = "";
}

fn stats(m: int) -> string {
  return names[m] + " health " + health[m] + "   " + names[m] + " stars " + stars[m] + "   " + names[m] + " energy " + energy[m];
}

label "Kaiju dice";
label stats(0);
label stats(1);
if winner == "" { label names[turn] + " to play"; } else { label winner + " wins!"; }
grid 6, dice, shown {
  dice[cell] = (dice[cell] + 1) % 6;
  shown[cell] = faces[dice[cell]];
}
row {
  button "End turn" { score(); }
  button "New game" { again(); }
}

// Line rider: tap or drag to lay track, then Ride: the sled falls over nothing, runs right on
// track and climbs a step; it crashes on the bottom or a wall. Clear erases the track.
// icon: line 2 8 9 14 16 15 22 11 fill 7 6 13 6 12 9 8 9 line 6 11 14 11
state track = [0; 240];
state sc = 0;               // the sled's column and row
state sr = 0;
state speed = 0;            // ms a step; 0 between rides
state result = "";

fn at(c: int, r: int) -> int { return r * 20 + c; }

fn free(c: int, r: int) -> bool {
  return c >= 0 && c < 20 && r >= 0 && r < 12 && track[at(c, r)] == 0;
}

fn stop(what: string) {
  result = what;
  speed = 0;
}

every speed {
  if sr == 11 {
    stop("Crashed");
  } else if track[at(sc, sr + 1)] == 0 {
    sr += 1;
  } else if sc == 19 {
    stop("Finished!");
  } else if free(sc + 1, sr) {
    sc += 1;
  } else if free(sc + 1, sr - 1) {
    sc += 1;
    sr -= 1;
  } else {
    stop("Crashed");
  }
}

fn scene() {
  let b = [-1; 240];
  for i in 0..240 {
    if track[i] > 0 { b[i] = 2; }
  }
  b[at(sc, sr)] = 1;
  pixels(b, 0, 0, 20, 8);
}

label "Line rider";
label "Distance " + sc + "   " + result;
canvas 160, 96, scene() {
  if speed == 0 { track[at(x / 8, y / 8)] = 1; }
}
row {
  if speed == 0 {
    button "Ride" {
      sc = 0;
      sr = 0;
      result = "";
      speed = 100;
    }
  }
  button "Clear" {
    if speed == 0 {
      for i in 0..240 { track[i] = 0; }
    }
  }
}

// Gem merchant: buy gems where they are cheap, travel (a day), sell where they are dear. Prices
// rise by 1 a day; the bag holds 10; ten days.
// icon: fill 7 4 17 4 21 9 12 21 3 9 line 3 9 21 9 line 9 4 12 21 15 4
state towns = ["Port", "Mine", "Palace"];
state gems = ["Ruby", "Emerald", "Sapphire"];
state prices = [10, 20, 30, 5, 10, 40, 20, 35, 25];   // town by town
state held = [0, 0, 0];
state town = 0;
state day = 1;
state gold = 100;
state over = false;

fn price(g: int) -> int { return prices[town * 3 + g] + day - 1; }

fn bag() -> int { return held[0] + held[1] + held[2]; }

fn buy(g: int) {
  if !over && gold >= price(g) && bag() < 10 {
    gold -= price(g);
    held[g] += 1;
  }
}

fn sell(g: int) {
  if !over && held[g] > 0 {
    gold += price(g);
    held[g] -= 1;
  }
}

fn go(t: int) {
  if over || t == town { return; }
  if day == 10 {
    over = true;
  } else {
    town = t;
    day += 1;
  }
}

fn again() {
  for g in 0..3 { held[g] = 0; }
  town = 0;
  day = 1;
  gold = 100;
  over = false;
}

fn map() {
  line(25, 25, 125, 25, 2, 10);
  for t in 0..3 {
    let c = 8;
    if t == town { c = 3; }
    circle(25 + t * 50, 25, 14, c);
  }
}

label "Gem merchant";
label "Day " + day + "   Gold " + gold + "   In " + towns[town];
label "Rubies " + held[0] + "   Emeralds " + held[1] + "   Sapphires " + held[2];
label "Today: Ruby " + price(0) + ", Emerald " + price(1) + ", Sapphire " + price(2);
canvas 150, 50, map();
for g in 0..3 {
  row {
    button "Buy " + gems[g] { buy(g); }
    button "Sell " + gems[g] { sell(g); }
  }
}
row { for t in 0..3 { button towns[t] { go(t); } } }
if over {
  label "Game over: " + gold + " gold";
  button "New game" { again(); }
}

